// bewegungtest.cpp - Paket bewegung (rc601): NPCs laufen, drehen sich und
// fallen wie im Spiel.
//
// Gemeldet: "NPCs don't walk to waypoints correctly. Looks like they ignore
// WALK_SPEED and RUN_SPEED", "NPCs don't rotate with their YAW_SPEED. They
// just instantly turn", "NPCs aren't affected by gravity".
//
// Jede Probe ist aus einer Stelle im Quelltext der Engine abgeleitet
// (MovieDuels-SJE-SP code/game, dort wo es von OpenJK abweicht, steht es
// dabei). Reine Proben: kein Fenster, kein Ton, keine Spieldaten.
//
// Mit Argumenten (intro_jedi.txt, md_twj_jedi.ent) zusaetzlich gegen die
// echten Daten der Mod.
#include "bhed/ablauf.h"
#include "bhed/bspgeo.h"
#include "bhed/kollision.h"
#include "bhed/navlauf.h"
#include "bhed/regelwerk.h"
#include "bhed/scene.h"
#include "bhed/script.h"
#include "bhed/wegpunkte.h"

#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstddef>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <functional>
#include <iterator>
#include <map>
#include <memory>
#include <set>
#include <sstream>
#include <string>
#include <tuple>
#include <vector>

using namespace bhed;

namespace {

int fehler = 0;

void pruefe(bool ok, const std::string& was) {
    std::printf("  %s  %s\n", ok ? "ok  " : "FEHL", was.c_str());
    if (!ok) { ++fehler; }
}

bool nah(double a, double b, double eps) { return std::fabs(a - b) <= eps; }

MapData karte(const char* text) {
    MapData m;
    parseEntities(text, m.entities);
    return m;
}

Script lies(const std::string& text) {
    Script s;
    std::vector<Diag> d;
    (void)readScript("//Generated by BehavEd\r\n" + text, s, d);
    return s;
}

Scene szene(const std::string& koerper, const MapData& m, const SzenenHilfe* h = nullptr) {
    return buildScene(lies(koerper), m, h);
}

// affect ( "held" ) { ... } um eine Befehlsliste.
std::string held(const std::string& befehle) {
    return "affect ( \"held\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n" + befehle + "}\r\n";
}
std::string set(const std::string& typ, const std::string& wert) {
    return "\tset ( /*@SET_TYPES*/ \"" + typ + "\", \"" + wert + "\" );\r\n";
}
std::string setZahl(const std::string& typ, const std::string& wert) {
    return "\tset ( /*@SET_TYPES*/ \"" + typ + "\", " + wert + " );\r\n";
}
std::string warte(double ms) {
    char b[64];
    std::snprintf(b, sizeof(b), "\twait ( %.3f );\r\n", ms);
    return b;
}

const ActorStep* letzterWeg(const Actor& a) {
    const ActorStep* w = nullptr;
    for (const ActorStep& st : a.steps) {
        if (st.kind == ActorStep::Kind::WalkTo) { w = &st; }
    }
    return w;
}
const ActorStep* ersterWeg(const Actor& a) {
    for (const ActorStep& st : a.steps) {
        if (st.kind == ActorStep::Kind::WalkTo) { return &st; }
    }
    return nullptr;
}
const Actor* figur(const Scene& s, const std::string& name) {
    for (const Actor& a : s.actors) {
        if (a.name == name) { return &a; }
    }
    return nullptr;
}

// Die Zeit, zu der ein Befehl im flachen Skript liegt (wie ablauftest.cpp).
double zeitVon(const Ablauf& a, const std::string& spur, const std::string& name, const std::string& arg) {
    const auto such = [&](const std::vector<Node>& ns) -> double {
        double t = 0.0;
        for (const Node& n : ns) {
            if (n.name == "wait") {
                t += std::atof(n.args[0].text.c_str());
                continue;
            }
            if (n.name == name && (arg.empty() || (!n.args.empty() && n.args.back().text == arg) ||
                                   (!n.args.empty() && n.args[0].text == arg))) {
                return t;
            }
        }
        return -1.0;
    };
    if (spur.empty()) { return such(a.flach.nodes); }
    for (const Node& n : a.flach.nodes) {
        if (n.name == "affect" && !n.args.empty() && n.args[0].text == spur) { return such(n.children); }
    }
    return -1.0;
}

// =====================================================================
// 1) Laufen
// =====================================================================
const char* const kKarte1 =
    "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"held\"\n\"NPC_type\" \"jedi\"\n"
    "\"origin\" \"0 0 100\"\n\"angle\" \"90\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"ziel1\"\n\"origin\" \"380 0 100\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"ziel2\"\n\"origin\" \"0 300 100\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"zielR\"\n\"origin\" \"380 0 100\"\n\"radius\" \"40\"\n}\n"
    "{\n\"classname\" \"ref_tag\"\n\"targetname\" \"marke\"\n\"origin\" \"380 0 100\"\n}\n"
    "{\n\"classname\" \"waypoint\"\n\"targetname\" \"wp1\"\n\"origin\" \"190 0 100\"\n}\n";

// rc601 (bewegung, Wege wie im Spiel): ein Weg ist nicht mehr gehDauerMs,
// sondern planeLauf (STEER + Pmove je Denkbild). Die Proben vergleichen darum
// mit einem Bezugslauf, den die Engine genauso rechnen muss: dieselben Werte in
// anderer Reihenfolge im selben Bild, oder eine Zahl aus PM_Friction.
double ankunftVon(const Actor& a) {
    for (const ActorStep& st : a.steps) {
        if (st.kind == ActorStep::Kind::WalkTo && st.ankunftMs >= 0.0) { return st.ankunftMs; }
    }
    return -1.0;
}

void laufenSzene() {
    std::printf("\n== Laufen: Szene (scene.cpp) ==\n");
    const MapData m = karte(kKarte1);
    // Der Bezug: gehen mit 90 nach ziel1 (380 weit, direkt - wp1 ist der
    // naechste Knoten, ziel1 sein Nachbar: SafeToGoTo im ersten Denkbild ja).
    const Scene bezug = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1")), m);
    const double geh90 = ankunftVon(bezug.actors.front());
    pruefe(geh90 > 3000.0 && geh90 < 6000.0, "Bezug: 380 weit mit 90 kommt an (" + std::to_string(geh90) + " ms)");

    // A1 - der gemeldete Fall: Gangart und Tempo stehen NACH dem Wegziel im
    // selben Bild (intro_jedi.txt:147-149). STEER::Activate liest beides
    // in jedem Denkbild neu (g_navigator.cpp:3990-3997) - im Spiel geht die
    // Figur also mit 45, nicht mit 300: genau wie mit beidem davor.
    {
        const Scene s = szene(held(set("SET_NAVGOAL", "ziel1") + set("SET_WALKING", "true") +
                                   setZahl("SET_WALKSPEED", "45.000")), m);
        const Scene b = szene(held(set("SET_WALKING", "true") + setZahl("SET_WALKSPEED", "45.000") +
                                   set("SET_NAVGOAL", "ziel1")), m);
        const ActorStep* w = letzterWeg(s.actors.front());
        pruefe(w != nullptr && w->text == "BOTH_WALK1", "A1 SET_WALKING nach SET_NAVGOAL im selben Bild: gehen");
        const double t1 = ankunftVon(s.actors.front());
        const double t2 = ankunftVon(b.actors.front());
        pruefe(t1 > geh90 && nah(t1, t2, 0.5),
               "A1 ... mit SET_WALKSPEED 45 danach wie davor (" + std::to_string(t1) + " / " + std::to_string(t2) + ")");
    }
    // A1b - dasselbe mit RUNNING und RUNSPEED (cin2_jedi.txt:75-77).
    {
        const Scene s = szene(held(set("SET_NAVGOAL", "ziel1") + set("SET_RUNNING", "true") +
                                   setZahl("SET_RUNSPEED", "75.000")), m);
        const Scene b = szene(held(set("SET_RUNNING", "true") + setZahl("SET_RUNSPEED", "75.000") +
                                   set("SET_NAVGOAL", "ziel1")), m);
        const double t1 = ankunftVon(s.actors.front());
        pruefe(t1 > 0.0 && nah(t1, ankunftVon(b.actors.front()), 0.5),
               "A1b SET_RUNSPEED 75 nach SET_NAVGOAL: laufen mit 75 (" + std::to_string(t1) + ")");
    }
    // A2 - SET_NAVGOAL "NULL" haelt an: goalEntity = NULL (Q3_Interface.cpp:2140).
    // Danach kein STEER mehr, nur PM_Friction: aus 90 rollt sie in drei
    // Denkbildern aus (90 -> 60 -> 30 -> 0, also 3 + 1,5 = 4,5 Einheiten).
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(3000.0) +
                                   set("SET_NAVGOAL", "NULL")), m);
        const Actor& a = s.actors.front();
        const ActorState bei3 = a.at(3000.0);
        const ActorState spaet = a.at(20000.0);
        pruefe(bei3.pos[0] > 10.0F && bei3.pos[0] < 370.0F, "A2 bei 3 s unterwegs");
        pruefe(nah(spaet.pos[0] - bei3.pos[0], 4.5, 0.01) && nah(a.at(3150.0).pos[0], spaet.pos[0], 0.001),
               "A2 NULL: sie rollt 4,5 aus und bleibt stehen (" + std::to_string(spaet.pos[0] - bei3.pos[0]) + ")");
        pruefe(!spaet.moving && spaet.animation == "BOTH_STAND1", "A2 ... und steht (keine Laufanimation)");
    }
    // A2b - "null" klein: Q_stricmp (Q3_Interface.cpp:2137).
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(3000.0) +
                                   set("SET_NAVGOAL", "null")), m);
        pruefe(s.actors.front().at(20000.0).pos[0] < 300.0F, "A2b \"null\" klein haelt ebenfalls an");
    }
    // A3 - ein neues Ziel unterwegs beginnt am AKTUELLEN Ort, ohne Sprung, und
    // aus der laufenden Geschwindigkeit (STEER::Activate liest ps.velocity).
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(3000.0) +
                                   set("SET_NAVGOAL", "ziel2")), m);
        const Actor& a = s.actors.front();
        const ActorState v = a.at(2990.0);
        const ActorState n = a.at(3010.0);
        const double sprung = std::hypot(n.pos[0] - v.pos[0], n.pos[1] - v.pos[1]);
        pruefe(sprung < 5.0, "A3 neues Ziel unterwegs: kein Sprung (" + std::to_string(sprung) + ")");
        const ActorStep* w1 = ersterWeg(a);
        pruefe(w1 != nullptr && nah(w1->endMs, 3000.0, 0.5) && w1->teilweg, "A3 das erste Stueck endet beim Schnitt");
        // Das neue Ziel liegt hinten links. Aus dem Stand ginge es sofort dorthin
        // (x nimmt ab); aus voller Fahrt nach Osten traegt die alte
        // Geschwindigkeit sie noch ein Stueck weiter nach Osten - STEER lenkt
        // mit hoechstens 150 je Denkbild um, PM_Friction nimmt nur 30.
        const double schritt = a.at(3050.0).pos[0] - a.at(3000.0).pos[0];
        pruefe(schritt > 1.0, "A3 das zweite Stueck faehrt aus der alten Geschwindigkeit weiter (x +" +
                                  std::to_string(schritt) + ")");
        const ActorState e = a.at(60000.0);
        pruefe(std::fabs(e.pos[0]) < 20.0F && std::fabs(e.pos[1] - 300.0F) < 20.0F,
               "A3 und kommt am neuen Ziel an (" + std::to_string(e.pos[0]) + " " + std::to_string(e.pos[1]) + ")");
    }
    // A4 - ein anderes Tempo unterwegs gilt ab sofort.
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(2000.0) +
                                   setZahl("SET_WALKSPEED", "45.000")), m);
        pruefe(s.actors.front().at(geh90).pos[0] < bezug.actors.front().at(geh90).pos[0] - 20.0F,
               "A4 SET_WALKSPEED 45 unterwegs bremst den Rest des Weges");
    }
    // A5 - .npc walkSpeed 0 ist gueltig: NPC_ParseParms verwirft nur n < 0
    // (NPC_stats.cpp:3720-3735). Die Figur steht.
    {
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tkyle\n\twalkSpeed\t0\n\trunSpeed\t0\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1")), m, &h);
        pruefe(nah(s.actors.front().at(60000.0).pos[0], 0.0, 1.0), "A5 .npc walkSpeed 0: die Figur bleibt stehen");
    }
    // A5b - COM_ParseInt: "55.9" ist 55 (atoi).
    {
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tkyle\n\twalkSpeed\t55.9\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1")), m, &h);
        const Scene b = szene(held(set("SET_WALKING", "true") + setZahl("SET_WALKSPEED", "55") + set("SET_NAVGOAL", "ziel1")), m);
        const double t = ankunftVon(s.actors.front());
        pruefe(t > 0.0 && nah(t, ankunftVon(b.actors.front()), 0.5), "A5b .npc walkSpeed 55.9 gilt als 55");
    }
    // A6 - dem Ablauf das Tempo beim Spawnen geben, nicht das letzte aus dem
    // Skript (gui/app_view3d.cpp, prepareScene).
    {
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tkyle\n\twalkSpeed\t55\n\trunSpeed\t200\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(30000.0) +
                                   setZahl("SET_WALKSPEED", "0.000") + setZahl("SET_RUNSPEED", "0.000")),
                              m, &h);
        const auto tempo = ablaufTempo(s);
        pruefe(nah(tempo("held", true), 55.0, 0.01) && nah(tempo("held", false), 200.0, 0.01),
               "A6 Ablauf bekommt die .npc-Tempi beim Spawnen (55/200), nicht die letzten aus dem Skript");
        pruefe(tempo("niemand", true) < 0.0F, "A6 unbekannte Figur: -1");
    }
    // A6b - SET_WALKSPEED ist atoi (Q3_Interface.cpp:9070): "55.7" ist 55.
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + setZahl("SET_WALKSPEED", "55.700") +
                                   set("SET_NAVGOAL", "ziel1")), m);
        const Scene b = szene(held(set("SET_WALKING", "true") + setZahl("SET_WALKSPEED", "55") + set("SET_NAVGOAL", "ziel1")), m);
        const double t = ankunftVon(s.actors.front());
        pruefe(t > 0.0 && nah(t, ankunftVon(b.actors.front()), 0.5), "A6b SET_WALKSPEED 55.7 gilt als 55");
    }
    // A6c - "TRUE" gross: Q_stricmp (Q3_Interface.cpp:9345).
    {
        const Scene s = szene(held(set("SET_WALKING", "TRUE") + set("SET_NAVGOAL", "ziel1")), m);
        const ActorStep* w = letzterWeg(s.actors.front());
        pruefe(w != nullptr && w->text == "BOTH_WALK1", "A6c SET_WALKING \"TRUE\" gross schaltet gehen ein");
    }
    // A7 - der Radius des Ziels: waypoint_navgoal "radius" (g_nav.cpp:262),
    // ref_tag 16 (g_ref.cpp:396). STEER::Reached sieht die Ankunft, sobald
    // der Ort nach dem letzten Pmove naeher als der Radius ist (oder das Ziel
    // im Kasten liegt) - mit 40 also 40 vor dem Ziel.
    {
        pruefe(nah(navZielAufloesen(m, "zielR").radius, 40.0, 0.01) && nah(navZielAufloesen(m, "marke").radius, 16.0, 0.01),
               "A7 Radien: waypoint_navgoal radius 40, ref_tag 16");
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "zielR")), m);
        const Actor& a = s.actors.front();
        const double t = ankunftVon(a);
        const float vorher = 380.0F - a.at(t - kNavDenkMs).pos[0];
        const float davor = 380.0F - a.at(t - 2.0 * kNavDenkMs).pos[0];
        // (Spaeter da als mit 12: Persue bremst ab 4 * Radius = 160.)
        pruefe(t > 0.0 && vorher < 40.0F && davor >= 40.0F,
               "A7 waypoint_navgoal mit radius 40: angekommen bei " + std::to_string(vorher) + " (davor " +
                   std::to_string(davor) + ")");
    }
    // A7b - TAG_Find sucht ohne Gross/klein (g_ref.cpp:161 Q_strlwr).
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ZIEL1")), m);
        pruefe(letzterWeg(s.actors.front()) != nullptr, "A7b SET_NAVGOAL \"ZIEL1\" findet ziel1");
    }
    // A8 - NULL und SET_ORIGIN: kein Laufband (die Figur laeuft nicht auf der Stelle).
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(2000.0) +
                                   set("SET_NAVGOAL", "NULL") + set("SET_ORIGIN", "0 500 100")), m);
        const ActorState st = s.actors.front().at(2100.0);
        pruefe(!st.moving && std::fabs(st.pos[1] - 500.0F) < 0.5F && st.animation == "BOTH_STAND1",
               "A8 NULL + SET_ORIGIN: steht am neuen Ort, ohne Laufanimation");
    }
    // A8b - SET_ORIGIN unterwegs: G_SetOrigin laesst goalEntity stehen
    // (g_utils.cpp:1585) - die Figur laeuft vom neuen Ort weiter zum Ziel.
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(2000.0) +
                                   set("SET_ORIGIN", "100 200 100")), m);
        const Actor& a = s.actors.front();
        const ActorState st = a.at(2500.0);
        pruefe(st.moving && st.pos[0] > 100.0F && st.pos[1] < 200.0F && st.pos[1] > 100.0F,
               "A8b SET_ORIGIN unterwegs: sie laeuft vom neuen Ort aus weiter (" + std::to_string(st.pos[0]) + " " +
                   std::to_string(st.pos[1]) + ")");
        const ActorState e = a.at(60000.0);
        pruefe(std::fabs(e.pos[0] - 380.0F) < 20.0F && std::fabs(e.pos[1]) < 20.0F, "A8b ... bis zum Ziel");
    }
    // A8c - rc605 (fix605): SET_ORIGIN / SET_ANGLES mit $tag( "name", ORIGIN|ANGLES )$.
    // CTaskManager::Get schreibt den Ort des TAGs als "%f %f %f" (TaskManager.cpp:
    // 637-652 OpenJK); ohne TAG scheitert der set (TASK_FAILED). Bis rc604 las die
    // Szene den Ausdruck als Zahlen - 0 0 0 (npc_rancor1 in t2_rancor fiel vom
    // Kartenursprung).
    {
        const MapData mt = karte((std::string(kKarte1) +
                                  "{\n\"classname\" \"ref_tag\"\n\"targetname\" \"blick\"\n\"origin\" \"-50 60 100\"\n"
                                  "\"angle\" \"135\"\n}\n").c_str());
        const Scene s = szene(held(warte(500.0) + setZahl("SET_ORIGIN", "$tag( \"MARKE\", ORIGIN )$") +
                                   setZahl("SET_ANGLES", "$tag( \"blick\", ANGLES )$") + warte(500.0) +
                                   setZahl("SET_ORIGIN", "$tag( \"fehlt\", ORIGIN )$") +
                                   setZahl("SET_ANGLES", "$tag( \"fehlt\", ANGLES )$")),
                              mt);
        const ActorState st = s.actors.front().at(1500.0);
        pruefe(std::fabs(st.pos[0] - 380.0F) < 0.5F && std::fabs(st.pos[1]) < 0.5F && st.pos[2] > 50.0F,
               "A8c SET_ORIGIN $tag( \"MARKE\", ORIGIN )$: steht an der Marke 380 0 (" + std::to_string(st.pos[0]) + " " +
                   std::to_string(st.pos[1]) + " " + std::to_string(st.pos[2]) + ")");
        pruefe(std::fabs(st.angles[1] - 135.0F) < 0.5F,
               "A8c SET_ANGLES $tag( \"blick\", ANGLES )$: Gier 135 (" + std::to_string(st.angles[1]) + "); ein fehlender TAG aendert nichts");
        // Der Ablauf nimmt denselben Ort (Plaene der Figuren beginnen dort).
        AblaufWelt welt;
        welt.karte = &mt;
        const Ablauf ab = simuliereAblauf(lies(held(warte(500.0) + setZahl("SET_ORIGIN", "$tag( \"MARKE\", ORIGIN )$") +
                                                    set("SET_NAVGOAL", "ziel2") + warte(100.0) +
                                                    setZahl("SET_ORIGIN", "$tag( \"held\", ORIGIN )$"))),
                                          "probe", welt);
        bool ok = false;
        bool falsch = false;
        for (const NavAbschnitt& a : ab.laufAbschnitte) {
            ok = ok || (std::fabs(a.start.ort[0] - 380.0F) < 0.5F && a.abMs < 700.0);
            falsch = falsch || (std::fabs(a.start.ort[0]) < 0.5F && a.abMs > 550.0);   // $tag( "held" ) ist kein TAG
        }
        pruefe(ok && !falsch, "A8c Ablauf: der Weg nach ziel2 beginnt an der Marke 380 0; $tag( \"held\" ) versetzt nicht");
    }
    // A9 - BUTTON_WALKING: ohne Schalter waehlt das Tempo die Animation
    // (STEER::DeActivate, g_navigator.cpp:4170: mSpeed < walkSpeed + 5).
    {
        const Scene s = szene(held(setZahl("SET_RUNSPEED", "60.000") + set("SET_NAVGOAL", "ziel1")), m);
        const ActorStep* w = letzterWeg(s.actors.front());
        pruefe(w != nullptr && w->text == "BOTH_WALK1", "A9 laufen mit 60 (< walkSpeed+5): die Gehanimation");
        const Scene r = szene(held(set("SET_RUNNING", "true") + setZahl("SET_RUNSPEED", "60.000") +
                                   set("SET_NAVGOAL", "ziel1")), m);
        const ActorStep* w2 = letzterWeg(r.actors.front());
        pruefe(w2 != nullptr && w2->text == "BOTH_RUN1", "A9 mit SET_RUNNING bleibt es die Laufanimation (NPC_ApplyScriptFlags)");
    }
    // A10 - ein unbekanntes Ziel laesst das alte stehen ("can't find NAVGOAL").
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(1000.0) +
                                   set("SET_NAVGOAL", "gibtesnicht")), m);
        pruefe(std::fabs(s.actors.front().at(60000.0).pos[0] - 380.0F) < 20.0F,
               "A10 unbekanntes Ziel: sie laeuft zum alten weiter");
    }
    // A11 - ein waypoint gibt es im Spiel nicht mehr (SP_waypoint ruft
    // G_FreeEntity, g_nav.cpp:197): kein TAG, G_Find findet nichts.
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "wp1")), m);
        pruefe(s.actors.empty() || letzterWeg(s.actors.front()) == nullptr, "A11 SET_NAVGOAL auf einen waypoint: kein Weg");
    }
    // A13 - kill unterwegs schneidet den Weg ab: das letzte Stueck endet beim
    // Tod, keines beginnt danach.
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(2000.0) +
                                   "\tkill ( \"self\" );\r\n"), m);
        const ActorStep* w = letzterWeg(s.actors.front());
        pruefe(w != nullptr && nah(w->endMs, 2000.0, 0.5), "A13 kill unterwegs: der Weg endet beim Tod");
    }
    // Waechter: ein gerader Weg ohne Aenderung ist EIN Schritt (scenetest):
    // bis zum Stillstand nach der Ankunft.
    {
        const Actor& a = bezug.actors.front();
        // Das Stueck endet mit der letzten Bewegung; UpdateGoal sieht die Ankunft
        // im Denkbild danach (am Ort nach dem letzten Pmove).
        pruefe(a.steps.size() == 1U && a.steps.front().lauf && nah(a.steps.front().ankunftMs, geh90, 0.5) &&
                   a.steps.front().endMs <= geh90 && a.steps.front().endMs > geh90 - 100.0,
               "Waechter: ein Weg ohne Aenderung ist ein Schritt bis zur Ankunft (" +
                   std::to_string(a.steps.front().endMs) + " / " + std::to_string(geh90) + ")");
    }
}


// Die Mod selbst: intro_jedi.txt:147-149 (anakin1) und 314-319 (barriss1).
void laufenEchteDaten(const char* skriptDatei, const char* entDatei) {
    std::printf("\n== Laufen: echte Daten (md_twj) ==\n");
    std::ifstream sf(skriptDatei, std::ios::binary);
    std::ostringstream ss;
    ss << sf.rdbuf();
    std::ifstream ef(entDatei, std::ios::binary);
    std::ostringstream es;
    es << ef.rdbuf();
    if (ss.str().empty() || es.str().empty()) {
        std::printf("  (Dateien fehlen - uebersprungen)\n");
        return;
    }
    Script s;
    std::vector<Diag> d;
    (void)readScript(ss.str(), s, d);
    MapData m;
    parseEntities(es.str(), m.entities);
    const Scene sc = buildScene(s, m);
    const Actor* anakin = figur(sc, "anakin1");
    const Actor* barriss = figur(sc, "barriss1");
    const ActorStep* wa = anakin != nullptr ? ersterWeg(*anakin) : nullptr;
    const ActorStep* wb = barriss != nullptr ? ersterWeg(*barriss) : nullptr;
    pruefe(wa != nullptr && wa->text == "BOTH_WALK1", "A7 intro_jedi anakin1: SET_WALKING nach dem Ziel - er geht");
    pruefe(wb != nullptr && wb->text == "BOTH_WALK1" && wb->endMs - wb->startMs >= 2000.0,
           "A7 intro_jedi barriss1: geht mit walkSpeed 35 (laenger als 2 s)");
}

// --- Der Ablauf (ablauf.cpp): wann dowait fertig ist --------------------
const char* const kKarteAblauf =
    "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"a\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"0 0 0\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"ziel1\"\n\"origin\" \"380 0 0\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"ziel2\"\n\"origin\" \"0 250 0\"\n}\n";

std::string inA(const std::string& befehle) { return "affect ( \"a\", FLUSH )\n{\n" + befehle + "}\n"; }

void laufenAblauf() {
    std::printf("\n== Laufen: Ablauf (ablauf.cpp) ==\n");
    const MapData m = karte(kKarteAblauf);
    AblaufWelt w;
    w.karte = &m;
    const auto lauf = [&](const std::string& text) { return simuliereAblauf(lies(text), "", w); };
    // Bezug (rc601 Wege): ziel1 380 weit, kein Wegnetz - im ersten Denkbild
    // prueft SafeToGoTo (Stop), dann gerade mit dem Tempo.
    const auto da = [&](const std::string& vorher, const std::string& imTask) {
        const Ablauf a = lauf(inA(vorher + "\ttask ( \"geh\" )\n\t{\n" + imTask + "\t}\n"
                                  "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n"));
        return zeitVon(a, "a", "print", "da");
    };
    const double geh90 = da("\tset ( \"SET_WALKING\", \"true\" );\n", "\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n");
    const double geh45 = da("\tset ( \"SET_WALKING\", \"true\" );\n\tset ( \"SET_WALKSPEED\", 45 );\n",
                            "\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n");
    const double lauf300 = da("\tset ( \"SET_RUNNING\", \"true\" );\n", "\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n");
    pruefe(geh90 > 0.0 && geh45 > geh90 && lauf300 > 0.0 && lauf300 < geh90,
           "B0 Bezug: gehen 90 / 45 und laufen 300 kommen an (" + std::to_string(geh90) + " / " + std::to_string(geh45) +
               " / " + std::to_string(lauf300) + ")");
    // B1 - Gangart und Tempo nach dem Ziel im selben Bild: wie davor.
    {
        const double t = da("", "\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n\t\tset ( \"SET_WALKING\", \"true\" );\n"
                                "\t\tset ( \"SET_WALKSPEED\", 45 );\n");
        pruefe(nah(t, geh45, 0.5), "B1 dowait wartet auf den Weg mit 45 (" + std::to_string(t) + ")");
    }
    // B2 - RUNNING geht vor WALKING; die Schalter sind unabhaengig
    // (Q3_SetWalking/Q3_SetRunning, Q3_Interface.cpp:5183, 5216).
    {
        const double t = da("\tset ( \"SET_RUNNING\", \"true\" );\n\tset ( \"SET_WALKING\", \"true\" );\n",
                            "\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n");
        pruefe(nah(t, lauf300, 0.5), "B2 RUNNING und WALKING: es wird gelaufen (" + std::to_string(t) + ")");
    }
    // B3 - NULL erledigt TID_MOVE_NAV (Q3_TaskIDComplete, Q3_Interface.cpp:2141).
    {
        const Ablauf a = lauf(inA("\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n\t}\n"
                                  "\tdo ( \"geh\" );\n\twait ( 1000.000 );\n\tset ( \"SET_NAVGOAL\", \"NULL\" );\n"
                                  "\twait ( \"geh\" );\n\tprint ( \"da\" );\n"));
        const double t = zeitVon(a, "a", "print", "da");
        pruefe(t >= 0.0 && t <= 1200.0, "B3 SET_NAVGOAL NULL erledigt den Weg (" + std::to_string(t) + ")");
    }
    // B4 - ein anderes Tempo unterwegs verlaengert den Weg.
    {
        const Ablauf a = lauf(inA("\tset ( \"SET_WALKING\", \"true\" );\n"
                                  "\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n\t}\n"
                                  "\tdo ( \"geh\" );\n\twait ( 2000.000 );\n\tset ( \"SET_WALKSPEED\", 45 );\n"
                                  "\twait ( \"geh\" );\n\tprint ( \"da\" );\n"));
        const double t = zeitVon(a, "a", "print", "da");
        pruefe(t > geh90 + 500.0 && t < geh45, "B4 SET_WALKSPEED 45 unterwegs: spaeter da (" + std::to_string(t) + ")");
    }
    // B5 - eine ROFF-Bahn hat das Fach TID_MOVE_NAV uebernommen: ein spaeteres
    // SET_WALKSPEED darf IHRE Zeit nicht neu rechnen.
    {
        AblaufWelt w2 = w;
        w2.roffDauer = [](const std::string& n) { return n == "x/bahn" ? 1750.0 : kRoffFehlt; };
        const Ablauf a = simuliereAblauf(
            lies(inA("\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n"
                     "\ttask ( \"flug\" )\n\t{\n\t\tplay ( \"PLAY_ROFF\", \"x/bahn\" );\n\t}\n"
                     "\tdo ( \"flug\" );\n\tset ( \"SET_WALKSPEED\", 10 );\n\twait ( \"flug\" );\n\tprint ( \"da\" );\n")),
            "", w2);
        const double t = zeitVon(a, "a", "print", "da");
        pruefe(t >= 1750.0 && t <= 1800.0, "B5 die ROFF-Bahn im selben Fach behaelt ihre Zeit (" + std::to_string(t) + ")");
    }
    // B6 - Tempo 0 aus der .npc ist gueltig: die Figur steht, dowait haengt.
    {
        AblaufWelt w2 = w;
        w2.tempo = [](const std::string&, bool) { return 0.0F; };
        const Ablauf a = simuliereAblauf(
            lies(inA("\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n\t}\n"
                     "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n")),
            "", w2);
        pruefe(zeitVon(a, "a", "print", "da") < 0.0, "B6 Tempo 0 aus der .npc: der Weg wird nie fertig");
    }
    // B7 - ein neues Ziel misst ab dem AKTUELLEN Ort, nicht ab dem alten Ziel:
    // von ziel1 (380 0) waeren es bis ziel2 (0 250) 455 - ohne Wegnetz kaeme
    // sie dort nie an. Vom Ort bei 3 s sind es unter 400.
    {
        const Ablauf a = lauf(inA("\tset ( \"SET_WALKING\", \"true\" );\n"
                                  "\ttask ( \"g1\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n\t}\n"
                                  "\ttask ( \"g2\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"ziel2\" );\n\t}\n"
                                  "\tdo ( \"g1\" );\n\twait ( 3000.000 );\n\tdowait ( \"g2\" );\n\tprint ( \"da\" );\n"));
        const double t = zeitVon(a, "a", "print", "da");
        const Scene s = buildScene(a.flach, m);
        const ActorState st = s.actors.empty() ? ActorState{} : s.actors.front().at(t);
        pruefe(t > 3000.0 && std::fabs(st.pos[0]) < 20.0F && std::fabs(st.pos[1] - 250.0F) < 20.0F,
               "B7 neues Ziel: Strecke ab dem aktuellen Ort (" + std::to_string(t) + " ms, " + std::to_string(st.pos[0]) +
                   " " + std::to_string(st.pos[1]) + ")");
    }
    // B8 - rc604 fix604 (JK2 Stufe 3): Jedi Outcast setzt TID_MOVE_NAV immer
    // und ruft nicht zurueck (codeJK2/game/Q3_Interface.cpp:6607-6610): ein
    // dowait auf "null" oder ein unbekanntes Ziel wartet fuer immer; OpenJK
    // ist sofort fertig.
    {
        const auto mitNull = [&](const std::string& ziel) {
            return zeitVon(lauf(inA("\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"" + ziel + "\" );\n\t}\n"
                                    "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n")),
                           "a", "print", "da");
        };
        const double nullJka = mitNull("NULL");
        const double fehltJka = mitNull("gibtsnicht");
        const bool mdVorher = navMovieDuelsRegeln();
        if (std::getenv("BHED_JK2_ALT") == nullptr) { regelwerkAnwendenSpiel(kRegelwerkJediOutcast, -1); }
        const double nullJk2 = mitNull("NULL");
        const double fehltJk2 = mitNull("gibtsnicht");
        regelwerkAnwenden(mdVorher, -1);
        pruefe(nah(nullJka, 0.0, 0.5) && nah(fehltJka, 0.0, 0.5), "B8 OpenJK: dowait auf \"null\"/unbekannt sofort fertig");
        pruefe(nullJk2 < 0.0 && fehltJk2 < 0.0, "B8 Jedi Outcast: dowait auf \"null\"/unbekannt wartet fuer immer (" +
                                                    std::to_string(nullJk2) + " / " + std::to_string(fehltJk2) + ")");
    }
}

// =====================================================================
// 2) Drehen
// =====================================================================
//
// Erwartet nach NPC_UpdateAngles: (60 + 3*yawSpeed) Grad je Sekunde, ohne
// Ueberschiessen, ab der Zeit des Befehls. Die Figur steht bei 0 0 100 und
// schaut nach 90; "held" ist BS_CINEMATIC (spawnflags 32), "normal" nicht.
const char* const kKarte2 =
    "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"held\"\n\"NPC_type\" \"jedi\"\n"
    "\"origin\" \"0 0 100\"\n\"angle\" \"90\"\n\"spawnflags\" \"32\"\n}\n"
    "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"normal\"\n\"NPC_type\" \"jedi\"\n"
    "\"origin\" \"500 500 100\"\n\"angle\" \"0\"\n}\n"
    "{\n\"classname\" \"target_position\"\n\"targetname\" \"ost\"\n\"origin\" \"900 0 100\"\n}\n"
    "{\n\"classname\" \"target_position\"\n\"targetname\" \"nord\"\n\"origin\" \"0 900 100\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"ziel1\"\n\"origin\" \"380 0 100\"\n}\n"
    "{\n\"classname\" \"info_null\"\n\"targetname\" \"fern\"\n\"origin\" \"900 0 100\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"ziel3\"\n\"origin\" \"500 200 100\"\n}\n";

float gier(const Actor& a, double ms) {
    float y = std::fmod(a.at(ms).angles[1], 360.0F);
    if (y < 0.0F) { y += 360.0F; }
    return y;
}
// Winkelabstand ohne Rueckwirkung des Vorzeichens (0 und 360 sind gleich).
bool gierNah(float ist, float soll, float eps) {
    float d = std::fmod(ist - soll, 360.0F);
    if (d > 180.0F) { d -= 360.0F; }
    if (d < -180.0F) { d += 360.0F; }
    return std::fabs(d) <= eps;
}
std::string normal(const std::string& befehle) {
    return "affect ( \"normal\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n" + befehle + "}\r\n";
}

void drehenSzene() {
    std::printf("\n== Drehen: Szene (scene.cpp) ==\n");
    const MapData m = karte(kKarte2);
    // T1 - Watchtarget wechseln nach SET_YAWSPEED 10 (90 Grad/s), das Muster
    // aus intro_jedi.txt:263-270. Bis rc600 ein Sprung (Start und Zeit des
    // ersten Ziels blieben stehen).
    {
        const Scene s = szene(held(set("SET_WATCHTARGET", "ost") + warte(2000.0) + setZahl("SET_YAWSPEED", "10.000") +
                                   set("SET_WATCHTARGET", "nord")), m);
        const Actor& a = s.actors.front();
        pruefe(gierNah(gier(a, 1999.0), 0.0F, 0.5F), "T1 vor dem Wechsel auf ost (0)");
        pruefe(gierNah(gier(a, 2500.0), 45.0F, 3.0F), "T1 Wechsel auf nord: nach 500 ms halb gedreht (" +
                                                          std::to_string(gier(a, 2500.0)) + ")");
        pruefe(gierNah(gier(a, 3100.0), 90.0F, 0.5F), "T1 ... und dann angekommen");
    }
    // T2 - NULL behaelt die Richtung: Q3_SetWatchTarget loescht nur den
    // Zeiger, desiredYaw bleibt (Q3_Interface.cpp:3281-3286).
    {
        const Scene s = szene(held(set("SET_WATCHTARGET", "ost") + warte(1000.0) + set("SET_WATCHTARGET", "NULL")), m);
        pruefe(gierNah(gier(s.actors.front(), 2000.0), 0.0F, 0.5F), "T2 Watchtarget NULL: sie schaut weiter dorthin (" +
                                                                          std::to_string(gier(s.actors.front(), 2000.0)) + ")");
    }
    // T3 - SET_DYAW dreht mit der Drehrate (150 Grad/s bei yawSpeed 30).
    {
        const Scene s = szene(held(setZahl("SET_YAWSPEED", "30.000") + setZahl("SET_DYAW", "0.000")), m);
        const Actor& a = s.actors.front();
        pruefe(gierNah(gier(a, 0.0), 90.0F, 0.5F) && gierNah(gier(a, 300.0), 45.0F, 3.0F) && gierNah(gier(a, 700.0), 0.0F, 0.5F),
               "T3 SET_DYAW 0: 90 -> 45 (300 ms) -> 0 (" + std::to_string(gier(a, 300.0)) + ")");
    }
    // T4 - SET_VIEWTARGET ebenso (Q3_SetViewTarget -> Q3_SetDYaw).
    {
        const Scene s = szene(held(setZahl("SET_YAWSPEED", "30.000") + set("SET_VIEWTARGET", "ost")), m);
        const Actor& a = s.actors.front();
        pruefe(gierNah(gier(a, 300.0), 45.0F, 3.0F) && gierNah(gier(a, 700.0), 0.0F, 0.5F),
               "T4 SET_VIEWTARGET ost: dreht mit der Drehrate (" + std::to_string(gier(a, 300.0)) + ")");
    }
    // T5 - SET_YAWSPEED mitten in der Drehung gilt ab seiner Zeit.
    {
        const Scene s = szene(held(set("SET_WATCHTARGET", "ost") + warte(100.0) + setZahl("SET_YAWSPEED", "10.000")), m);
        pruefe(gierNah(gier(s.actors.front(), 400.0), 30.0F, 3.0F),
               "T5 SET_YAWSPEED 10 nach 100 ms: 57 Grad, dann 27 weiter (" + std::to_string(gier(s.actors.front(), 400.0)) + ")");
    }
    // T6 - yawSpeed aus der .npc (NPC_stats.cpp:3700-3716).
    {
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tjedi\n\tyawSpeed\t30\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        const Scene s = szene(held(set("SET_WATCHTARGET", "ost")), m, &h);
        pruefe(gierNah(gier(*figur(s, "held"), 300.0), 45.0F, 3.0F),
               ".npc yawSpeed 30: 150 Grad/s (T6, " + std::to_string(gier(*figur(s, "held"), 300.0)) + ")");
    }
    // T7 - SET_ANGLES beim Gehen: ein Sprung (SetClientViewAngle), dann dreht
    // STEER die Figur zurueck in die Laufrichtung.
    {
        const Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") + warte(2000.0) +
                                   set("SET_ANGLES", "0 90 0")), m);
        const Actor& a = s.actors.front();
        pruefe(gierNah(gier(a, 2001.0), 90.0F, 1.0F) && gierNah(gier(a, 2136.0), 45.0F, 3.0F),
               "T7 SET_ANGLES beim Gehen: Sprung auf 90, dann zurueck zur Laufrichtung (" + std::to_string(gier(a, 2136.0)) + ")");
    }
    // T8 - dowait auf SET_DYAW: TID_ANGLE_FACE haelt 50*(ceil(90/16.5)+1) = 350 ms.
    {
        const Scene s = szene(held("\ttask ( \"dreh\" )\r\n\t{\r\n" + set("SET_DYAW", "0") + "\t}\r\n" +
                                   "\tdowait ( \"dreh\" );\r\n" + set("SET_ANIM_BOTH", "BOTH_GESTURE1")), m);
        pruefe(nah(s.actors.front().at(1000.0).animStartMs, 350.0, 1.0),
               "T8 dowait auf SET_DYAW wartet die Drehung ab (" + std::to_string(s.actors.front().at(1000.0).animStartMs) + ")");
    }
    // T9 - genau 180 Grad: AngleDelta liefert +180, der Winkel nimmt ab.
    {
        const Scene s = szene(held(setZahl("SET_YAWSPEED", "30.000") + setZahl("SET_DYAW", "270.000")), m);
        pruefe(gierNah(gier(s.actors.front(), 600.0), 0.0F, 1.0F) && gierNah(gier(s.actors.front(), 1300.0), 270.0F, 0.5F),
               "T9 Kehre um 180: ueber 0 nach 270 (" + std::to_string(gier(s.actors.front(), 600.0)) + ")");
    }
    // T10/T11 - rotate und move auf einem NPC: Lerp2Angles/Lerp2Pos lehnen
    // ab ("NOT a mover", Q3_Interface.cpp:8573, 8688).
    {
        const Scene s = szene(held("\trotate ( < 0.000 0.000 0.000 >, 1000.000 );\r\n"), m);
        pruefe(gierNah(gier(s.actors.front(), 2000.0), 90.0F, 0.5F), "T10 rotate auf einem NPC tut nichts");
        const Scene t = szene(held("\tmove ( < 500.000 0.000 100.000 >, 1000.000 );\r\n"), m);
        pruefe(nah(t.actors.front().at(2000.0).pos[0], 0.0, 0.5), "T11 move auf einem NPC tut nichts");
    }
    // T12 - Watchtarget beim Gehen, dann NULL: die verfolgte Richtung bleibt.
    {
        const Scene s = szene(held(set("SET_WATCHTARGET", "nord") + set("SET_WALKING", "true") + set("SET_NAVGOAL", "ziel1") +
                                   warte(20000.0) + set("SET_WATCHTARGET", "NULL")), m);
        const ActorState ende = s.actors.front().at(20500.0);
        const float soll = std::atan2(900.0F - ende.pos[1], 0.0F - ende.pos[0]) * 180.0F / 3.14159265F;
        pruefe(gierNah(gier(s.actors.front(), 20500.0), soll, 1.5F),
               "T12 nach dem Weg und NULL: weiter zu nord (" + std::to_string(soll) + ", " +
                   std::to_string(gier(s.actors.front(), 20500.0)) + ")");
    }
    // T13 - ein unbekanntes Watchtarget laesst das alte stehen
    // (Q3_SetWatchTarget kehrt vor der Zuweisung zurueck).
    {
        const Scene s = szene(held(set("SET_WATCHTARGET", "ost") + warte(1000.0) + set("SET_WATCHTARGET", "gibtesnicht")), m);
        pruefe(gierNah(gier(s.actors.front(), 2000.0), 0.0F, 0.5F) && s.actors.front().at(2000.0).hasWatchTarget,
               "T13 unbekanntes Watchtarget: das alte bleibt");
    }
    // T14 - "player" ist der Spieler (targetname "player", g_client.cpp).
    {
        const MapData mp = karte(
            "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"held\"\n\"NPC_type\" \"jedi\"\n"
            "\"origin\" \"0 0 100\"\n\"angle\" \"90\"\n\"spawnflags\" \"32\"\n}\n"
            "{\n\"classname\" \"info_player_start\"\n\"origin\" \"900 0 100\"\n}\n");
        const Scene s = szene(held(set("SET_WATCHTARGET", "player")), mp);
        pruefe(gierNah(gier(s.actors.front(), 1000.0), 0.0F, 0.5F), "T14 SET_WATCHTARGET player dreht zum Spieler");
    }
    // T15 - info_null gibt es im Spiel nach 300 ms nicht mehr (g_misc.cpp:50-62).
    {
        const Scene s = szene(held(warte(500.0) + set("SET_WATCHTARGET", "fern")), m);
        pruefe(gierNah(gier(s.actors.front(), 2000.0), 90.0F, 0.5F), "T15 Watchtarget auf ein info_null: G_Find findet es nicht");
    }
    // T16 - Watchtarget wirkt nur in BS_CINEMATIC (NPC_BSCinematic,
    // NPC_behavior.cpp:304) - NPC_BSDefault kennt es nicht.
    {
        const Scene s = szene(normal(set("SET_WATCHTARGET", "ost") + warte(1000.0) + set("SET_BEHAVIOR_STATE", "BS_CINEMATIC")), m);
        const Actor* n = figur(s, "normal");
        const float soll = std::atan2(-500.0F, 400.0F) * 180.0F / 3.14159265F + 360.0F;
        pruefe(n != nullptr && gierNah(gier(*n, 900.0), 0.0F, 0.5F), "T16 in BS_DEFAULT dreht das Watchtarget nicht");
        pruefe(n != nullptr && gierNah(gier(*n, 3000.0), soll, 1.0F), "T16 ... ab BS_CINEMATIC schon");
    }
    // T17 - die Gangart ohne Schalter haengt am Verhalten: NPC_BSDefault setzt
    // BUTTON_WALKING (AI_Default.cpp:1066-1081, auch jedi_patrol), STEER::
    // Activate nimmt dann walkSpeed; NPC_BSCinematic nicht.
    {
        const Scene s = szene(normal(set("SET_NAVGOAL", "ziel3")) + held(set("SET_NAVGOAL", "ziel1")), m);
        const ActorStep* wn = figur(s, "normal") ? letzterWeg(*figur(s, "normal")) : nullptr;
        const ActorStep* wh = figur(s, "held") ? letzterWeg(*figur(s, "held")) : nullptr;
        pruefe(wn != nullptr && wn->text == "BOTH_WALK1", "T17 BS_DEFAULT ohne Schalter: gehen");
        pruefe(wh != nullptr && wh->text == "BOTH_RUN1", "T17 BS_CINEMATIC ohne Schalter: laufen");
    }
    // T18 - der Verhaltenszustand selbst (gemeinsam mit dem Paket saber).
    {
        const Scene s = szene(held(warte(500.0) + set("SET_BEHAVIOR_STATE", "bs_noclip")) + normal(warte(10.0)), m);
        pruefe(figur(s, "held") && figur(s, "held")->at(0.0).verhalten == "BS_CINEMATIC",
               "T18 spawnflags 32: beginnt in BS_CINEMATIC");
        pruefe(figur(s, "held") && figur(s, "held")->at(1000.0).verhalten == "BS_NOCLIP", "T18 SET_BEHAVIOR_STATE, gross");
        pruefe(figur(s, "normal") && figur(s, "normal")->at(0.0).verhalten.empty(), "T18 ohne spawnflags: leer (BS_DEFAULT)");
    }
    // T19 - der Spieler selbst ist kein NPC.
    {
        const MapData mp = karte("{\n\"classname\" \"info_player_start\"\n\"origin\" \"0 0 100\"\n\"angle\" \"90\"\n}\n"
                                 "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"ziel1\"\n\"origin\" \"900 0 100\"\n}\n");
        const Scene s = szene("affect ( \"player\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n" + set("SET_NAVGOAL", "ziel1") +
                                  setZahl("SET_DYAW", "0.000") + "}\r\n", mp);
        const Actor* p = figur(s, "player");
        pruefe(p != nullptr && letzterWeg(*p) == nullptr, "T19 SET_NAVGOAL auf den Spieler: nichts (kein NPC)");
        pruefe(p != nullptr && gierNah(gier(*p, 1000.0), 90.0F, 0.5F), "T19 SET_DYAW auf den Spieler: nichts");
    }
    // T20 - der eigene Name: Q3_SetWatchTarget loescht, findet sich aber gleich
    // wieder (G_Find, Q3_Interface.cpp:3288) - und schaut auf sich selbst:
    // vectoangles eines Nullvektors ist Gier 0.
    {
        const Scene s = szene(held(set("SET_WATCHTARGET", "held")), m);
        pruefe(gierNah(gier(s.actors.front(), 1000.0), 0.0F, 0.5F), "T20 Watchtarget auf sich selbst: Gier 0");
    }
    // Waechter - SET_ANGLES setzt sofort (SetClientViewAngle).
    {
        const Scene s = szene(held(warte(1000.0) + set("SET_ANGLES", "0 0 0")), m);
        pruefe(gierNah(gier(s.actors.front(), 1001.0), 0.0F, 0.5F), "Waechter: SET_ANGLES setzt sofort");
    }
}

const char* const kKarteAblauf2 =
    "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"a\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"0 0 0\"\n"
    "\"angle\" \"90\"\n\"spawnflags\" \"32\"\n}\n"
    "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"b\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"0 100 0\"\n}\n"
    "{\n\"classname\" \"target_position\"\n\"targetname\" \"ost\"\n\"origin\" \"900 0 0\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"ziel1\"\n\"origin\" \"380 0 0\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"ziel2\"\n\"origin\" \"380 100 0\"\n}\n";

void drehenAblauf() {
    std::printf("\n== Drehen: Ablauf (ablauf.cpp) ==\n");
    const MapData m = karte(kKarteAblauf2);
    AblaufWelt w;
    w.karte = &m;
    const auto lauf = [&](const std::string& text) { return simuliereAblauf(lies(text), "", w); };
    // C1 - dowait auf SET_DYAW: 350 ms (TID_ANGLE_FACE, NPC_UpdateAngles).
    {
        const Ablauf a = lauf(inA("\ttask ( \"dreh\" )\n\t{\n\t\tset ( \"SET_DYAW\", 0 );\n\t}\n"
                                  "\tdowait ( \"dreh\" );\n\tprint ( \"da\" );\n"));
        const double t = zeitVon(a, "a", "print", "da");
        pruefe(nah(t, 350.0, 0.5), "C1 dowait auf SET_DYAW 0 (von 90): 350 ms (" + std::to_string(t) + ")");
    }
    // C2 - SET_VIEWTARGET haelt ebenso.
    {
        const Ablauf a = lauf(inA("\ttask ( \"dreh\" )\n\t{\n\t\tset ( \"SET_VIEWTARGET\", \"ost\" );\n\t}\n"
                                  "\tdowait ( \"dreh\" );\n\tprint ( \"da\" );\n"));
        const double t = zeitVon(a, "a", "print", "da");
        pruefe(nah(t, 350.0, 0.5), "C2 dowait auf SET_VIEWTARGET: 350 ms (" + std::to_string(t) + ")");
    }
    // C3/C4 - rotate und move auf einem NPC werden nie fertig: Lerp2Angles und
    // Lerp2Pos kehren vor Q3_TaskIDSet zurueck, CTaskManager::Rotate/Move
    // melden selbst nichts (TaskManager.cpp:1206, 1425).
    {
        const Ablauf a = lauf(inA("\ttask ( \"r\" )\n\t{\n\t\trotate ( < 0 0 0 >, 500.000 );\n\t}\n"
                                  "\tdowait ( \"r\" );\n\tprint ( \"da\" );\n"));
        pruefe(zeitVon(a, "a", "print", "da") < 0.0, "C3 rotate auf einem NPC: dowait haengt wie im Spiel");
        const Ablauf b = lauf(inA("\ttask ( \"r\" )\n\t{\n\t\tmove ( < 100 0 0 >, 500.000 );\n\t}\n"
                                  "\tdowait ( \"r\" );\n\tprint ( \"da\" );\n"));
        pruefe(zeitVon(b, "a", "print", "da") < 0.0, "C4 move auf einem NPC: dowait haengt wie im Spiel");
    }
    double c5Lauf = -1.0;
    // C5 - die Gangart ohne Schalter: a ist BS_CINEMATIC (laeuft), b BS_DEFAULT (geht).
    {
        const Ablauf a = lauf(inA("\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"ziel1\" );\n\t}\n"
                                  "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n") +
                              "affect ( \"b\", FLUSH )\n{\n\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"ziel2\" );\n\t}\n"
                              "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n}\n");
        const double ta = zeitVon(a, "a", "print", "da");
        const double tb = zeitVon(a, "b", "print", "da");
        // rc601 (Wege): beide 380 weit ohne Wegnetz, a mit runSpeed 300, b mit
        // walkSpeed 90 (die Vorgaben ohne .npc).
        pruefe(ta > 0.0 && tb > 0.0 && ta < tb, "C5 BS_CINEMATIC laeuft, BS_DEFAULT geht (" + std::to_string(ta) + " / " +
                                                    std::to_string(tb) + ")");
        c5Lauf = ta;
    }
    // C6 - SET_BEHAVIOR_STATE schaltet die Gangart um.
    {
        const Ablauf a = lauf("affect ( \"b\", FLUSH )\n{\n\tset ( \"SET_BEHAVIOR_STATE\", \"BS_CINEMATIC\" );\n"
                              "\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"ziel2\" );\n\t}\n"
                              "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n}\n");
        const double tb = zeitVon(a, "b", "print", "da");
        pruefe(tb > 0.0 && nah(tb, c5Lauf, 0.5), "C6 BS_CINEMATIC per Skript: laufen (" + std::to_string(tb) + ")");
    }
}

// =====================================================================
// 3) Schwerkraft
// =====================================================================
//
// Eine Welt aus Kloetzen (Oberseite zaehlt) und Rampen (z linear in x), als
// BodenStrahl: der hoechste Boden unter dem Strahlbeginn. So misst
// PM_GroundTrace mit seinem Kasten nach unten.
struct Klotz {
    float x0, x1, y0, y1, oben;
};
struct Rampe {
    float x0, x1, y0, y1, z0, z1;   // z von z0 (bei x0) nach z1 (bei x1)
};
BodenStrahl welt(std::vector<Klotz> kloetze, std::vector<Rampe> rampen) {
    return [kloetze, rampen](const std::array<float, 3>& von, const std::array<float, 3>& bis, double,
                             std::array<float, 3>& treffer) {
        const float x = von[0];
        const float y = von[1];
        float best = -1.0e30F;
        for (const Klotz& k : kloetze) {
            if (x >= k.x0 && x <= k.x1 && y >= k.y0 && y <= k.y1 && k.oben <= von[2] && k.oben >= bis[2]) {
                best = std::max(best, k.oben);
            }
        }
        for (const Rampe& r : rampen) {
            if (x >= r.x0 && x <= r.x1 && y >= r.y0 && y <= r.y1) {
                const float z = r.z0 + (r.z1 - r.z0) * (x - r.x0) / (r.x1 - r.x0);
                if (z <= von[2] && z >= bis[2]) { best = std::max(best, z); }
            }
        }
        if (best < -1.0e29F) { return false; }
        treffer = {x, y, best};
        return true;
    };
}

std::string kartenNpc(const char* name, const char* ort, const char* mehr = "") {
    return std::string("{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"") + name +
           "\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"" + ort + "\"\n\"angle\" \"0\"\n" + mehr + "}\n";
}
std::string kartenZiel(const char* name, const char* ort) {
    return std::string("{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"") + name + "\"\n\"origin\" \"" + ort +
           "\"\n}\n";
}

void schwerkraftProben() {
    std::printf("\n== Schwerkraft (Pmove) ==\n");
    const BodenStrahl flach = welt({{-5000, 5000, -5000, 5000, 0}}, {});
    const auto mitSchwerkraft = [](Scene& s, const BodenStrahl& w, double ende) {
        SchwerkraftHilfe h;
        h.strahl = w;
        h.endeMs = ende;
        schwerkraftEinrechnen(s, h);
    };
    // a1 - rc601 (bewegung, Kartenstart): eine Figur, die beim Laden der
    // Karte gespawnt wird, ist beim Skriptanfang NICHT laengst gelandet. In
    // SV_SpawnServer (sv_init.cpp MD: sv.time 1000, vier Bilder zu 100 ms,
    // dann eins) denkt der Spawner bei 1400 (START_TIME_REMOVE_ENTS + 50,
    // NPC_spawn.cpp:3101), NPC_Begin kommt bei 1500 + FRAMETIME... im ersten
    // Bild nach dem Laden (Com_ModifyMsec kappt auf 200: 1550-1700). Das
    // Skript startet erst, wenn der Client sein erstes usercmd schickt
    // (SV_ClientEnterWorld -> ClientBegin -> G_UseTargets) - im naechsten
    // Bild, 1750. NPC_Begin liegt also 200 ms vor dem Skriptanfang: ein Schritt
    // von 200 ms (224 -> 208), das erste NPC_Think 150 ms spaeter wieder 200
    // ms (-> 160), und das Denkbild bei 0 nimmt 50 ms (-> 143).
    {
        const MapData m = karte(kartenNpc("held", "0 0 224").c_str());
        Scene s = szene(held(warte(2000.0)), m);
        mitSchwerkraft(s, flach, 3000.0);
        const Actor& a = s.actors.front();
        pruefe(nah(a.at(0.0).pos[2], 143.0, 0.5) && nah(a.at(2000.0).pos[2], 24.0, 0.5),
               "a1 beim Laden der Karte gespawnt: faellt noch beim Skriptanfang (143), dann auf dem Boden (" +
                   std::to_string(a.at(0.0).pos[2]) + ", " + std::to_string(a.at(2000.0).pos[2]) + ")");
    }
    // a2 - erst im Ablauf gespawnt (erscheintMs 1000): NPC_Begin rechnet
    // sofort einen Pmove-Schritt von 200 ms (16 tiefer), das erste NPC_Think
    // 150 ms spaeter noch einen (64 tiefer), dann 50 ms je Takt - genau
    // z0 - 400 t^2 mit t = 0,4 s + Takte.
    {
        const MapData m = karte(kartenNpc("held", "0 0 224").c_str());
        Scene s = szene(held(warte(4000.0)), m);
        s.actors.front().erscheintMs = 1000.0;
        mitSchwerkraft(s, flach, 5000.0);
        const Actor& a = s.actors.front();
        pruefe(nah(a.at(1000.0).pos[2], 208.0, 0.5) && nah(a.at(1100.0).pos[2], 208.0, 0.5),
               "a2 beim Spawnen ein Schritt von 200 ms: 16 tiefer (" + std::to_string(a.at(1000.0).pos[2]) + ")");
        pruefe(nah(a.at(1150.0).pos[2], 160.0, 0.5), "a2 erstes NPC_Think: 64 tiefer (" + std::to_string(a.at(1150.0).pos[2]) + ")");
        pruefe(nah(a.at(1350.0).pos[2], 80.0, 1.0), "a2 0,2 s spaeter 144 tiefer (" + std::to_string(a.at(1350.0).pos[2]) + ")");
        pruefe(nah(a.at(1500.0).pos[2], 24.0, 0.5) && nah(a.at(2500.0).pos[2], 24.0, 0.5), "a2 dann auf dem Boden");
    }
    // b - Stufe statt Rampe: bis 16 hoch steigt sie (STEPSIZE 18).
    {
        const BodenStrahl w = welt({{-2000, 300, -500, 500, 0}, {300, 600, -500, 500, 16}}, {});
        const MapData m = karte((kartenNpc("held", "0 0 24") + kartenZiel("oben", "450 0 40")).c_str());
        Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "oben")), m);
        mitSchwerkraft(s, w, 20000.0);
        const Actor& a = s.actors.front();
        bool unten = true;
        bool oben = true;
        for (double t = 0.0; t < 15000.0; t += 50.0) {
            const ActorState st = a.at(t);
            if (st.pos[0] < 280.0F) { unten = unten && nah(st.pos[2], 24.0, 0.5); }
            if (st.pos[0] > 290.0F) { oben = oben && nah(st.pos[2], 40.0, 0.5); }
        }
        pruefe(unten && oben, "b Stufe: 24 davor, 40 darauf - keine Rampe");
    }
    // c - Kante: sie geht ueber den Rand und faellt (NPC_AvoidWallsAndCliffs
    // ist in der Engine auskommentiert). Der Kasten traegt, bis seine Kante
    // (x - 16) ueber den Rand ist.
    {
        const BodenStrahl w = welt({{300, 600, -500, 500, 16}, {600, 2000, -500, 500, -200}}, {});
        const MapData m = karte((kartenNpc("held", "450 0 40") + kartenZiel("unten", "1000 0 -176")).c_str());
        Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "unten")), m);
        mitSchwerkraft(s, w, 20000.0);
        const Actor& a = s.actors.front();
        bool getragen = true;
        bool faellt = true;
        bool nieDrunter = true;
        bool gelandet = true;
        float vorher = 1.0e9F;
        for (double t = 0.0; t < 15000.0; t += 50.0) {
            const ActorState st = a.at(t);
            if (st.pos[0] < 610.0F) { getragen = getragen && nah(st.pos[2], 40.0, 0.5); }
            if (st.pos[0] >= 610.0F) { faellt = faellt && st.pos[2] <= vorher + 0.01F; }
            nieDrunter = nieDrunter && st.pos[2] >= -176.5F;
            if (st.pos[0] > 700.0F) { gelandet = gelandet && nah(st.pos[2], -176.0, 0.5); }
            vorher = st.pos[2];
        }
        pruefe(getragen && faellt && nieDrunter && gelandet, "c Kante: getragen bis x 610, dann Fall, Landung bei -176");
    }
    // d - SET_ORIGIN in die Luft: set ( SET_ORIGIN ) ruft G_SetOrigin
    // (Q3_Interface.cpp:8792) - genau dort, kein +1; dann faellt sie.
    {
        const MapData m = karte(kartenNpc("held", "0 0 24").c_str());
        Scene s = szene(held(warte(1000.0) + set("SET_ORIGIN", "0 0 300")), m);
        mitSchwerkraft(s, flach, 4000.0);
        const Actor& a = s.actors.front();
        pruefe(nah(a.at(1000.0).pos[2], 300.0, 0.5), "d SET_ORIGIN: genau dort (G_SetOrigin)");
        pruefe(nah(a.at(999.0).pos[2], 24.0, 0.5), "d ... und kein Verschmieren davor (" + std::to_string(a.at(999.0).pos[2]) + ")");
        pruefe(nah(a.at(1400.0).pos[2], 236.0, 1.0), "d ... 0,4 s spaeter 64 tiefer (" + std::to_string(a.at(1400.0).pos[2]) + ")");
        pruefe(nah(a.at(2500.0).pos[2], 24.0, 0.5), "d ... und dann auf dem Boden");
    }
    // e - ein Flieger (CLASS_REMOTE, MT_FLYSWIM, gravity 0; NPC_spawn.cpp:996-1006).
    {
        NpcMap npcs;
        parseNpcFile("remote_sp\n{\n\tlegsModel\tremote\n\tclass\tCLASS_REMOTE\n\tplayerTeam\tTEAM_ENEMY\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        const MapData m = karte("{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"held\"\n\"NPC_type\" \"remote_sp\"\n"
                                "\"origin\" \"0 0 224\"\n}\n");
        Scene s = szene(held(warte(2000.0)), m, &h);
        mitSchwerkraft(s, flach, 3000.0);
        pruefe(nah(s.actors.front().at(2000.0).pos[2], 224.0, 0.5), "e Flieger (CLASS_REMOTE) bleibt in der Luft");
    }
    // e2 - "movetype flyswim" aus der .npc (MoveTypeNameToEnum, NPC_stats.cpp:468).
    {
        NpcMap npcs;
        parseNpcFile("schweber\n{\n\tplayerModel\tkyle\n\tmovetype\tFlySwim\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        const MapData m = karte("{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"held\"\n\"NPC_type\" \"schweber\"\n"
                                "\"origin\" \"0 0 224\"\n}\n");
        Scene s = szene(held(warte(2000.0)), m, &h);
        mitSchwerkraft(s, flach, 3000.0);
        pruefe(nah(s.actors.front().at(2000.0).pos[2], 224.0, 0.5), "e2 movetype flyswim: bleibt in der Luft");
    }
    // f - ohne Strahl (keine Karte) bleibt alles wie bisher.
    {
        const MapData m = karte(kartenNpc("held", "0 0 224").c_str());
        Scene s = szene(held(warte(2000.0)), m);
        mitSchwerkraft(s, BodenStrahl{}, 3000.0);
        pruefe(s.actors.front().hoehe.empty() && nah(s.actors.front().at(1000.0).pos[2], 224.0, 0.5),
               "f ohne Karte: keine Schwerkraft (Waechter)");
    }
    // g - bergab auf einer gehbaren Rampe (30 Grad): sie bleibt am Boden
    // (PM_WalkMove klappt die Bewegung auf den Hang), schwebt nicht. Der
    // Kasten liegt dabei auf seiner oberen Kante auf (x - 16), wie der
    // Kasten von PM_GroundTrace.
    {
        const float tief = -300.0F * 0.5774F;
        const BodenStrahl w = welt({{300, 2000, -500, 500, tief}, {-2000, 0, -500, 500, 0}}, {{0, 300, -500, 500, 0, tief}});
        char ziel[64];
        std::snprintf(ziel, sizeof(ziel), "600 0 %.3f", static_cast<double>(tief + 24.0F));
        const MapData m = karte((kartenNpc("held", "-50 0 24", "\"spawnflags\" \"32\"\n") + kartenZiel("unten", ziel)).c_str());
        Scene s = szene(held(set("SET_NAVGOAL", "unten")), m);
        mitSchwerkraft(s, w, 10000.0);
        const Actor& a = s.actors.front();
        const auto boden = [tief](float x) { return x <= 0.0F ? 0.0F : x >= 300.0F ? tief : -0.5774F * x; };
        float schlimmst = 0.0F;
        for (double t = 0.0; t < 8000.0; t += 50.0) {
            const ActorState st = a.at(t);
            const float traegt = std::max({boden(st.pos[0] - 16.0F), boden(st.pos[0]), boden(st.pos[0] + 16.0F)});
            schlimmst = std::max(schlimmst, std::fabs(st.pos[2] - (traegt + 24.0F)));
        }
        pruefe(schlimmst <= 1.0F, "g bergab am Hang: der Kasten liegt auf (hoechstens 1 daneben, " + std::to_string(schlimmst) + ")");
    }
    // h - BS_NOCLIP: keine Schwerkraft (client->noclip, PM_NoclipMove), der
    // Weg geht frei durch die Luft (Waechter).
    {
        const MapData m = karte((kartenNpc("held", "0 0 24") + kartenZiel("luft", "900 0 224")).c_str());
        // rc601 (bewegung, BS_NOCLIP wie im Spiel): PM_NoclipMove nimmt
        // ps.speed - SET_WALKSPEED setzt es (sonst 0: sie stuende).
        Scene s = szene(held(set("SET_BEHAVIOR_STATE", "BS_NOCLIP") + set("SET_WALKING", "true") +
                             setZahl("SET_WALKSPEED", "90") + set("SET_NAVGOAL", "luft")),
                        m);
        mitSchwerkraft(s, flach, 20000.0);
        const Actor& a = s.actors.front();
        pruefe(a.at(5000.0).pos[2] > 100.0F, "h BS_NOCLIP: der Weg geht durch die Luft (Waechter, " +
                                                 std::to_string(a.at(5000.0).pos[2]) + ")");
    }
    // h2 - BS_NOCLIP wieder aus: Q3_SetBState hebt 0,125, dann faellt sie.
    {
        const MapData m = karte((kartenNpc("held", "0 0 24") + kartenZiel("luft", "300 0 224")).c_str());
        Scene s = szene(held(set("SET_BEHAVIOR_STATE", "BS_NOCLIP") + set("SET_WALKING", "true") +
                             setZahl("SET_WALKSPEED", "90") +
                             "\ttask ( \"flug\" )\r\n\t{\r\n" + set("SET_NAVGOAL", "luft") + "\t}\r\n" +
                             "\tdowait ( \"flug\" );\r\n" + set("SET_BEHAVIOR_STATE", "BS_CINEMATIC") + warte(3000.0)),
                        m);
        mitSchwerkraft(s, flach, 30000.0);
        const Actor& a = s.actors.front();
        const ActorStep* w = letzterWeg(a);
        const double an = w != nullptr ? w->endMs : 0.0;
        pruefe(w != nullptr && a.at(an).pos[2] > 200.0F && nah(a.at(an + 2000.0).pos[2], 24.0, 0.5),
               "h2 BS_NOCLIP aus: oben angekommen, dann gefallen (" + std::to_string(a.at(an).pos[2]) + ")");
    }
    // i - kill in der Luft: die Leiche faellt weiter (der Halt aendert nur X/Y).
    {
        const MapData m = karte(kartenNpc("held", "0 0 24").c_str());
        Scene s = szene(held(warte(1000.0) + set("SET_ORIGIN", "0 0 300") + warte(200.0) + "\tkill ( \"self\" );\r\n"), m);
        mitSchwerkraft(s, flach, 4000.0);
        pruefe(nah(s.actors.front().at(2500.0).pos[2], 24.0, 0.5), "i kill in der Luft: die Leiche landet");
    }
    // j - DROPTOFLOOR setzt die Figur NICHT um (G_SetOrigin auf den Spawner,
    // nicht auf die Figur - NPC_spawn.cpp:2469-2483, 2659-2662); erst im
    // Ablauf gespawnt, steht sie oben und faellt.
    {
        const MapData m = karte(kartenNpc("held", "0 0 224", "\"spawnflags\" \"16\"\n").c_str());
        Scene s = szene(held(warte(4000.0)), m);
        s.actors.front().erscheintMs = 1000.0;
        mitSchwerkraft(s, flach, 5000.0);
        const Actor& a = s.actors.front();
        pruefe(a.at(1000.0).pos[2] > 200.0F && nah(a.at(2500.0).pos[2], 24.0, 0.5),
               "j DROPTOFLOOR: spawnt oben, faellt dann (" + std::to_string(a.at(1000.0).pos[2]) + ")");
    }
    // k - CEILING (JSF_AMBUSH, spawnflags 16) auf einem Jedi: haengt
    // (client->noclip, NPC_spawn.cpp:665-670) bis zum ersten SET_BEHAVIOR_STATE.
    {
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tjedi\n\tclass\tCLASS_JEDI\n\tplayerTeam\tTEAM_PLAYER\n\tweapon\tWP_SABER\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        const MapData m = karte(kartenNpc("held", "0 0 224", "\"spawnflags\" \"16\"\n").c_str());
        Scene s = szene(held(warte(2000.0) + set("SET_BEHAVIOR_STATE", "BS_CINEMATIC") + warte(2000.0)), m, &h);
        mitSchwerkraft(s, flach, 5000.0);
        const Actor& a = s.actors.front();
        pruefe(nah(a.at(1900.0).pos[2], 224.0, 0.5), "k CEILING-Jedi haengt bis SET_BEHAVIOR_STATE");
        pruefe(nah(a.at(3500.0).pos[2], 24.0, 0.5), "k ... und faellt danach");
    }
    // l - eine ROFF-Bahn auf der Figur: kein Pmove (NPC_ApplyRoff statt
    // ClientThink, NPC.cpp:2158-2166). Die Bahn rechnet ab dem AKTUELLEN Ort
    // (G_Roff addiert auf trBase) - auch ab der gelandeten Hoehe; danach
    // faellt die Figur wieder.
    {
        auto bahn = std::make_shared<Roff>();
        bahn->fassung = 1;
        bahn->bildMs = 100;
        bahn->lerp = 10;
        for (int k = 0; k < 10; ++k) {
            RoffBild b;
            b.ort[2] = 10.0F;   // je Bild 10 hinauf
            bahn->bilder.push_back(b);
        }
        SzenenHilfe h;
        h.roff = [bahn](const std::string& n) { return n == "hoch" ? std::shared_ptr<const Roff>(bahn) : nullptr; };
        const MapData m = karte(kartenNpc("held", "0 0 224").c_str());
        Scene s = szene(held(warte(1000.0) + "\tplay ( /*@PLAY_TYPES*/ \"PLAY_ROFF\", \"hoch\" );\r\n" + warte(5000.0)), m, &h);
        mitSchwerkraft(s, flach, 7000.0);
        const Actor& a = s.actors.front();
        const ActorStep* r = nullptr;
        for (const ActorStep& st : a.steps) {
            if (st.kind == ActorStep::Kind::Roff) { r = &st; }
        }
        const double ende = r != nullptr ? r->endMs : 0.0;
        pruefe(r != nullptr && nah(a.at(ende).pos[2], 124.0, 1.0),
               "l ROFF auf der Figur: 100 hinauf ab dem Boden, nicht ab dem Spawner (" + std::to_string(a.at(ende).pos[2]) + ")");
        pruefe(r != nullptr && nah(a.at(ende + 1500.0).pos[2], 24.0, 0.5), "l ... danach faellt sie wieder");
    }
    // m - ein Aufzug: der Boden selbst bewegt sich (SchwerkraftHilfe::
    // beweglich) - die Figur faehrt mit, hinauf und wieder hinab
    // (G_MoverPush nimmt, wer darauf steht).
    {
        const auto buehne = [](double ms) {
            if (ms <= 1000.0) { return 0.0F; }
            if (ms <= 2000.0) { return static_cast<float>((ms - 1000.0) * 0.1); }
            if (ms <= 3000.0) { return 100.0F; }
            if (ms <= 4000.0) { return static_cast<float>(100.0 - (ms - 3000.0) * 0.1); }
            return 0.0F;
        };
        const BodenStrahl w = [buehne](const std::array<float, 3>& von, const std::array<float, 3>& bis, double ms,
                                       std::array<float, 3>& t) {
            float z = 0.0F;
            if (std::fabs(von[0]) <= 100.0F && std::fabs(von[1]) <= 100.0F) { z = buehne(ms); }
            if (z > von[2] || z < bis[2]) { return false; }
            t = {von[0], von[1], z};
            return true;
        };
        const MapData m = karte(kartenNpc("held", "0 0 24").c_str());
        Scene s = szene(held(warte(6000.0)), m);
        SchwerkraftHilfe h;
        h.strahl = w;
        h.endeMs = 7000.0;
        h.beweglich = [](float x, float y, double ms) {
            return std::fabs(x) <= 120.0F && std::fabs(y) <= 120.0F && ms > 950.0 && ms < 4050.0;
        };
        schwerkraftEinrechnen(s, h);
        const Actor& a = s.actors.front();
        pruefe(nah(a.at(1500.0).pos[2], 74.0, 1.0) && nah(a.at(2500.0).pos[2], 124.0, 0.5),
               "m Aufzug hinauf: sie faehrt mit (" + std::to_string(a.at(1500.0).pos[2]) + ")");
        float schlimmst = 0.0F;
        for (double t = 3000.0; t <= 4500.0; t += 50.0) {
            schlimmst = std::max(schlimmst, std::fabs(a.at(t).pos[2] - (buehne(t) + 24.0F)));
        }
        pruefe(schlimmst <= 0.5F && nah(a.at(5000.0).pos[2], 24.0, 0.5),
               "m ... und hinab, ohne zu schweben (hoechstens " + std::to_string(schlimmst) + " darueber)");
    }
    // n - G_CheckInSolid hebt eine Figur, deren Fuesse im Boden stecken (bis
    // 24); mit SFB_STARTINSOLID (128) nicht (NPC_spawn.cpp:2030-2034).
    {
        const MapData m = karte((kartenNpc("held", "0 0 14") + kartenNpc("drin", "200 0 14", "\"spawnflags\" \"128\"\n")).c_str());
        Scene s = szene(held(warte(2000.0)) + "affect ( \"drin\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n" + warte(2000.0) + "}\r\n", m);
        for (Actor& a : s.actors) { a.erscheintMs = 500.0; }
        mitSchwerkraft(s, flach, 3000.0);
        const Actor* held1 = figur(s, "held");
        const Actor* drin = figur(s, "drin");
        pruefe(held1 != nullptr && nah(held1->at(500.0).pos[2], 24.0, 0.3) && nah(held1->at(2000.0).pos[2], 24.0, 0.3),
               "n G_CheckInSolid: aus dem Boden gehoben");
        pruefe(drin != nullptr && nah(drin->at(2000.0).pos[2], 14.0, 0.3), "n SFB_STARTINSOLID: bleibt stecken");
    }
    // o - der Spieler selbst ist ein client wie jeder NPC: auch er steht auf
    // dem Boden.
    {
        const MapData m = karte("{\n\"classname\" \"info_player_start\"\n\"origin\" \"0 0 224\"\n\"angle\" \"0\"\n}\n");
        Scene s = szene("affect ( \"player\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n" + warte(1000.0) + "}\r\n", m);
        mitSchwerkraft(s, flach, 2000.0);
        const Actor* p = figur(s, "player");
        pruefe(p != nullptr && nah(p->at(500.0).pos[2], 24.0, 0.5), "o der Spieler steht auf dem Boden");
    }
    // Der Kartenstrahl: Wasser ist kein Boden, ein Brush-Modell schon.
    {
        BspGeometry g;
        g.planes.push_back(BspGeometry::Plane{{0.0F, 0.0F, 1.0F}, -100000.0F});
        BspGeometry::Node knoten;
        knoten.plane = 0;
        knoten.children[0] = -1;
        knoten.children[1] = -1;
        g.nodes.push_back(knoten);
        BspGeometry::Leaf blatt;
        blatt.numSurfaces = 2;
        g.leafs.push_back(blatt);
        g.leafSurfaces = {0, 1};
        BspShader fest;
        fest.name = "textures/probe/boden";
        fest.contentFlags = 1U;   // CONTENTS_SOLID
        BspShader wasser;
        wasser.name = "textures/probe/wasser";
        wasser.contentFlags = 4U;   // CONTENTS_WATER
        g.shaders = {fest, wasser};
        const auto quad = [&](float z, int shader) {
            const auto erster = static_cast<int>(g.verts.size());
            const float ecken[4][2] = {{-500.0F, -500.0F}, {500.0F, -500.0F}, {500.0F, 500.0F}, {-500.0F, 500.0F}};
            for (const auto& e : ecken) {
                BspVertex v;
                v.xyz[0] = e[0];
                v.xyz[1] = e[1];
                v.xyz[2] = z;
                g.verts.push_back(v);
            }
            const auto ersterIndex = static_cast<int>(g.indexes.size());
            for (const std::uint32_t i : {0U, 1U, 2U, 0U, 2U, 3U}) { g.indexes.push_back(i); }
            BspSurface f;
            f.type = BspSurface::Type::Planar;
            f.shader = shader;
            f.firstVert = erster;
            f.numVerts = 4;
            f.firstIndex = ersterIndex;
            f.numIndexes = 6;
            f.mins[0] = f.mins[1] = -500.0F;
            f.maxs[0] = f.maxs[1] = 500.0F;
            f.mins[2] = f.maxs[2] = z;
            g.surfaces.push_back(f);
        };
        quad(0.0F, 0);
        quad(40.0F, 1);
        const float von[3] = {0.0F, 0.0F, 200.0F};
        const float bis[3] = {0.0F, 0.0F, -100.0F};
        float t[3] = {0.0F, 0.0F, 0.0F};
        pruefe(bodenTreffer(g, von, bis, t) && nah(t[2], 0.0, 0.01), "Kartenstrahl: Wasser (CONTENTS_WATER) wird durchstossen");
        pruefe(festeShader(g) == std::vector<bool>({true, false}), "Kartenstrahl: feste Shader nach MASK_NPCSOLID");
        BspMesh netz;
        const float ecken[4][2] = {{-50.0F, -50.0F}, {50.0F, -50.0F}, {50.0F, 50.0F}, {-50.0F, 50.0F}};
        for (const auto& e : ecken) {
            BspVertex v;
            v.xyz[0] = e[0];
            v.xyz[1] = e[1];
            v.xyz[2] = 100.0F;
            netz.verts.push_back(v);
        }
        netz.indexes = {0U, 1U, 2U, 0U, 2U, 3U};
        BspMesh::Batch b;
        b.shader = 0;
        b.firstIndex = 0;
        b.numIndexes = 6;
        netz.batches.push_back(b);
        float tn[3] = {0.0F, 0.0F, 0.0F};
        pruefe(netzTreffer(netz, {}, von, bis, tn) && nah(tn[2], 100.0, 0.01), "Kartenstrahl: ein Brush-Modell traegt");
        // Das Raster fuer senkrechte Strahlen: dieselbe Welt als Netz, das
        // Wasser darin nicht fest.
        BspMesh weltNetz;
        for (int q = 0; q < 2; ++q) {
            for (const auto& e : ecken) {
                BspVertex v;
                v.xyz[0] = e[0] * 10.0F;
                v.xyz[1] = e[1] * 10.0F;
                v.xyz[2] = q == 0 ? 0.0F : 40.0F;
                weltNetz.verts.push_back(v);
            }
            const auto o = static_cast<std::uint32_t>(q * 4);
            for (const std::uint32_t i : {0U, 1U, 2U, 0U, 2U, 3U}) { weltNetz.indexes.push_back(o + i); }
            BspMesh::Batch wb;
            wb.shader = q;
            wb.firstIndex = static_cast<std::uint32_t>(q * 6);
            wb.numIndexes = 6;
            weltNetz.batches.push_back(wb);
        }
        const BodenRaster r = baueBodenRaster(weltNetz, festeShader(g));
        float z = -1.0F;
        pruefe(rasterTreffer(r, 10.0F, -20.0F, 200.0F, -100.0F, z) && nah(z, 0.0, 0.01), "Raster: Wasser durchstossen, Boden getroffen");
        const BodenRaster alles = baueBodenRaster(weltNetz, {});
        pruefe(rasterTreffer(alles, 10.0F, -20.0F, 200.0F, -100.0F, z) && nah(z, 40.0, 0.01), "Raster: ohne Filter der oberste");
        pruefe(!rasterTreffer(r, 10.0F, -20.0F, -1.0F, -100.0F, z), "Raster: unter dem Boden nichts");
        pruefe(!rasterTreffer(r, 900.0F, 0.0F, 200.0F, -100.0F, z), "Raster: neben der Welt nichts");
    }
}

// --- Teil 4: Laufziele ohne Weg im Wegnetz (rc601) ---------------------------
//
// Ein Lauf ab 400 Einheiten, dessen Ziel im Netz nicht erreichbar ist: im Spiel
// ruft NPC_MoveToGoal STEER::Stop, die Figur bleibt stehen, die Laufaufgabe
// wird nie fertig. behaved laeuft gerade - und muss es wenigstens melden.
std::string wegpunkt(const char* name, const char* ort, const char* ziel = "") {
    std::string t = std::string("{\n\"classname\" \"waypoint\"\n\"targetname\" \"") + name + "\"\n\"origin\" \"" + ort + "\"\n";
    if (*ziel != 0) { t += std::string("\"target\" \"") + ziel + "\"\n"; }
    return t + "}\n";
}
std::string zielOhneAuto(const char* name, const char* ort) {
    // spawnflags 4: NO_AUTO_CONNECT (g_navigator.cpp, NAV::SpawnedPoint)
    return std::string("{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"") + name + "\"\n\"origin\" \"" + ort +
           "\"\n\"spawnflags\" \"4\"\n}\n";
}

void navProben() {
    std::printf("\n== Laufziele ohne Weg im Wegnetz (STEER::SafeToGoTo / NAV::GoTo) ==\n");
    const auto meldungen = [](const std::string& kartenText, const std::string& skript) {
        const MapData m = karte(kartenText.c_str());
        const Scene s = szene(held(skript), m);
        return navZieleOhneWeg(s, baueWegNetz(m.entities));
    };
    // n1 - 600 weit, kein Netz: im Spiel steht sie (GetNearestNode ohne
    // Kanten: WAYPOINT_NONE, NAV::GoTo -> STEER::Blocked/Stop).
    {
        const auto w = meldungen(kartenNpc("held", "0 0 24") + kartenZiel("weit", "600 0 24"),
                                 set("SET_NAVGOAL", "weit") + warte(9000.0));
        pruefe(w.size() == 1U && w.front().abstand > 599.0F && w.front().abstand < 601.0F,
               "n1 600 weit ohne Netz: eine Meldung (" + std::to_string(w.size()) + ")");
    }
    // n2 - 300 weit: STEER geht gerade (MoveTrace unter 400) - keine Meldung.
    {
        const auto w = meldungen(kartenNpc("held", "0 0 24") + kartenZiel("nah", "300 0 24"),
                                 set("SET_NAVGOAL", "nah") + warte(9000.0));
        pruefe(w.empty(), "n2 300 weit: keine Meldung (" + std::to_string(w.size()) + ")");
    }
    // n3 - 800 weit, eine Kette Wegpunkt -> Wegpunkt -> Ziel: NAV::GoTo findet
    // einen Weg (A*) - keine Meldung.
    {
        // rc601 (Wege): mit einem vierten Knoten - bis drei Knoten baut die
        // Engine gar keine Kanten ("if (mGraph.size_nodes() <= 3) return
        // true;", g_navigator.cpp:1471).
        const auto w = meldungen(kartenNpc("held", "0 0 24") + wegpunkt("w1", "40 0 24", "w2") +
                                     wegpunkt("w2", "420 0 24", "fern") + zielOhneAuto("fern", "800 0 24") +
                                     wegpunkt("w0", "-300 60 24", "w1"),
                                 set("SET_NAVGOAL", "fern") + warte(9000.0));
        pruefe(w.empty(), "n3 800 weit mit Kette im Netz: keine Meldung (" + std::to_string(w.size()) + ")");
        const auto drei = meldungen(kartenNpc("held", "0 0 24") + wegpunkt("w1", "40 0 24", "w2") +
                                        wegpunkt("w2", "420 0 24", "fern") + zielOhneAuto("fern", "800 0 24"),
                                    set("SET_NAVGOAL", "fern") + warte(9000.0));
        pruefe(drei.size() == 1U, "n3b dieselbe Kette mit nur drei Knoten: kein Netz, eine Meldung (" +
                                      std::to_string(drei.size()) + ")");
    }
    // n4 - 800 weit, Netz da, aber das Ziel haengt an keinem Knoten der Figur
    // (NO_AUTO_CONNECT, keine Kante dorthin): kein Weg - Meldung.
    {
        const auto w = meldungen(kartenNpc("held", "0 0 24") + wegpunkt("w1", "40 0 24", "w2") +
                                     wegpunkt("w2", "300 0 24") + zielOhneAuto("fern", "800 0 24"),
                                 set("SET_NAVGOAL", "fern") + warte(9000.0));
        pruefe(w.size() == 1U && w.front().zielKnoten >= 0,
               "n4 800 weit, Ziel ohne Kante: eine Meldung mit Zielknoten (" + std::to_string(w.size()) + ")");
    }
    // n5 - ein neues Tempo unterwegs teilt den Weg in Stuecke: trotzdem nur
    // EINE Meldung je Lauf.
    {
        const auto w = meldungen(kartenNpc("held", "0 0 24") + kartenZiel("weit", "900 0 24"),
                                 set("SET_NAVGOAL", "weit") + warte(1000.0) + setZahl("SET_WALKSPEED", "40") +
                                     warte(9000.0));
        pruefe(w.size() == 1U, "n5 Weg in Stuecken: eine Meldung (" + std::to_string(w.size()) + ")");
    }
    // n6 - zwei Laeufe nacheinander, der zweite mit Tempo direkt danach und
    // einem Wechsel unterwegs (das Muster aus bewegungSchritte): zwei Meldungen.
    {
        const auto w = meldungen(kartenNpc("held", "0 0 24") + kartenZiel("z1", "600 0 24") + kartenZiel("z2", "600 600 24"),
                                 set("SET_NAVGOAL", "z1") + warte(15000.0) + set("SET_NAVGOAL", "z2") +
                                     setZahl("SET_WALKSPEED", "30") + warte(800.0) + setZahl("SET_WALKSPEED", "60") +
                                     warte(700.0) + set("SET_NAVGOAL", "NULL") + warte(500.0));
        std::string was;
        for (const NavOhneWeg& x : w) { was += " " + std::to_string(static_cast<int>(x.ziel[1])) + "@" + std::to_string(static_cast<int>(x.ms)); }
        // Der zweite Lauf geht von (600 0) nach z2 (600 600) und wird nach 1,5 s
        // per NULL abgebrochen - das Ziel kennt nur laufZiel.
        pruefe(w.size() == 2U && w.back().ms > 14999.0 && w.back().ziel[1] > 599.0F,
               "n6 zwei Laeufe nacheinander: zwei Meldungen, die zweite mit dem echten Ziel (" + std::to_string(w.size()) +
                   ":" + was + ")");
    }
    // n7 - der Beginn eines in Stuecke geteilten Laufs zaehlt: Meldung bei 0 ms,
    // nicht beim zweiten Stueck.
    {
        const auto w = meldungen(kartenNpc("held", "0 0 24") + kartenZiel("weit", "900 0 24"),
                                 set("SET_NAVGOAL", "weit") + warte(1000.0) + setZahl("SET_WALKSPEED", "40") +
                                     warte(9000.0));
        pruefe(w.size() == 1U && w.front().ms < 1.0 && w.front().abstand > 899.0F,
               "n7 Weg in Stuecken: Meldung beim Losgehen mit dem ganzen Abstand (" +
                   (w.empty() ? std::string("-") : std::to_string(w.front().ms) + " ms, " + std::to_string(w.front().abstand)) + ")");
    }
}

// =====================================================================
// Review (rc601, Paket bewegung): Befunde der Durchsicht
// =====================================================================
//
// Jede Probe hier war vor ihrer Behebung rot (NOTIZEN_bewegung.md, "Review").

// Die Hoehen aller Figuren Bit fuer Bit als eine Zahl (FNV-1a).
std::uint64_t hoehenHash(const Scene& s) {
    std::uint64_t h = 1469598103934665603ULL;
    const auto dazu = [&h](std::uint32_t b) {
        for (int k = 0; k < 4; ++k) {
            h ^= (b >> (8 * k)) & 0xFFU;
            h *= 1099511628211ULL;
        }
    };
    for (const Actor& a : s.actors) {
        for (const float z : a.hoehe) {
            std::uint32_t b = 0;
            std::memcpy(&b, &z, sizeof(b));
            dazu(b);
        }
        dazu(static_cast<std::uint32_t>(a.hoehe.size()));
    }
    return h;
}

// Eine grosse Szene: n Figuren, je acht Laufziele mit Gangart- und
// Tempowechseln, SET_ORIGIN in die Luft, BS_NOCLIP, ROFF, SET_GRAVITY, kill;
// manche erst im Ablauf gespawnt, manche haengend (JSF_AMBUSH).
Scene grosseSzene(int n, const SzenenHilfe& h) {
    std::string karteText;
    std::string skript;
    for (int i = 0; i < n; ++i) {
        const int x = (i % 8) * 300;
        const int y = (i / 8) * 300;
        const std::string f = "f" + std::to_string(i);
        karteText += kartenNpc(f.c_str(), (std::to_string(x) + " " + std::to_string(y) + " 100").c_str());
        karteText += kartenZiel(("z" + std::to_string(i)).c_str(),
                                (std::to_string(x + 150) + " " + std::to_string(y + 150) + " 24").c_str());
        skript += "affect ( \"" + f + "\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n";
        for (int r = 0; r < 8; ++r) {
            skript += set("SET_NAVGOAL", "z" + std::to_string((i + r + 1) % n));
            if (r % 3 == 0) {
                skript += set("SET_RUNNING", "true");
            } else if (r % 3 == 1) {
                skript += set("SET_RUNNING", "false") + set("SET_WALKING", "true");
            } else {
                skript += set("SET_WALKING", "false");
            }
            if (r == 2) { skript += setZahl("SET_WALKSPEED", "40"); }
            if (r == 5) { skript += setZahl("SET_RUNSPEED", "150"); }
            if (r == 2 && i % 5 == 0) { skript += "\tplay ( /*@PLAY_TYPES*/ \"PLAY_ROFF\", \"hoch\" );\r\n"; }
            if (r == 5 && i % 3 == 0) { skript += set("SET_GRAVITY", "300"); }
            skript += warte(1500.0 + 300.0 * r + 37.0 * i);
            if (r == 1) { skript += setZahl("SET_WALKSPEED", "70"); }
            if (r == 3) { skript += set("SET_ORIGIN", std::to_string(x) + " " + std::to_string(y) + " 160"); }
            if (r == 4) { skript += set("SET_BEHAVIOR_STATE", "BS_NOCLIP"); }
            if (r == 6) { skript += set("SET_BEHAVIOR_STATE", "BS_CINEMATIC"); }
        }
        if (i % 7 == 3) { skript += "\tkill ( \"" + f + "\" );\r\n"; }
        skript += "}\r\n";
    }
    const MapData m = karte(karteText.c_str());
    Scene s = szene(skript, m, &h);
    for (std::size_t i = 0; i < s.actors.size(); ++i) {
        Actor& a = s.actors[i];
        if (i % 4 == 1) { a.erscheintMs = 1000.0 + 50.0 * static_cast<double>(i); }
        if (i % 9 == 0) {
            a.haengtAnfangs = true;
            a.haengtBisMs = 5000.0;
        }
    }
    return s;
}

void reviewProben() {
    std::printf("\n== Review (Durchsicht rc601) ==\n");
    const BodenStrahl flach = welt({{-5000, 5000, -5000, 5000, 0}}, {});
    const auto mitSchwerkraft = [](Scene& s, const BodenStrahl& w, double ende) {
        SchwerkraftHilfe h;
        h.strahl = w;
        h.endeMs = ende;
        schwerkraftEinrechnen(s, h);
    };
    // g1 - "gravity" der worldspawn: SP_worldspawn setzt g_gravity daraus
    // (g_spawn.cpp:1698-1704). Mit 400 faellt die erst im Ablauf gespawnte
    // Figur im 200-ms-Schritt von NPC_Begin 8 statt 16, im zweiten (200 ms,
    // vz -80 -> -160) weitere 24.
    {
        const MapData m = karte(("{\n\"classname\" \"worldspawn\"\n\"gravity\" \"400\"\n}\n" + kartenNpc("held", "0 0 224")).c_str());
        Scene s = szene(held(warte(4000.0)), m);
        s.actors.front().erscheintMs = 1000.0;
        mitSchwerkraft(s, flach, 5000.0);
        const Actor& a = s.actors.front();
        pruefe(nah(s.schwerkraft, 400.0, 0.001), "g1 worldspawn gravity 400: Scene::schwerkraft (" + std::to_string(s.schwerkraft) + ")");
        pruefe(nah(a.at(1000.0).pos[2], 216.0, 0.5) && nah(a.at(1150.0).pos[2], 192.0, 0.5),
               "g1 ... faellt mit 400: 216 beim Spawnen, 192 beim ersten NPC_Think (" + std::to_string(a.at(1000.0).pos[2]) +
                   ", " + std::to_string(a.at(1150.0).pos[2]) + ")");
    }
    // g2 - ohne Schluessel gilt 800 (G_SpawnString-Vorgabe).
    {
        const MapData m = karte(("{\n\"classname\" \"worldspawn\"\n}\n" + kartenNpc("held", "0 0 224")).c_str());
        const Scene s = szene(held(warte(1000.0)), m);
        pruefe(nah(s.schwerkraft, 800.0, 0.001), "g2 worldspawn ohne gravity: 800 (" + std::to_string(s.schwerkraft) + ")");
    }
    // g3 - set ( SET_GRAVITY, 0 ): die Figur schwebt nach SET_ORIGIN in der
    // Luft (ps.gravity 0, vz bleibt 0 - PM_SlideMove zieht nichts ab).
    {
        const MapData m = karte(kartenNpc("held", "0 0 24").c_str());
        Scene s = szene(held(set("SET_GRAVITY", "0") + warte(500.0) + set("SET_ORIGIN", "0 0 300") + warte(3000.0)), m);
        mitSchwerkraft(s, flach, 4000.0);
        const Actor& a = s.actors.front();
        pruefe(nah(a.at(3000.0).pos[2], 300.0, 0.01), "g3 SET_GRAVITY 0: schwebt nach SET_ORIGIN auf 300 (" +
                                                            std::to_string(a.at(3000.0).pos[2]) + ")");
    }
    // g4 - set ( SET_GRAVITY, 200 ): nach 1 s Fall 100 tiefer (z0 - g/2 t^2).
    {
        const MapData m = karte(kartenNpc("held", "0 0 24").c_str());
        Scene s = szene(held(set("SET_GRAVITY", "200") + warte(500.0) + set("SET_ORIGIN", "0 0 300") + warte(3000.0)), m);
        mitSchwerkraft(s, flach, 4000.0);
        const Actor& a = s.actors.front();
        pruefe(nah(a.at(1500.0).pos[2], 200.0, 0.01), "g4 SET_GRAVITY 200: 1 s nach SET_ORIGIN 100 tiefer (" +
                                                            std::to_string(a.at(1500.0).pos[2]) + ")");
    }
    // g5 - SET_GRAVITY auf eine Tuer (kein client): Q3_SetGravity meldet
    // "is not an NPC/player" und tut nichts.
    {
        const MapData m = karte("{\n\"classname\" \"func_door\"\n\"targetname\" \"tuer\"\n\"model\" \"*1\"\n}\n");
        const Scene s = szene("affect ( \"tuer\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n" + set("SET_GRAVITY", "0") + "}\r\n", m);
        bool leer = true;
        for (const Actor& a : s.actors) { leer = leer && a.eigeneSchwerkraft.empty(); }
        pruefe(leer, "g5 SET_GRAVITY auf eine Tuer: nichts");
    }
    // y1 - SET_YAWSPEED liest die Engine mit atof (Q3_Interface.cpp:9085-9087):
    // "fast" ist 0, also 60 Grad/s. Der Ablauf rechnete schon so (ablauf.cpp),
    // die Szene nahm std::stof - das wirft, und es galten 330 Grad/s.
    {
        const MapData m = karte(kKarte2);
        const Scene s = szene(held(set("SET_YAWSPEED", "fast") + setZahl("SET_DYAW", "0.000")), m);
        const Actor& a = s.actors.front();
        pruefe(gierNah(gier(a, 750.0), 45.0F, 1.0F), "y1 SET_YAWSPEED \"fast\" = atof 0: 60 Grad/s, nach 750 ms 45 (" +
                                                         std::to_string(gier(a, 750.0)) + ")");
    }
    // P1 - Leistung: der Durchgang der Schwerkraft fragte je Figur und Takt
    // das ganze Actor::at (Animationen, Waffen, Blickziel ...) nur fuer Ort,
    // Verhalten und "fort". Der schnelle Durchlauf muss Bit fuer Bit dasselbe
    // ergeben wie der alte Weg (SchwerkraftHilfe::nachActorAt).
    {
        auto bahn = std::make_shared<Roff>();
        bahn->fassung = 1;
        bahn->bildMs = 100;
        bahn->lerp = 10;
        for (int k = 0; k < 10; ++k) {
            RoffBild b;
            b.ort[0] = 5.0F;
            b.ort[2] = 10.0F;
            bahn->bilder.push_back(b);
        }
        SzenenHilfe sh;
        sh.roff = [bahn](const std::string& nm) { return nm == "hoch" ? std::shared_ptr<const Roff>(bahn) : nullptr; };
        // Treppen und eine Rampe unter den Wegen.
        std::vector<Klotz> kloetze = {{-5000, 5000, -5000, 5000, 0}};
        for (int k = 0; k < 40; ++k) {
            const auto x0 = static_cast<float>(-200 + 70 * k);
            kloetze.push_back({x0, x0 + 60.0F, -500.0F + 20.0F * static_cast<float>(k % 5), 2600.0F,
                               static_cast<float>((k * 7) % 30)});
        }
        const BodenStrahl w = welt(kloetze, {{1000, 1600, 200, 900, 0, 200}});
        Scene schnell = grosseSzene(40, sh);
        Scene alt = schnell;
        SchwerkraftHilfe h;
        h.strahl = w;
        h.endeMs = schnell.durationMs + 5000.0;
        double msSchnell = 1e30;
        double msAlt = 1e30;
        for (int runde = 0; runde < 3; ++runde) {
            auto t0 = std::chrono::steady_clock::now();
            h.nachActorAt = false;
            schwerkraftEinrechnen(schnell, h);
            auto t1 = std::chrono::steady_clock::now();
            h.nachActorAt = true;
            schwerkraftEinrechnen(alt, h);
            auto t2 = std::chrono::steady_clock::now();
            msSchnell = std::min(msSchnell, std::chrono::duration<double, std::milli>(t1 - t0).count());
            msAlt = std::min(msAlt, std::chrono::duration<double, std::milli>(t2 - t1).count());
        }
        std::size_t figuren = 0;
        std::size_t takte = 0;
        for (const Actor& a : schnell.actors) {
            if (!a.hoehe.empty()) { ++figuren; }
            takte += a.hoehe.size();
        }
        char zeile[200];
        std::snprintf(zeile, sizeof(zeile), "P1 %zu Figuren, %zu Takte bis %.0f ms: schnell %.1f ms, alt (Actor::at) %.1f ms, Hash %016llx",
                      figuren, takte, h.endeMs, msSchnell, msAlt, static_cast<unsigned long long>(hoehenHash(schnell)));
        std::printf("  info  %s\n", zeile);
        pruefe(figuren == 40U && hoehenHash(schnell) == hoehenHash(alt), "P1 schneller Durchlauf = Actor::at, Bit fuer Bit");
        pruefe(msSchnell * 4.0 < msAlt, "P1 ... und mindestens viermal so schnell");
        // P2 - rc601 (bewegung, Wege): was prepareScene nach jeder Aenderung im
        // Missions-Tab fuer die Wege rechnet, auf einer grossen Karte (900
        // Wegpunkte in target-Ketten wie taspir1, 60 Laufziele, die sich an das
        // Netz haengen): das Wegnetz (einmal je Entity-Stand) und dann die
        // Szene, deren 10 Figuren je 6 Ziele ueber das Netz ansteuern - kalt
        // (alle Plaene neu) und warm (prepareScene baut die Szene dreimal, den
        // Ablauf zweimal; dieselben Plaene kommen aus dem Zwischenspeicher).
        std::string netzText;
        for (int i = 0; i < 900; ++i) {
            netzText += wegpunkt(("wp" + std::to_string(i)).c_str(),
                                 (std::to_string((i % 30) * 100) + " " + std::to_string((i / 30) * 100) + " 24").c_str(),
                                 ("wp" + std::to_string(i + 1)).c_str());
        }
        for (int i = 0; i < 60; ++i) {
            netzText += kartenZiel(("ng" + std::to_string(i)).c_str(),
                                   (std::to_string((i % 10) * 290 + 20) + " " + std::to_string((i / 10) * 480 + 20) + " 24").c_str());
        }
        std::string netzSkript;
        for (int f = 0; f < 10; ++f) {
            netzText += kartenNpc(("lauf" + std::to_string(f)).c_str(), (std::to_string(50 + f * 280) + " 60 24").c_str());
            netzSkript += "affect ( \"lauf" + std::to_string(f) + "\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n" +
                          set("SET_RUNNING", "true");
            for (int r = 0; r < 6; ++r) {
                netzSkript += set("SET_NAVGOAL", "ng" + std::to_string((f * 7 + r * 13) % 60)) + warte(6000.0);
            }
            netzSkript += "}\r\n";
        }
        const MapData netzKarte = karte(netzText.c_str());
        const auto t0 = std::chrono::steady_clock::now();
        const std::shared_ptr<const NavWelt> nw = navWeltAusEntities(netzKarte.entities);
        const double msNetz = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
        SzenenHilfe hn;
        hn.nav = nw;
        const auto t1 = std::chrono::steady_clock::now();
        const Scene kalt = szene(netzSkript, netzKarte, &hn);
        const double msKalt = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t1).count();
        double msWarm = 1e30;
        for (int runde = 0; runde < 3; ++runde) {
            const auto t2 = std::chrono::steady_clock::now();
            const Scene warm = szene(netzSkript, netzKarte, &hn);
            msWarm = std::min(msWarm, std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t2).count());
        }
        std::size_t stuecke = 0;
        std::size_t angekommen = 0;
        for (const Actor& a : kalt.actors) {
            for (const ActorStep& st : a.steps) {
                if (st.kind != ActorStep::Kind::WalkTo) { continue; }
                ++stuecke;
                if (st.ankunftMs >= 0.0) { ++angekommen; }
            }
        }
        std::printf("  info  P2 Wegnetz (900 Wegpunkte, 60 Ziele): %zu Knoten, %d Kanten, %.1f ms; Szene mit 10 Figuren x 6 "
                    "Zielen ueber das Netz (%zu Stuecke, %zu Ankuenfte): kalt %.1f ms, warm %.1f ms\n",
                    nw->netz->knoten.size() - 1U, nw->netz->zahlKanten(), msNetz, stuecke, angekommen, msKalt, msWarm);
        std::set<std::pair<std::string, Path>> laeufe;
        for (const Actor& a : kalt.actors) {
            for (const ActorStep& st : a.steps) {
                if (st.kind == ActorStep::Kind::WalkTo) { laeufe.insert({a.name, st.path}); }
            }
        }
        pruefe(laeufe.size() == 60U && angekommen > 0U,
               "P2 jeder der 60 Laeufe bewegt die Figur ueber das Netz (" + std::to_string(laeufe.size()) + ")");
    }
}

// =====================================================================
// 4) Wege wie im Spiel (rc601, Auftrag Routing)
// =====================================================================
//
// Der Betreuer: "das mit dem Laufen soll genauso gehen wie ingame bitte".
// Erwartet nach NPC_MoveToGoal (NPC_move.cpp:892-955): STEER::GoTo, sonst
// NAV::GoTo ueber das Wegnetz, sonst STEER::Stop - in JEDEM Denkbild zu
// 50 ms, danach ein Pmove (PM_Friction 6, PM_Accelerate 12).
void wegeProben() {
    std::printf("\n== Wege wie im Spiel (STEER + NAV::GoTo + Pmove je Denkbild) ==\n");
    const std::string geh = set("SET_WALKING", "true") + setZahl("SET_WALKSPEED", "100");
    const auto xBei = [](const Actor* a, double t) { return a != nullptr ? a->at(t).pos[0] : -1.0e9F; };
    // W1 - kein Wegnetz (ein Knoten: LoadFromEntitiesAndSaveToFile baut erst ab
    // vier Knoten Kanten), Ziel 900 weit: GetNearestNode ohne Kanten ->
    // WAYPOINT_NONE, NAV::GoTo -> STEER::Stop in jedem Denkbild. Die Figur steht.
    {
        const MapData m = karte((kartenNpc("held", "0 0 24") + kartenZiel("weit", "900 0 24")).c_str());
        const Scene s = szene(held(geh + set("SET_NAVGOAL", "weit") + warte(9000.0)), m);
        const float x = xBei(figur(s, "held"), 8000.0);
        pruefe(std::fabs(x) < 0.5F, "W1 900 weit ohne Wegnetz: die Figur steht (x bei 8 s: " + std::to_string(x) + ")");
    }
    // W2 - ... und ein dowait auf den Lauf wird nie fertig (TID_MOVE_NAV bleibt).
    {
        const MapData m = karte((kartenNpc("a", "0 0 24") + kartenZiel("weit", "900 0 24")).c_str());
        AblaufWelt w;
        w.karte = &m;
        const Ablauf a = simuliereAblauf(lies(inA("\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"weit\" );\n\t}\n"
                                                  "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n")),
                                         "", w);
        pruefe(zeitVon(a, "a", "print", "da") < 0.0,
               "W2 900 weit ohne Wegnetz: dowait haengt wie im Spiel (" + std::to_string(zeitVon(a, "a", "print", "da")) + ")");
    }
    // W3 - ueber Eck: Kette w2 -> w0 -> w1 -> ziel (Ziel ohne Auto-Kante). Das
    // Ziel liegt 849 weit (ueber 500: SafeToGoTo nein), also NAV::GoTo: A* w0,
    // w1, ziel. Die Figur geht erst die Kette entlang (+x) und biegt erst ab,
    // wenn w1 im Radius ist - nicht diagonal.
    const std::string eckKarte = kartenNpc("held", "0 0 24") + wegpunkt("w0", "0 0 24", "w1") +
                                 wegpunkt("w1", "600 0 24", "ziel") + zielOhneAuto("ziel", "600 600 24") +
                                 wegpunkt("w2", "-600 0 24", "w0");
    {
        const MapData m = karte(eckKarte.c_str());
        const Scene s = szene(held(geh + set("SET_NAVGOAL", "ziel") + warte(20000.0)), m);
        const Actor* a = figur(s, "held");
        float y = 1.0e9F;
        double t = 0.0;
        for (; a != nullptr && t < 20000.0; t += 10.0) {
            const ActorState st = a->at(t);
            if (st.pos[0] >= 150.0F) {
                y = st.pos[1];
                break;
            }
        }
        pruefe(std::fabs(y) < 1.0F, "W3 ueber Eck: bei x = 150 noch auf der Kette, y = " + std::to_string(y) + " (" +
                                         std::to_string(t) + " ms)");
        // Angekommen heisst fuer STEER::Reached: im Radius 12 oder das Ziel im
        // Kasten der Figur (+-16 und das Epsilon 1 von SV_LinkEntity) - dann
        // rollt sie noch aus.
        const ActorState ende = a != nullptr ? a->at(19000.0) : ActorState{};
        pruefe(std::fabs(ende.pos[0] - 600.0F) < 20.0F && std::fabs(ende.pos[1] - 600.0F) < 20.0F,
               "W3 ... und kommt am Ziel an (" + std::to_string(ende.pos[0]) + " " + std::to_string(ende.pos[1]) + ")");
    }
    // W4 - Pmove je Denkbild, gerade 100 weit (unter 110: SafeToGoTo sofort
    // ja), Tempo 100 aus dem Stand mit Blick zum Ziel. Erstes Denkbild bei 50
    // ms: Seek will 100, ps.speed 100; PM_Friction (Stand: nichts), PM_Accelerate
    // 12*0.05*100 = 60 -> 3 Einheiten. Dann Reibung 30 (unter 100: control 100)
    // und +60/+40/+30: 7,5 / 12,5 / 17,5.
    {
        const MapData m = karte((kartenNpc("held", "0 0 24") + kartenZiel("nah", "100 0 24")).c_str());
        const Scene s = szene(held(geh + set("SET_NAVGOAL", "nah") + warte(5000.0)), m);
        const Actor* a = figur(s, "held");
        const float x1 = xBei(a, 50.0);
        const float x2 = xBei(a, 100.0);
        const float x3 = xBei(a, 150.0);
        const float x4 = xBei(a, 200.0);
        pruefe(nah(x1, 3.0, 0.01) && nah(x2, 7.5, 0.01) && nah(x3, 12.5, 0.01) && nah(x4, 17.5, 0.01),
               "W4 Pmove je Denkbild: x = 3 / 7,5 / 12,5 / 17,5 (" + std::to_string(x1) + " / " + std::to_string(x2) +
                   " / " + std::to_string(x3) + " / " + std::to_string(x4) + ")");
    }
    // W5 - 390 weit ohne Netz: im ersten Denkbild setzt SafeToGoTo erst die
    // Timer (MoveTrace frei -> DURATION 2000) und sagt nein; NAV::GoTo ohne
    // Netz -> STEER::Stop. Die Figur geht ein Denkbild spaeter los.
    {
        const MapData m = karte((kartenNpc("held", "0 0 24") + kartenZiel("mittel", "390 0 24")).c_str());
        const Scene s = szene(held(geh + set("SET_NAVGOAL", "mittel") + warte(9000.0)), m);
        const Actor* a = figur(s, "held");
        const float x1 = xBei(a, 50.0);
        const float x2 = xBei(a, 100.0);
        pruefe(nah(x1, 0.0, 0.01) && nah(x2, 3.0, 0.01),
               "W5 390 weit: erstes Denkbild steht (Timer), dann los: x = 0 / 3 (" + std::to_string(x1) + " / " +
                   std::to_string(x2) + ")");
        // W6 - (bei 2100 ist sie noch 182 weit, also nicht unter 110)
        // DURATION (gesetzt bei 50 auf 2050) laeuft ab, wenn time <
        // level.time (TIMER_Done), also im Denkbild 2100; CHECK (1550) auch:
        // wieder ein Denkbild mit nein und Stop. Dessen Pmove bringt die Figur
        // von 2050 nach 2100 nur 3,5 weit (Reibung 30, kein Antrieb) statt 5.
        const float d = xBei(a, 2100.0) - xBei(a, 2050.0);
        const float d0 = xBei(a, 2050.0) - xBei(a, 2000.0);
        const float d1 = xBei(a, 2150.0) - xBei(a, 2100.0);
        pruefe(nah(d0, 5.0, 0.01) && nah(d, 3.5, 0.01) && nah(d1, 5.0, 0.01),
               "W6 alle 2050 ms ein Stop-Denkbild: " + std::to_string(d0) + " / " + std::to_string(d) + " / " +
                   std::to_string(d1) + " Einheiten je Denkbild");
    }
    // W7 - der Weg ueber Eck in Stuecken nach der Konvention der Zeitleiste
    // und des Missions-Tabs: gleicher path, nahtlos (endMs == startMs), alle
    // ausser dem letzten teilweg, das letzte endet am Ziel.
    {
        const MapData m = karte(eckKarte.c_str());
        const Scene s = szene(held(geh + set("SET_NAVGOAL", "ziel") + warte(20000.0)), m);
        const Actor* a = figur(s, "held");
        std::vector<const ActorStep*> wege;
        if (a != nullptr) {
            for (const ActorStep& st : a->steps) {
                if (st.kind == ActorStep::Kind::WalkTo) { wege.push_back(&st); }
            }
        }
        bool gut = wege.size() >= 2U;
        for (std::size_t i = 0; gut && i < wege.size(); ++i) {
            gut = wege[i]->path == wege.front()->path && (i + 1 == wege.size() ? !wege[i]->teilweg : wege[i]->teilweg);
            if (gut && i + 1 < wege.size()) { gut = std::fabs(wege[i]->endMs - wege[i + 1]->startMs) < 0.5; }
        }
        if (gut) { gut = std::fabs(wege.back()->to[0] - 600.0F) < 20.0F && std::fabs(wege.back()->to[1] - 600.0F) < 20.0F; }
        std::string was;
        for (const ActorStep* w : wege) {
            char b[96];
            std::snprintf(b, sizeof(b), " [%.0f-%.0f %s (%.0f %.0f)]", w->startMs, w->endMs, w->teilweg ? "teil" : "ende",
                          w->to[0], w->to[1]);
            was += b;
        }
        pruefe(gut, "W7 ueber Eck: " + std::to_string(wege.size()) + " Stuecke nach der Stueck-Konvention:" + was);
    }
    // W8 - Ablauf und Szene sind sich einig: dowait endet in dem Denkbild, in
    // dem UpdateGoal die Ankunft sieht - der Ort nach dem Pmove des Denkbilds
    // davor ist im Radius (12) oder das Ziel im Kasten der Figur (+-17).
    {
        const MapData m = karte((kartenNpc("a", "0 0 24") + kartenZiel("nah", "100 0 24")).c_str());
        AblaufWelt w;
        w.karte = &m;
        const std::string befehle = "\tset ( \"SET_WALKING\", \"true\" );\n\tset ( \"SET_WALKSPEED\", 100 );\n"
                                    "\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"nah\" );\n\t}\n"
                                    "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n";
        const Ablauf ab = simuliereAblauf(lies(inA(befehle)), "", w);
        const Scene s = buildScene(ab.flach, m);
        const Actor* a = figur(s, "a");
        double ankunft = -1.0;
        for (int k = 1; a != nullptr && k < 200; ++k) {
            const ActorState st = a->at(50.0 * k);
            const float dx = 100.0F - st.pos[0];
            if (dx * dx + st.pos[1] * st.pos[1] < 144.0F || (std::fabs(dx) < 17.0F && std::fabs(st.pos[1]) < 17.0F)) {
                ankunft = 50.0 * (k + 1);
                break;
            }
        }
        const double t = zeitVon(ab, "a", "print", "da");
        pruefe(ankunft > 0.0 && nah(t, ankunft, 0.5),
               "W8 dowait = Ankunft in der Szene (" + std::to_string(t) + " / " + std::to_string(ankunft) + ")");
    }
    // W9 - BS_NOCLIP: NPC_BSNoClip (NPC_behavior.cpp:1182-1212 MD) ruft weder
    // STEER noch NAV, sondern setzt ucmd gerade aufs Ziel; PM_NoclipMove
    // (bg_pmove.cpp:4860-4939) skaliert mit PM_CmdScale = ps.speed * max /
    // (127 * total). ps.speed setzt nur STEER (Activate 0, DeActivate mSpeed)
    // oder SET_WALKSPEED/SET_RUNSPEED (Q3_Interface.cpp:3621-3657). Eine Figur,
    // die noch nie gelaufen ist, hat ps.speed 0: sie bleibt stehen, und ein
    // dowait auf den Lauf haengt - in Szene und Ablauf.
    {
        const MapData m = karte((kartenNpc("a", "0 0 24") + kartenZiel("weit", "900 0 24")).c_str());
        AblaufWelt w;
        w.karte = &m;
        const std::string befehle = "\tset ( \"SET_BEHAVIOR_STATE\", \"BS_NOCLIP\" );\n"
                                    "\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"weit\" );\n\t}\n"
                                    "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n";
        const Ablauf ab = simuliereAblauf(lies(inA(befehle)), "", w);
        const Scene s = buildScene(ab.flach, m);
        const float x = xBei(figur(s, "a"), 8000.0);
        const double t = zeitVon(ab, "a", "print", "da");
        pruefe(std::fabs(x) < 0.01F && t < 0.0,
               "W9 BS_NOCLIP mit ps.speed 0: steht, dowait haengt (x bei 8 s: " + std::to_string(x) + ", dowait " +
                   std::to_string(t) + ")");
    }
    // W9b - ... aber sie dreht sich zum Ziel: NPC_BSNoClip setzt desiredYaw in
    // jedem Denkbild (vectoangles), NPC_UpdateAngles dreht mit 330 Grad/s.
    {
        const MapData m = karte((kartenNpc("a", "0 0 24") + kartenZiel("nord", "0 900 24")).c_str());
        const Scene s = szene("affect ( \"a\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n" +
                                  set("SET_BEHAVIOR_STATE", "BS_NOCLIP") + set("SET_NAVGOAL", "nord") + warte(3000.0) +
                                  "}\r\n",
                              m);
        const Actor* a = figur(s, "a");
        const ActorState st = a != nullptr ? a->at(1000.0) : ActorState{};
        pruefe(a != nullptr && nah(st.angles[1], 90.0, 0.5) && std::fabs(st.pos[1]) < 0.01F,
               "W9b BS_NOCLIP mit ps.speed 0: dreht sich zum Ziel, ohne zu fahren (Gier " +
                   std::to_string(st.angles[1]) + ", y " + std::to_string(st.pos[1]) + ")");
    }
    // W10 - BS_NOCLIP nach SET_WALKSPEED 100 (ps.speed 100), Blick zum Ziel:
    // ucmd 127/0/0, wishspeed 100. PM_NoclipMove: Reibung pm_friction * 1,5
    // = 9 (control mindestens 100: -45 je Denkbild), PM_Accelerate 12 * 0,05
    // * 100 = 60. Geschwindigkeit 60 / 75, dann im dritten Denkbild eine
    // Eigenheit der Engine: VectorNormalize (q_math.c:1141) multipliziert mit
    // dem Kehrwert, 893,25 * (1/893,25) ist 0,99999994, floor(126,99999) =
    // 126 - wishspeed 100 * 126/127, Geschwindigkeit 89,53; danach wieder
    // 127 und 100. x = 3 / 6,75 / 11,2264 / 16,2264. Kein Wegnetz noetig
    // (900 weit). PmoveSingle kehrt nach
    // PM_NoclipMove zurueck - PM_Footsteps waehlt keine Laufanimation. Und
    // dowait endet bei der Ankunft der Szene.
    {
        const MapData m = karte((kartenNpc("a", "0 0 24") + kartenZiel("weit", "900 0 24")).c_str());
        AblaufWelt w;
        w.karte = &m;
        const std::string befehle = "\tset ( \"SET_BEHAVIOR_STATE\", \"BS_NOCLIP\" );\n"
                                    "\tset ( \"SET_WALKSPEED\", 100 );\n"
                                    "\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"weit\" );\n\t}\n"
                                    "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n";
        const Ablauf ab = simuliereAblauf(lies(inA(befehle)), "", w);
        const Scene s = buildScene(ab.flach, m);
        const Actor* a = figur(s, "a");
        const float x1 = xBei(a, 50.0);
        const float x2 = xBei(a, 100.0);
        const float x3 = xBei(a, 150.0);
        const float x4 = xBei(a, 200.0);
        pruefe(nah(x1, 3.0, 0.001) && nah(x2, 6.75, 0.001) && nah(x3, 11.22638, 0.001) && nah(x4, 16.22638, 0.001),
               "W10 BS_NOCLIP PM_NoclipMove: x = 3 / 6,75 / 11,2264 / 16,2264 (" + std::to_string(x1) + " / " +
                   std::to_string(x2) + " / " + std::to_string(x3) + " / " + std::to_string(x4) + ")");
        const std::string anim = a != nullptr ? a->at(1000.0).animation : std::string("?");
        pruefe(anim == "BOTH_STAND1", "W10 ... ohne Laufanimation (" + anim + ")");
        const double ankunft = a != nullptr ? ankunftVon(*a) : -1.0;
        const double t = zeitVon(ab, "a", "print", "da");
        pruefe(ankunft > 0.0 && nah(t, ankunft, 0.5),
               "W10 ... dowait = Ankunft in der Szene (" + std::to_string(t) + " / " + std::to_string(ankunft) + ")");
    }
}

// =====================================================================
// 5) Offene Punkte aus der Durchsicht (R5-R8, rc601)
// =====================================================================
void offenePunkte() {
    std::printf("\n== Offene Punkte der Durchsicht (R5-R8) ==\n");
    const BodenStrahl flach = welt({{-5000, 5000, -5000, 5000, 0}}, {});
    // R5 - NPC_UpdateAngles (NPC_utils.cpp:264-281 MD): ein Rocket Trooper ohne
    // Feind dreht mit yawSpeed 1 - "just slowly lookin' around" - egal, was
    // .npc oder SET_YAWSPEED sagen: 60 + 3 = 63 Grad/s. Mit WP_EMPLACED_GUN
    // gilt yawSpeed 20: 120 Grad/s.
    {
        const MapData m = karte(kKarte2);
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tjedi\n\tclass\tCLASS_ROCKETTROOPER\n\tyawSpeed\t90\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        const Scene s = szene(held(set("SET_DYAW", "0") + setZahl("SET_YAWSPEED", "150")), m, &h);
        const float g = gier(*figur(s, "held"), 750.0);
        pruefe(gierNah(g, 42.75F, 0.5F), "R5 Rocket Trooper ohne Feind: 63 Grad/s, nach 750 ms bei 42,75 (" + std::to_string(g) + ")");
        NpcMap npcs2;
        parseNpcFile("jedi\n{\n\tplayerModel\tjedi\n\tweapon\tWP_EMPLACED_GUN\n}\n", npcs2);
        SzenenHilfe h2;
        h2.npcs = &npcs2;
        const Scene t = szene(held(set("SET_DYAW", "0")), m, &h2);
        const float g2 = gier(*figur(t, "held"), 375.0);
        pruefe(gierNah(g2, 45.0F, 0.5F), "R5 WP_EMPLACED_GUN: yawSpeed 20, 120 Grad/s, nach 375 ms bei 45 (" + std::to_string(g2) + ")");
    }
    // R6 - PM_StepSlideMove (bg_slidemove.cpp:368-416 MD): die Stufe je Klasse -
    // ATST 70, Rancor 48 (Mutant 64), maxs[2] <= 0 nur 4, sonst STEPSIZE 18.
    // Ein ATST steigt auf einen Block von 40 (Ursprung 64), eine normale Figur
    // nicht.
    {
        const BodenStrahl stufe = welt({{-5000, 5000, -5000, 5000, 0}, {200, 400, -100, 100, 40}}, {});
        const MapData m = karte((kartenNpc("held", "100 0 24") + kartenZiel("weiter", "450 0 24")).c_str());
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tatst\n\tclass\tCLASS_ATST\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        Scene s = szene(held(set("SET_WALKING", "true") + set("SET_NAVGOAL", "weiter") + warte(8000.0)), m, &h);
        SchwerkraftHilfe sh;
        sh.strahl = stufe;
        sh.endeMs = 9000.0;
        schwerkraftEinrechnen(s, sh);
        float zAuf = -1.0F;
        for (double t = 0.0; t < 8000.0; t += 50.0) {
            const ActorState st = s.actors.front().at(t);
            if (st.pos[0] > 260.0F && st.pos[0] < 340.0F) {
                zAuf = st.pos[2];
                break;
            }
        }
        pruefe(nah(zAuf, 64.0, 0.5), "R6 ATST: Stufe 70 - steigt auf den Block von 40 (" + std::to_string(zAuf) + ")");
    }
    // R7 - STEER::DeActivate (g_navigator.cpp:4170-4177): BUTTON_WALKING haengt
    // an der AKTUELLEN Geschwindigkeit (mSpeed < walkSpeed + 5), danach
    // NPC_ApplyScriptFlags (SCF_RUNNING/SCF_WALKING gehen vor). In BS_CINEMATIC
    // ohne Schalter, walkSpeed 150 und runSpeed 300: das erste Denkbild bringt
    // aus dem Stand 150 (mMaxForce), unter 155 - die Figur GEHT erst, dann
    // laeuft sie. (Bei 90/300 sieht man es nicht: dann sind schon 150 ein Lauf,
    // und vor dem Ziel kommt sie an, bevor sie unter 95 faellt.)
    {
        const MapData m = karte((kartenNpc("held", "0 0 24", "\"spawnflags\" \"32\"\n") + kartenZiel("nah", "100 0 24")).c_str());
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tjedi\n\twalkSpeed\t150\n\trunSpeed\t300\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        const Scene s = szene(held(set("SET_NAVGOAL", "nah") + warte(4000.0)), m, &h);
        const Actor& a = s.actors.front();
        const std::string erst = a.at(25.0).animation;
        const std::string dann = a.at(75.0).animation;
        pruefe(erst == "BOTH_WALK1" && dann == "BOTH_RUN1",
               "R7 BS_CINEMATIC ohne Schalter: im ersten Denkbild 150 < 155 gehen, dann laufen (" + erst + ", " + dann + ")");
        const Scene r = szene(held(set("SET_RUNNING", "true") + set("SET_NAVGOAL", "nah") + warte(4000.0)), m, &h);
        bool immerLauf = true;
        for (double t = 25.0; t < 4000.0; t += 25.0) {
            const ActorState st = r.actors.front().at(t);
            if (st.moving && st.animation != "BOTH_RUN1") { immerLauf = false; }
        }
        pruefe(immerLauf, "R7 mit SET_RUNNING bleibt es die Laufanimation (NPC_ApplyScriptFlags)");
    }
    // R8 - Schwerkraft unter 0 (PM_WalkMove, bg_pmove.cpp:4259-4273: velocity[2]
    // -= gravity * frametime, in die Luft; PM_StepSlideMove(1)): die Figur steigt
    // bis an die Decke. Decke bei 300: der Kopf (maxs[2] 40) stoesst an, der
    // Ursprung bleibt bei 260.
    {
        const BodenStrahl mitDecke = welt({{-5000, 5000, -5000, 5000, 0}, {-200, 200, -200, 200, 300}}, {});
        const MapData m = karte(kartenNpc("held", "0 0 24").c_str());
        Scene s = szene(held(warte(500.0) + set("SET_GRAVITY", "-800") + warte(4000.0)), m);
        SchwerkraftHilfe sh;
        sh.strahl = mitDecke;
        sh.endeMs = 5000.0;
        schwerkraftEinrechnen(s, sh);
        const float z0 = s.actors.front().at(500.0).pos[2];
        const float z1 = s.actors.front().at(3000.0).pos[2];
        pruefe(nah(z0, 24.0, 0.5) && nah(z1, 260.0, 0.5),
               "R8 SET_GRAVITY -800: steigt bis an die Decke (" + std::to_string(z0) + " -> " + std::to_string(z1) + ")");
    }
    // R8b - target_gravity_change (g_target.cpp:937-965): GLOBAL setzt g_gravity
    // (ab dem naechsten ClientThink fuer alle ohne eigene Schwerkraft), sonst
    // ps.gravity = floor(speed) des Ausloesers. Nach dem use mit gravity 0
    // faellt eine Figur nach SET_ORIGIN in die Luft nicht mehr.
    {
        const MapData m = karte((kartenNpc("held", "0 0 24") +
                                 "{\n\"classname\" \"target_gravity_change\"\n\"targetname\" \"schwerelos\"\n"
                                 "\"gravity\" \"0\"\n\"spawnflags\" \"1\"\n\"origin\" \"0 0 0\"\n}\n" +
                                 "{\n\"classname\" \"target_gravity_change\"\n\"targetname\" \"leicht\"\n"
                                 "\"gravity\" \"200.7\"\n\"origin\" \"0 0 0\"\n}\n")
                                    .c_str());
        Scene s = szene(held(warte(1500.0) + set("SET_ORIGIN", "0 0 500") + warte(3000.0)), m);
        schwerkraftWechsel(s, m, {SchwerkraftBenutzung{1000.0, "schwerelos", ""}});
        SchwerkraftHilfe sh;
        sh.strahl = flach;
        sh.endeMs = 5000.0;
        schwerkraftEinrechnen(s, sh);
        const float z = s.actors.front().at(3000.0).pos[2];
        pruefe(nah(z, 500.0, 0.5), "R8b target_gravity_change GLOBAL 0: schwebt nach SET_ORIGIN (" + std::to_string(z) + ")");
        Scene t = szene(held(warte(1500.0) + set("SET_ORIGIN", "0 0 500") + warte(3000.0)), m);
        schwerkraftWechsel(t, m, {SchwerkraftBenutzung{1000.0, "leicht", "held"}});
        schwerkraftEinrechnen(t, sh);
        // floor(200.7) = 200: nach 1 s 100 tiefer (z0 - g/2 t^2, je Takt genau)
        const float z2 = t.actors.front().at(2500.0).pos[2];
        pruefe(nah(z2, 400.0, 0.5), "R8b ohne GLOBAL: ps.gravity = floor(200,7) = 200 fuer den Ausloeser (" +
                                        std::to_string(z2) + ")");
    }
}

// --- rc601 (bewegung, Wege): Proben gegen eine echte .bsp --------------------
//
// bewegungtest --bsp <datei.bsp>: die Spuren (bhed/kollision.h) und das
// Wegnetz mit Spuren an einer Karte der Mod - wie viele Knoten SpawnedPoint
// behaelt, wie lange der Bau dauert, und ob ein Strahl von jedem Knoten nach
// unten den Boden etwa 24 darunter trifft (der Ursprung steht 24 ueber dem
// Boden, wenn der Designer den Kasten auf den Boden gestellt hat).
void echteKarte(const char* datei) {
    std::printf("\n== Spuren an %s ==\n", datei);
    std::ifstream f(datei, std::ios::binary);
    const std::string b((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
    KollisionsKarte k;
    const auto t0 = std::chrono::steady_clock::now();
    const bool ok = leseKollision(b, k);
    const double msLesen = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
    std::printf("  lesen %s: %zu Brushes, %zu Knoten, %zu Blaetter, %.1f ms\n", ok ? "ok" : "FEHL", k.pinsel.size(),
                k.knoten.size(), k.blaetter.size(), msLesen);
    MapData m;
    std::string err;
    (void)readBsp(b, m, &err);
    const NavSpurFn spur = [&k](const NavVec& a, const NavVec& mn, const NavVec& mx, const NavVec& e, int, std::uint32_t maske) {
        const KollisionsSpur w = kollisionsSpur(k, a.data(), mn.data(), mx.data(), e.data(), maske);
        NavSpur r;
        r.allsolid = w.allsolid;
        r.startsolid = w.startsolid;
        r.fraction = w.fraction;
        r.endpos = w.endpos;
        r.normal = w.normale;
        r.contents = w.inhalt;
        r.entity = w.fraction != 1.0F ? kNavWeltEntity : kNavKeineEntity;
        return r;
    };
    int ziele = 0;
    int imFesten = 0;
    int bodenNah = 0;
    for (const MapEntity& e : m.entities) {
        const std::string kl = e.classname;
        if (kl != "waypoint_navgoal" && kl != "waypoint" && kl != "waypoint_small" && kl != "point_combat") { continue; }
        ++ziele;
        NavVec o{};
        std::istringstream is(e.origin);
        is >> o[0] >> o[1] >> o[2];
        const NavVec o5{o[0], o[1], o[2] + 5.0F};
        const NavSpur s = spur(o, {-20, -20, 0}, {20, 20, 60}, o5, -1, kNavMaskNpcSolid | kNavBotClip);
        if (s.startsolid || s.allsolid || s.fraction < 1.0F) {
            ++imFesten;
            if (imFesten <= 8) {
                std::printf("    im Festen: %s %s (%s) start %d all %d f %.3f\n", kl.c_str(), e.targetname.c_str(),
                            e.origin.c_str(), s.startsolid ? 1 : 0, s.allsolid ? 1 : 0, static_cast<double>(s.fraction));
            }
        }
        const NavVec unten{o[0], o[1], o[2] - 200.0F};
        const NavSpur s2 = spur(o, {0, 0, 0}, {0, 0, 0}, unten, -1, kNavSolid | kNavTerrain | kNavMonsterClip);
        if (s2.fraction < 1.0F && std::fabs(o[2] - s2.endpos[2] - 24.0F) < 30.0F) { ++bodenNah; }
    }
    std::printf("  %d Knoten-Entities, %d davon im Festen (SpawnedPoint), %d mit Boden 0-54 darunter\n", ziele, imFesten,
                bodenNah);
    NavBauHilfe hilfe;
    hilfe.spur = spur;
    const auto t1 = std::chrono::steady_clock::now();
    const auto netz = baueNavNetz(m.entities, hilfe);
    const double msNetz = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t1).count();
    int inseln = 0;
    int schwebend = 0;
    for (std::size_t i = 1; i < netz->knoten.size(); ++i) {
        inseln += netz->knoten[i].insel ? 1 : 0;
        schwebend += netz->knoten[i].schwebend ? 1 : 0;
    }
    std::printf("  Wegnetz mit Spuren: %zu Knoten, %d Kanten, %d Inseln, %d schwebend, %.1f ms\n", netz->knoten.size() - 1U,
                netz->zahlKanten(), inseln, schwebend, msNetz);
    // rc601 (bewegung, Durchsicht 2): Laeufe auf der echten Karte mit Pmove
    // gegen die Waende - von Wegpunkt zu Wegpunkt (je der dritte nach dem
    // naechsten Knoten): wie viele kommen an, wie viele stehen ohne Weg, und
    // steckt der Kasten je in einer Wand (das darf nicht sein).
    auto nw = std::make_shared<NavWelt>();
    nw->netz = netz;
    nw->spur = spur;
    nw->boden = [&spur](float x, float y, float zOben, float zUnten, float& z) {
        const NavSpur r = spur({x, y, zOben}, {0, 0, 0}, {0, 0, 0}, {x, y, zUnten}, -1, kNavSolid | kNavTerrain | kNavMonsterClip);
        if (r.fraction >= 1.0F || r.startsolid) { return false; }
        z = r.endpos[2];
        return true;
    };
    int laeufe = 0;
    int an = 0;
    int nie = 0;
    int steckt = 0;
    double msPlan = 0.0;
    const int kn = static_cast<int>(netz->knoten.size()) - 1;
    for (int i = 1; i <= kn && laeufe < 40; i += std::max(1, kn / 40)) {
        const int j = ((i + 2) % kn) + 1;
        if (netz->knoten[static_cast<std::size_t>(i)].insel || netz->knoten[static_cast<std::size_t>(j)].insel) { continue; }
        LaufZustand st;
        st.ort = netz->knoten[static_cast<std::size_t>(i)].punkt;
        LaufWerte lw;
        lw.zielGesetzt = true;
        lw.ziel = netz->knoten[static_cast<std::size_t>(j)].punkt;
        lw.maxTempo = 200.0F;
        lw.gehTempo = 55.0F;
        const auto tp = std::chrono::steady_clock::now();
        const LaufPlan pl = planeLauf(*nw, st, lw, 0.0, 30000.0);
        msPlan += std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - tp).count();
        ++laeufe;
        if (pl.ankunftMs >= 0.0) { ++an; }
        if (pl.nie) { ++nie; }
        for (const LaufTakt& k : pl.takte) {
            const NavSpur r = spur(k.ort, {-16, -16, -24 + 18}, {16, 16, 40}, k.ort, -1, kNavSolid);
            if (r.startsolid || r.allsolid) {
                ++steckt;
                break;
            }
        }
    }
    std::printf("  Laeufe mit Pmove gegen die Waende: %d, angekommen %d, ohne Weg stehend %d, Kasten in einer Wand %d, %.1f ms\n",
                laeufe, an, nie, steckt, msPlan);
}

}  // namespace

// =====================================================================
// Durchsicht 2 (rc601, Paket bewegung)
// =====================================================================
//
// S - die Schwierigkeit (g_spskill). NPC_Begin (NPC_spawn.cpp:1828-1877 MD)
// richtet yawSpeed danach: Stormtrooper, Guard, Clonetrooper, SBD,
// Battledroid, Swamptrooper, Impworker und rodian2 auf 0 mal 0,75, auf 2 mal
// 1,5; Reborn, BoC, Shadowtrooper, Galen auf 1 mal 1,25, auf 2 mal 1,5 -
// "default:;": auf 3 (Jedi Master) gar nicht. "rodian" steht davor in der
// Kette und bekommt nichts. NPC_SetMiscDefaultData (NPC_spawn.cpp:335-346,
// 633-641 MD): Tusken ab 2 runSpeed 280 / walkSpeed 65, Sandkreatur ab 2
// runSpeed * 1,5 (int).
void schwierigkeitProben() {
    std::printf("\n== Durchsicht 2: Schwierigkeit (g_spskill) ==\n");
    const MapData m = karte(kKarte2);
    const auto rate = [&](const std::string& npc, int skill, const char* typ = "jedi") {
        NpcMap npcs;
        parseNpcFile(std::string(typ) + "\n{\n\tplayerModel\tjedi\n" + npc + "}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        if (skill >= 0) { h.schwierigkeit = skill; }
        // Ein eigener Typ fuer "rodian"/"rodian2": die Karte nennt "jedi".
        MapData mm = m;
        for (MapEntity& e : mm.entities) {
            if (e.classname == "NPC_spawner") {
                for (auto& [k, v] : e.keys) {
                    if (k == "NPC_type") { v = typ; }
                }
            }
        }
        const Scene s = szene(held(set("SET_DYAW", "0")), mm, &h);
        const Actor* a = figur(s, "held");
        return a != nullptr ? a->startDrehrate : -1.0F;
    };
    const std::string trooper = "\tclass\tCLASS_STORMTROOPER\n\tyawSpeed\t100\n";
    const std::string reborn = "\tclass\tCLASS_REBORN\n\tyawSpeed\t100\n";
    const float t0 = rate(trooper, 0);
    const float t1 = rate(trooper, 1);
    const float t2 = rate(trooper, 2);
    const float t3 = rate(trooper, 3);
    const float tv = rate(trooper, -1);
    pruefe(nah(t0, 285.0, 0.01) && nah(t1, 360.0, 0.01) && nah(t2, 510.0, 0.01) && nah(t3, 360.0, 0.01),
           "S1 Stormtrooper yawSpeed 100: Padawan 285 / Jedi 360 / Jedi Knight 510 / Jedi Master 360 Grad/s (" +
               std::to_string(t0) + " / " + std::to_string(t1) + " / " + std::to_string(t2) + " / " + std::to_string(t3) + ")");
    pruefe(nah(tv, 510.0, 0.01), "S1 ohne Einstellung gilt Jedi Knight wie Movie Duels (g_spskill 2): 510 (" + std::to_string(tv) + ")");
    const float r0 = rate(reborn, 0);
    const float r1 = rate(reborn, 1);
    const float r2 = rate(reborn, 2);
    const float r3 = rate(reborn, 3);
    pruefe(nah(r0, 360.0, 0.01) && nah(r1, 435.0, 0.01) && nah(r2, 510.0, 0.01) && nah(r3, 360.0, 0.01),
           "S2 Reborn yawSpeed 100: 360 / 435 / 510 / 360 Grad/s (" + std::to_string(r0) + " / " + std::to_string(r1) + " / " +
               std::to_string(r2) + " / " + std::to_string(r3) + ")");
    const float rv = rate("\tclass\tCLASS_REBORN\n", 1);
    pruefe(nah(rv, 397.5, 0.01), "S2 Reborn ohne yawSpeed (Vorgabe 90) auf Jedi: 60 + 3 * 112,5 = 397,5 (" + std::to_string(rv) + ")");
    const float ro = rate(trooper, 2, "rodian");
    const float ro2 = rate(reborn, 1, "rodian2");
    pruefe(nah(ro, 360.0, 0.01) && nah(ro2, 360.0, 0.01),
           "S3 'rodian' steht vorn in der Kette (nichts), 'rodian2' in der Trooper-Kette (auf 1 nichts, auch als Reborn): 360 / 360 (" +
               std::to_string(ro) + " / " + std::to_string(ro2) + ")");
    // Tusken und Sandkreatur: das Tempo beim Spawnen (dasselbe nimmt der Ablauf).
    const auto tempo = [&](const std::string& npc, int skill) {
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tjedi\n" + npc + "}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        h.schwierigkeit = skill;
        const Scene s = szene(held(set("SET_DYAW", "0")), m, &h);
        const auto f = ablaufTempo(s);
        return std::make_pair(f("held", true), f("held", false));
    };
    const std::string tusken = "\tclass\tCLASS_TUSKEN\n\twalkSpeed\t50\n\trunSpeed\t200\n";
    const auto k1 = tempo(tusken, 1);
    const auto k2 = tempo(tusken, 2);
    const auto k3 = tempo(tusken, 3);
    pruefe(nah(k1.first, 50.0, 0.01) && nah(k1.second, 200.0, 0.01) && nah(k2.first, 65.0, 0.01) && nah(k2.second, 280.0, 0.01) &&
               nah(k3.first, 65.0, 0.01) && nah(k3.second, 280.0, 0.01),
           "S4 Tusken: bis Jedi die .npc (50/200), ab Jedi Knight 65/280 (" + std::to_string(k1.first) + "/" +
               std::to_string(k1.second) + ", " + std::to_string(k2.first) + "/" + std::to_string(k2.second) + ", " +
               std::to_string(k3.first) + "/" + std::to_string(k3.second) + ")");
    const auto sc = tempo("\tclass\tCLASS_SAND_CREATURE\n\trunSpeed\t201\n", 2);
    const auto sc1 = tempo("\tclass\tCLASS_SAND_CREATURE\n\trunSpeed\t201\n", 1);
    pruefe(nah(sc.second, 301.0, 0.01) && nah(sc1.second, 201.0, 0.01),
           "S5 Sandkreatur runSpeed 201: Jedi Knight int(201 * 1,5) = 301, Jedi 201 (" + std::to_string(sc.second) + ", " +
               std::to_string(sc1.second) + ")");
    // Und es wirkt: ein Reborn auf Jedi dreht mit 397,5 Grad/s - nach 100 ms
    // also 39,75 Grad (von 90 auf 0 zu).
    {
        NpcMap npcs;
        parseNpcFile("jedi\n{\n\tplayerModel\tjedi\n\tclass\tCLASS_REBORN\n}\n", npcs);
        SzenenHilfe h;
        h.npcs = &npcs;
        h.schwierigkeit = 1;
        const Scene s = szene(held(set("SET_DYAW", "0")), m, &h);
        const float g = gier(*figur(s, "held"), 100.0);
        pruefe(gierNah(g, 90.0F - 39.75F, 0.5F), "S6 Reborn auf Jedi dreht mit 397,5 Grad/s: nach 100 ms bei 50,25 (" + std::to_string(g) + ")");
    }
}

// P3 - Durchsicht 2: was ein Eingriff im Missions-Tab kostet (prepareScene
// nach dem Loslassen: Ablauf + Szene) - einen Laufziel-Punkt um 10 Einheiten
// ziehen (neues Wegnetz, alle Plaene kalt) und eine Gangart einer Figur
// aendern (nur ihre Plaene kalt) - und dass die Abkuerzungen (navSchnellwegeAn)
// Bit fuer Bit dasselbe ergeben.
std::uint64_t ortsHash(const Scene& s) {
    std::uint64_t h = 1469598103934665603ULL;
    const auto dazu = [&h](const void* p, std::size_t n) {
        const auto* b = static_cast<const unsigned char*>(p);
        for (std::size_t k = 0; k < n; ++k) {
            h ^= b[k];
            h *= 1099511628211ULL;
        }
    };
    for (const Actor& a : s.actors) {
        for (const ActorStep& st : a.steps) {
            if (st.kind != ActorStep::Kind::WalkTo) { continue; }
            dazu(&st.startMs, sizeof(st.startMs));
            dazu(&st.endMs, sizeof(st.endMs));
            dazu(&st.ankunftMs, sizeof(st.ankunftMs));
            dazu(st.to, sizeof(st.to));
            if (st.lauf) {
                for (const LaufTakt& k : st.lauf->takte) { dazu(k.ort.data(), sizeof(float) * 3); }
            }
        }
    }
    return h;
}

void leistungEingriffe() {
    std::printf("\n== Durchsicht 2: Eingriffe im Missions-Tab (P3) ==\n");
    std::string netzText;
    for (int i = 0; i < 900; ++i) {
        netzText += wegpunkt(("wp" + std::to_string(i)).c_str(),
                             (std::to_string((i % 30) * 100) + " " + std::to_string((i / 30) * 100) + " 24").c_str(),
                             ("wp" + std::to_string(i + 1)).c_str());
    }
    std::string ziele[2];
    for (int v = 0; v < 2; ++v) {
        for (int i = 0; i < 60; ++i) {
            const int dx = (v == 1 && i == 17) ? 10 : 0;   // der gezogene Punkt
            ziele[v] += kartenZiel(("ng" + std::to_string(i)).c_str(),
                                   (std::to_string((i % 10) * 290 + 20 + dx) + " " + std::to_string((i / 10) * 480 + 20) + " 24").c_str());
        }
    }
    std::string figuren;
    std::string skript[2];
    for (int f = 0; f < 10; ++f) {
        figuren += kartenNpc(("lauf" + std::to_string(f)).c_str(), (std::to_string(50 + f * 280) + " 60 24").c_str());
        for (int v = 0; v < 2; ++v) {
            skript[v] += "affect ( \"lauf" + std::to_string(f) + "\", /*@AFFECT_TYPE*/ FLUSH )\r\n{\r\n" +
                         set((v == 1 && f == 3) ? "SET_WALKING" : "SET_RUNNING", "true");
            for (int r = 0; r < 6; ++r) { skript[v] += set("SET_NAVGOAL", "ng" + std::to_string((f * 7 + r * 13) % 60)) + warte(6000.0); }
            skript[v] += "}\r\n";
        }
    }
    const MapData vorher = karte((netzText + ziele[0] + figuren).c_str());
    const MapData gezogen = karte((netzText + ziele[1] + figuren).c_str());
    const auto bauenMit = [](const std::string& sk, const MapData& m, const std::shared_ptr<const NavWelt>& nav, double& ms) {
        const auto t0 = std::chrono::steady_clock::now();
        SzenenHilfe h;
        h.nav = nav ? nav : navWeltAusEntities(m.entities);
        AblaufWelt w;
        w.karte = &m;
        w.nav = h.nav;
        const Ablauf ab = simuliereAblauf(lies(sk), "", w);
        Scene sc = buildScene(ab.flach, m, &h);
        ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
        return sc;
    };
    const auto bauen = [&](const std::string& sk, const MapData& m, double& ms) { return bauenMit(sk, m, nullptr, ms); };
    double msStart = 0.0;
    double msZug = 0.0;
    double msGang = 0.0;
    const Scene a = bauen(skript[0], vorher, msStart);
    const Scene b = bauen(skript[0], gezogen, msZug);
    const Scene c = bauen(skript[1], gezogen, msGang);
    std::printf("  info  P3 Ablauf + Szene (10 Figuren x 6 Ziele, 900 Wegpunkte): erster Aufbau %.1f ms, Laufziel gezogen "
                "(Netz neu, alles kalt) %.1f ms, Gangart einer Figur %.1f ms\n",
                msStart, msZug, msGang);
    // Bit fuer Bit: dieselbe Szene ohne Zwischenspeicher der Plaene (Kennung
    // 0), je mit frisch gebautem Netz - einmal ohne, einmal mit Abkuerzungen.
    const auto frisch = [&](bool schnell) {
        navSchnellwegeAn(schnell);
        auto w = std::make_shared<NavWelt>();
        w->netz = baueNavNetz(gezogen.entities, NavBauHilfe{});
        w->kennung = 0;
        return std::shared_ptr<const NavWelt>(w);
    };
    double msLang = 0.0;
    const std::shared_ptr<const NavWelt> wLang = frisch(false);
    const Scene d = bauenMit(skript[1], gezogen, wLang, msLang);
    double msKurz = 0.0;
    const std::shared_ptr<const NavWelt> wKurz = frisch(true);
    const Scene e = bauenMit(skript[1], gezogen, wKurz, msKurz);
    navSchnellwegeAn(true);
    pruefe(wLang->netz->regionLinks == wKurz->netz->regionLinks && wLang->netz->regionKanten == wKurz->netz->regionKanten &&
               wLang->netz->regionZahl == wKurz->netz->regionZahl,
           "P3 Regionsverbindungen ueber die Nachbarn = ueber alle Knotenpaare (" + std::to_string(wKurz->netz->regionZahl) +
               " Regionen, " + std::to_string(wKurz->netz->regionKanten.size()) + " Verbindungen)");
    std::printf("  info  P3 dieselbe Szene ohne Abkuerzungen %.1f ms, mit %.1f ms\n", msLang, msKurz);
    pruefe(ortsHash(d) == ortsHash(e) && ortsHash(d) != 0U, "P3 Abkuerzungen aendern nichts: Wege Bit fuer Bit gleich (" +
                                                                 std::to_string(ortsHash(d)) + " / " + std::to_string(ortsHash(e)) + ")");
    // rc601 (bewegung, teil 3): dasselbe mit allen Figuren im selben Takt
    // (simuliereAblaufMitKoerpern) - was es kostet, und: wo keine Figur einer
    // anderen in die Spuren kommt, ist die Szene Bit fuer Bit dieselbe.
    {
        const auto mitKoerpern = [&](const std::string& sk, const MapData& m, double& ms, int& dg, std::size_t& geaendert) {
            const auto t0 = std::chrono::steady_clock::now();
            SzenenHilfe h;
            h.nav = navWeltAusEntities(m.entities);
            AblaufWelt w;
            w.karte = &m;
            w.nav = h.nav;
            const Ablauf ab = simuliereAblaufMitKoerpern(lies(sk), "", w, &dg);
            h.koerperPlaene = w.koerperPlaene;
            geaendert = w.koerperPlaene ? w.koerperPlaene->size() : 0U;
            Scene sc = buildScene(ab.flach, m, &h);
            ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
            return sc;
        };
        double msK = 0.0;
        int dgK = 0;
        std::size_t gK = 0;
        const Scene k = mitKoerpern(skript[1], gezogen, msK, dgK, gK);
        double msK2 = 0.0;
        int dgK2 = 0;
        std::size_t gK2 = 0;
        (void)mitKoerpern(skript[1], gezogen, msK2, dgK2, gK2);
        std::printf("  info  P4 mit allen Figuren im selben Takt: %.1f ms (noch einmal, warm: %.1f ms), %d Ablauf-Rechnungen, %zu Plaene geaendert\n",
                    msK, msK2, dgK, gK);
        if (gK == 0U) {
            pruefe(ortsHash(k) == ortsHash(c), "P4 ohne Beruehrung: die Szene ist Bit fuer Bit die ohne gemeinsamen Takt (" +
                                                   std::to_string(ortsHash(k)) + ")");
        } else {
            std::printf("  info  P4 hier beruehren sich Figuren - der Vergleich Bit fuer Bit steht in K2\n");
        }
        // rc601 integ: P4b - bekommt eine Rechnung des gemeinsamen Takts Bit fuer
        // Bit dieselben Eingaben wie die vorige, endet die Schleife ohne sie
        // (ablaufKoerperAbkuerzungAn). Das Ergebnis muss Bit fuer Bit dasselbe
        // sein wie mit der Rechnung.
        {
            ablaufKoerperAbkuerzungAn(false);
            double msOhne = 0.0;
            int dgOhne = 0;
            std::size_t gOhne = 0;
            const Scene ohne = mitKoerpern(skript[1], gezogen, msOhne, dgOhne, gOhne);
            ablaufKoerperAbkuerzungAn(true);
            double msMit = 0.0;
            int dgMit = 0;
            std::size_t gMit = 0;
            const Scene mit = mitKoerpern(skript[1], gezogen, msMit, dgMit, gMit);
            std::printf("  info  P4b gemeinsamer Takt ohne Abkuerzung %.1f ms, mit %.1f ms (%d Ablauf-Rechnungen, %zu Plaene geaendert)\n",
                        msOhne, msMit, dgMit, gMit);
            pruefe(ortsHash(ohne) == ortsHash(mit) && ortsHash(mit) != 0U && dgOhne == dgMit && gOhne == gMit,
                   "P4b Abkuerzung bei gleichen Eingaben: Szene Bit fuer Bit gleich (" + std::to_string(ortsHash(ohne)) + " / " +
                       std::to_string(ortsHash(mit)) + "), Rechnungen " + std::to_string(dgOhne) + "/" + std::to_string(dgMit));
        }
    }
    (void)a;
    (void)b;
    (void)c;
}

// --- Durchsicht 2: eine Welt aus achsparallelen Brushes fuer die Spuren ------
// CM_TraceThroughBrush (cm_trace.cpp MD) fuer Kaesten: sechs Ebenen, um den
// Kasten der Figur verschoben, mit SURFACE_CLIP_EPSILON 0,125.
struct ProbeKlotz {
    NavVec min{};
    NavVec max{};
    std::uint32_t inhalt = kNavSolid;
};
NavSpur probeSpur(const std::vector<ProbeKlotz>& welt, const NavVec& start, const NavVec& mins, const NavVec& maxs, const NavVec& ende,
                  std::uint32_t maske) {
    NavSpur r;
    r.endpos = ende;
    for (std::size_t bi = 0; bi < welt.size(); ++bi) {
        const ProbeKlotz& k = welt[bi];
        if ((k.inhalt & maske) == 0U) { continue; }
        float enter = -1.0F;
        float leave = 1.0F;
        bool startout = false;
        bool getout = false;
        NavVec normale{};
        bool raus = false;
        for (int a = 0; a < 3 && !raus; ++a) {
            for (int sg = 0; sg < 2 && !raus; ++sg) {
                const float s1 = sg == 0 ? 1.0F : -1.0F;
                const float dist = sg == 0 ? k.max[static_cast<std::size_t>(a)] - mins[static_cast<std::size_t>(a)]
                                           : -k.min[static_cast<std::size_t>(a)] + maxs[static_cast<std::size_t>(a)];
                const float d1 = s1 * start[static_cast<std::size_t>(a)] - dist;
                const float d2 = s1 * ende[static_cast<std::size_t>(a)] - dist;
                if (d2 > 0.0F) { getout = true; }
                if (d1 > 0.0F) { startout = true; }
                if (d1 > 0.0F && (d2 >= 0.125F || d2 >= d1)) {
                    raus = true;
                    break;
                }
                if (d1 <= 0.0F && d2 <= 0.0F) { continue; }
                if (d1 > d2) {
                    float f = (d1 - 0.125F) / (d1 - d2);
                    if (f < 0.0F) { f = 0.0F; }
                    if (f > enter) {
                        enter = f;
                        normale = {0, 0, 0};
                        normale[static_cast<std::size_t>(a)] = s1;
                    }
                } else {
                    float f = (d1 + 0.125F) / (d1 - d2);
                    if (f > 1.0F) { f = 1.0F; }
                    if (f < leave) { leave = f; }
                }
            }
        }
        if (raus) { continue; }
        if (!startout) {
            r.startsolid = true;
            r.entity = kNavWeltEntity;
            if (!getout) {
                r.allsolid = true;
                r.fraction = 0.0F;
            }
            continue;
        }
        if (enter < leave && enter > -1.0F && enter < r.fraction) {
            r.fraction = std::max(0.0F, enter);
            r.normal = normale;
            r.contents = k.inhalt;
            r.entity = kNavWeltEntity;
        }
    }
    for (int a = 0; a < 3; ++a) {
        r.endpos[static_cast<std::size_t>(a)] =
            start[static_cast<std::size_t>(a)] + r.fraction * (ende[static_cast<std::size_t>(a)] - start[static_cast<std::size_t>(a)]);
    }
    return r;
}

// F1 - Pmove gegen die Waende: PM_StepSlideMove/PM_SlideMove (bg_slidemove.cpp
// MD) schieben die Figur mit ihrem Kasten an Waenden entlang - sie geht nicht
// hindurch. Ziel 100 weit hinter einer Wand (unter 110: STEER::SafeToGoTo sagt
// sofort ja, STEER::Seek zieht geradeaus, AvoidCollisions lenkt ab - aber die
// Wand haelt).
void waendeProben() {
    std::printf("\n== Durchsicht 2: Pmove gegen die Waende (F1) ==\n");
    auto welt = std::make_shared<NavWelt>();
    const std::vector<ProbeKlotz> kloetze = {
        {{-2000, -2000, -16}, {2000, 2000, 0}, kNavSolid},   // Boden
        {{50, -500, 0}, {60, 500, 200}, kNavSolid},          // Wand quer
    };
    welt->spur = [kloetze](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int, std::uint32_t maske) {
        return probeSpur(kloetze, a, mi, ma, b, maske);
    };
    welt->boden = [](float, float, float zOben, float zUnten, float& z) {
        if (zOben < 0.0F || zUnten > 0.0F) { return false; }
        z = 0.0F;
        return true;
    };
    LaufZustand start;
    start.ort = {0.0F, 0.0F, 24.125F};
    LaufWerte w;
    w.zielGesetzt = true;
    w.ziel = {100.0F, 0.0F, 24.125F};
    w.maxTempo = 300.0F;
    w.gehTempo = 90.0F;
    const LaufPlan p = planeLauf(*welt, start, w, 0.0, 6000.0);
    float xMax = -1.0e9F;
    for (const LaufTakt& k : p.takte) { xMax = std::max(xMax, k.ort[0]); }
    pruefe(xMax <= 50.0F - 16.0F + 0.2F,
           "F1 Ziel hinter einer Wand (100 weit): der Kasten bleibt vor der Wand, x hoechstens 34 (" + std::to_string(xMax) + ")");
    // Schraeg an die Wand: sie gleitet an ihr entlang (y aendert sich), statt
    // stehen zu bleiben oder hindurchzugehen.
    LaufWerte w2 = w;
    w2.ziel = {100.0F, 40.0F, 24.125F};
    const LaufPlan p2 = planeLauf(*welt, start, w2, 0.0, 3000.0);
    float xMax2 = -1.0e9F;
    for (const LaufTakt& k : p2.takte) { xMax2 = std::max(xMax2, k.ort[0]); }
    pruefe(xMax2 <= 50.0F - 16.0F + 0.2F, "F1 ... schraeg: auch dann nicht hindurch (x " + std::to_string(xMax2) + ")");
    // Stufen: PM_StepSlideMove steigt bis step_size (18) hinauf - auf einen
    // Absatz von 16 ja, auf einen Block von 40 nicht.
    for (const float hoehe : {16.0F, 40.0F}) {
        auto w3 = std::make_shared<NavWelt>();
        const std::vector<ProbeKlotz> k3 = {
            {{-2000, -2000, -16}, {2000, 2000, 0}, kNavSolid},
            {{50, -500, 0}, {2000, 500, hoehe}, kNavSolid},
        };
        w3->spur = [k3](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int, std::uint32_t maske) {
            return probeSpur(k3, a, mi, ma, b, maske);
        };
        w3->boden = welt->boden;
        LaufWerte w4 = w;
        w4.ziel = {100.0F, 0.0F, 24.125F + hoehe};
        const LaufPlan p3 = planeLauf(*w3, start, w4, 0.0, 4000.0);
        float xM = -1.0e9F;
        float zM = -1.0e9F;
        for (const LaufTakt& k : p3.takte) {
            xM = std::max(xM, k.ort[0]);
            zM = std::max(zM, k.ort[2]);
        }
        const bool gut = hoehe < 18.0F ? (xM > 66.0F && nah(zM, 24.125 + hoehe, 0.01)) : (xM <= 34.0F);
        pruefe(gut, "F1 Absatz " + std::to_string(static_cast<int>(hoehe)) + ": " + (hoehe < 18.0F ? "steigt hinauf" : "bleibt davor") +
                        " (x " + std::to_string(xM) + ", z " + std::to_string(zM) + ")");
    }
}

// Offene Punkte aus §8.7, Durchsicht 2.
void review2Proben() {
    std::printf("\n== Durchsicht 2: offene Punkte ==\n");
    const std::string geh = set("SET_WALKING", "true") + setZahl("SET_WALKSPEED", "100");
    // D1 - die angezeigte Gier beim Laufen ist die des Plans je Denkbild
    // (NPC_UpdateAngles nach STEER::DeActivate, desiredYaw aus der
    // Geschwindigkeit), nicht die Richtung des Wegstuecks: ueber Eck (wie W3)
    // an jedem Denkbild gleich.
    {
        // Gerannt (BS_CINEMATIC, runSpeed 300): an der Ecke braucht die
        // Geschwindigkeit mehrere Denkbilder (mMaxForce 150), die Richtung
        // biegt, statt zu springen.
        const std::string eckKarte = kartenNpc("held", "0 0 24", "\"spawnflags\" \"32\"\n") + wegpunkt("w0", "0 0 24", "w1") +
                                     wegpunkt("w1", "600 0 24", "ziel") + zielOhneAuto("ziel", "600 600 24") +
                                     wegpunkt("w2", "-600 0 24", "w0");
        const MapData m = karte(eckKarte.c_str());
        const Scene s = szene(held(set("SET_RUNNING", "true") + set("SET_NAVGOAL", "ziel") + warte(20000.0)), m);
        const Actor* a = figur(s, "held");
        const ActorStep* w = a != nullptr ? ersterWeg(*a) : nullptr;
        double ende = 0.0;
        if (a != nullptr) {
            for (const ActorStep& st : a->steps) {
                if (st.kind == ActorStep::Kind::WalkTo && w != nullptr && st.lauf == w->lauf) { ende = st.endMs; }
            }
        }
        float grösste = -1.0F;
        double wo = -1.0;
        int takte = 0;
        if (w != nullptr && w->lauf) {
            const LaufPlan& p = *w->lauf;
            grösste = 0.0F;
            for (std::size_t i = 0; i < p.takte.size(); ++i) {
                if (p.takte[i].t < w->startMs || p.takte[i].t > ende) { continue; }
                const float ist = a->at(p.takte[i].t).angles[1];
                float d = std::fmod(ist - p.zustaende[i].gier, 360.0F);
                if (d > 180.0F) { d -= 360.0F; }
                if (d < -180.0F) { d += 360.0F; }
                ++takte;
                if (std::fabs(d) > grösste) {
                    grösste = std::fabs(d);
                    wo = p.takte[i].t;
                }
            }
        }
        pruefe(takte > 20 && grösste >= 0.0F && grösste < 0.01F,
               "D1 Gier beim Laufen = Gier des Plans je Denkbild (ueber Eck, " + std::to_string(takte) + " Denkbilder): groesste Abweichung " +
                   std::to_string(grösste) + " Grad bei " + std::to_string(wo) + " ms");
    }
    // D1b - ... und der Ablauf dreht von DERSELBEN Gier weiter: nach dem Lauf
    // ueber Eck ein SET_DYAW 0 mit dowait (TID_ANGLE_FACE). Die Szene zeigt
    // die Drehung von der Gier des Plans aus; dowait endet ein Denkbild nach
    // dem Denkbild, in dem sie 0 erreicht (NPC_UpdateAngles "exact").
    {
        const std::string eckKarte = kartenNpc("a", "0 0 24", "\"spawnflags\" \"32\"\n") + wegpunkt("w0", "0 0 24", "w1") +
                                     wegpunkt("w1", "600 0 24", "ziel") + zielOhneAuto("ziel", "600 600 24") +
                                     wegpunkt("w2", "-600 0 24", "w0");
        const MapData m = karte(eckKarte.c_str());
        AblaufWelt w;
        w.karte = &m;
        const std::string befehle = "\tset ( \"SET_RUNNING\", \"true\" );\n"
                                    "\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"ziel\" );\n\t}\n"
                                    "\tdowait ( \"geh\" );\n"
                                    "\ttask ( \"dreh\" )\n\t{\n\t\tset ( \"SET_DYAW\", 0 );\n\t}\n"
                                    "\tdowait ( \"dreh\" );\n\tprint ( \"da\" );\n";
        const Ablauf ab = simuliereAblauf(lies(inA(befehle)), "", w);
        const Scene s = buildScene(ab.flach, m);
        const Actor* a = figur(s, "a");
        const double tDreh = zeitVon(ab, "a", "set", "SET_DYAW");
        double erreicht = -1.0;
        for (int k = 1; a != nullptr && tDreh >= 0.0 && k < 600; ++k) {
            const double t = 50.0 * std::ceil(tDreh / 50.0) + 50.0 * k;
            float g = std::fmod(a->at(t).angles[1], 360.0F);
            if (g > 180.0F) { g -= 360.0F; }
            if (g < -180.0F) { g += 360.0F; }
            if (std::fabs(g) < 0.01F) {
                erreicht = t;
                break;
            }
        }
        const double tDa = zeitVon(ab, "a", "print", "da");
        pruefe(erreicht > 0.0 && nah(tDa, erreicht + 50.0, 0.5),
               "D1b nach dem Lauf ueber Eck: dowait auf SET_DYAW endet ein Denkbild nach der Szene (" + std::to_string(tDa) +
                   " / " + std::to_string(erreicht) + " + 50, SET_DYAW bei " + std::to_string(tDreh) + ")");
    }
    // F2 - Befehle wirken im Denkbild: ICARUS laeuft am Ende von NPC_Think
    // (NPC.cpp:2412-2415 MD), alle 50 ms. Ein SET_NAVGOAL zur Zeit 1234 wird
    // im Denkbild 1250 ausgefuehrt - NACH dessen Bewegung -, die Figur geht im
    // Denkbild 1300 los. Ebenso ein neues Tempo mitten im Weg: das Denkbild
    // 1250 laeuft noch mit dem alten, und ab dem Ort NACH diesem Denkbild
    // (nicht einem Ort zwischen zwei Denkbildern).
    {
        const MapData m = karte((kartenNpc("held", "0 0 24") + kartenZiel("nah", "100 0 24")).c_str());
        const Scene s = szene(held(geh + warte(1234.0) + set("SET_NAVGOAL", "nah") + warte(5000.0)), m);
        const Actor* a = figur(s, "held");
        const float x1 = a != nullptr ? a->at(1250.0).pos[0] : -1.0F;
        const float x2 = a != nullptr ? a->at(1300.0).pos[0] : -1.0F;
        pruefe(nah(x1, 0.0, 0.01) && nah(x2, 3.0, 0.01),
               "F2 SET_NAVGOAL bei 1234: im Denkbild 1250 ausgefuehrt, los im Denkbild 1300: x = 0 / 3 (" + std::to_string(x1) + " / " +
                   std::to_string(x2) + ")");
        const MapData m2 = karte((kartenNpc("held", "0 0 24") + kartenZiel("weiter", "300 0 24")).c_str());
        const Scene ohne = szene(held(geh + set("SET_NAVGOAL", "weiter") + warte(5000.0)), m2);
        const Scene mit = szene(held(geh + set("SET_NAVGOAL", "weiter") + warte(1234.0) + setZahl("SET_WALKSPEED", "50") + warte(5000.0)), m2);
        const Actor* ao = figur(ohne, "held");
        const Actor* am = figur(mit, "held");
        const float o1 = ao != nullptr ? ao->at(1250.0).pos[0] : -1.0F;
        const float m1 = am != nullptr ? am->at(1250.0).pos[0] : -2.0F;
        const float o2 = ao != nullptr ? ao->at(1300.0).pos[0] : -1.0F;
        const float m2x = am != nullptr ? am->at(1300.0).pos[0] : -1.0F;
        pruefe(nah(o1, m1, 0.001) && m2x < o2 - 0.5F,
               "F2 SET_WALKSPEED 50 bei 1234: Denkbild 1250 noch mit 100 (x " + std::to_string(m1) + " = " + std::to_string(o1) +
                   "), ab 1300 langsamer (" + std::to_string(m2x) + " < " + std::to_string(o2) + ")");
        // Ablauf und Szene bleiben sich einig (wie W8, mit Start ausserhalb des Rasters).
        const MapData m3 = karte((kartenNpc("a", "0 0 24") + kartenZiel("nah", "100 0 24")).c_str());
        AblaufWelt w;
        w.karte = &m3;
        const std::string befehle = "\tset ( \"SET_WALKING\", \"true\" );\n\tset ( \"SET_WALKSPEED\", 100 );\n\twait ( 1234 );\n"
                                    "\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"nah\" );\n\t}\n"
                                    "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n";
        const Ablauf ab = simuliereAblauf(lies(inA(befehle)), "", w);
        const Scene sa = buildScene(ab.flach, m3);
        const Actor* aa = figur(sa, "a");
        double ankunft = -1.0;
        for (int k = 1; aa != nullptr && k < 300; ++k) {
            const ActorState st = aa->at(50.0 * k);
            const float dx = 100.0F - st.pos[0];
            if (50.0 * k > 1250.0 && (dx * dx + st.pos[1] * st.pos[1] < 144.0F || (std::fabs(dx) < 17.0F && std::fabs(st.pos[1]) < 17.0F))) {
                ankunft = 50.0 * (k + 1);
                break;
            }
        }
        const double t = zeitVon(ab, "a", "print", "da");
        pruefe(ankunft > 0.0 && nah(t, ankunft, 0.5),
               "F2 ... dowait = Ankunft in der Szene, Start bei 1234 (" + std::to_string(t) + " / " + std::to_string(ankunft) + ")");
    }
    // D3 - R5 je Denkbild nach der Waffe in der Hand (NPC_utils.cpp:274-290
    // MD liest NPC->s.weapon): ein spaeteres SET_WEAPON WP_EMPLACED_GUN dreht
    // mit yawSpeed 20 (120 Grad/s: von 90 nach 375 ms bei 45), ein SET_WEAPON
    // weg davon wieder mit dem yawSpeed der .npc (330: nach 100 ms bei 57).
    // Der Ablauf wartet ebenso: 90 Grad mit 6 je Denkbild = 15 Denkbilder + 1.
    {
        const MapData m = karte(kKarte2);
        NpcMap blaster;
        parseNpcFile("jedi\n{\n\tplayerModel\tjedi\n\tweapon\tWP_BLASTER\n}\n", blaster);
        SzenenHilfe h;
        h.npcs = &blaster;
        const Scene s = szene(held(set("SET_WEAPON", "WP_EMPLACED_GUN") + set("SET_DYAW", "0")), m, &h);
        const float g1 = gier(*figur(s, "held"), 375.0);
        NpcMap kanone;
        parseNpcFile("jedi\n{\n\tplayerModel\tjedi\n\tweapon\tWP_EMPLACED_GUN\n}\n", kanone);
        SzenenHilfe h2;
        h2.npcs = &kanone;
        const Scene s2 = szene(held(set("SET_WEAPON", "WP_BLASTER") + set("SET_DYAW", "0")), m, &h2);
        const float g2 = gier(*figur(s2, "held"), 100.0);
        pruefe(gierNah(g1, 45.0F, 0.5F) && gierNah(g2, 57.0F, 0.5F),
               "D3 SET_WEAPON WP_EMPLACED_GUN: 120 Grad/s (nach 375 ms bei 45: " + std::to_string(g1) +
                   "), SET_WEAPON weg davon: 330 Grad/s (nach 100 ms bei 57: " + std::to_string(g2) + ")");
        AblaufWelt w;
        w.karte = &m;
        w.drehrateNpc = ablaufDrehrate(s);
        w.drehrateYaw = ablaufDrehrateYaw(s);
        const Ablauf ab = simuliereAblauf(
            lies("affect ( \"held\", FLUSH )\n{\n\tset ( \"SET_WEAPON\", \"WP_EMPLACED_GUN\" );\n"
                 "\ttask ( \"dreh\" )\n\t{\n\t\tset ( \"SET_DYAW\", 0 );\n\t}\n\tdowait ( \"dreh\" );\n\tprint ( \"da\" );\n}\n"),
            "", w);
        const double t = zeitVon(ab, "held", "print", "da");
        pruefe(nah(t, 800.0, 0.5), "D3 ... der Ablauf wartet mit 120 Grad/s: dowait endet bei 800 (" + std::to_string(t) + ")");
    }
    // D2 - BS_NOCLIP mitten im Rennen: PmoveSingle nimmt PM_NoclipMove und
    // kehrt ohne PM_Footsteps zurueck (bg_pmove.cpp:4860-4939 MD) - die Beine
    // behalten BOTH_RUN1, auch nach der Ankunft. Aus dem Stand bleibt es
    // BOTH_STAND1 (W10).
    {
        const MapData m = karte((kartenNpc("held", "0 0 24", "\"spawnflags\" \"32\"\n") + kartenZiel("mittel", "380 0 24")).c_str());
        const Scene s = szene(held(set("SET_RUNNING", "true") + set("SET_NAVGOAL", "mittel") + warte(500.0) +
                                   set("SET_BEHAVIOR_STATE", "BS_NOCLIP") + warte(5000.0)),
                              m);
        const Actor* a = figur(s, "held");
        const std::string vorher = a != nullptr ? a->at(450.0).animation : "";
        const std::string mitten = a != nullptr ? a->at(800.0).animation : "";
        const std::string spaeter = a != nullptr ? a->at(4000.0).animation : "";
        pruefe(vorher == "BOTH_RUN1" && mitten == "BOTH_RUN1" && spaeter == "BOTH_RUN1",
               "D2 BS_NOCLIP mitten im Rennen: die Beine behalten BOTH_RUN1 (" + vorher + " / " + mitten + " / " + spaeter + ")");
    }
}

// --- rc601 (bewegung, teil 3): Tueren und Mover zur Zeit ----------------------
//
// Auftrag: "Doors and movers at their state at that time: the engine traces
// against movers where they are at that frame and decides door edges at
// runtime (incl. door ownership TestEdge g_navigator.cpp:1290-1455 MD = B6)".
namespace teil3 {

struct EntKlotz {
    ProbeKlotz k;
    int entity = kNavWeltEntity;
};
// Wie probeSpur, aber mit der Entity des naechsten Treffers und Klotzen, die
// je Entity versetzt oder abgeschaltet sein koennen.
NavSpur spurMitEnts(const std::vector<EntKlotz>& welt, const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b,
                    int ignoriere, std::uint32_t maske, const std::function<bool(int, NavVec&)>& stellung) {
    NavSpur r;
    r.endpos = b;
    for (const EntKlotz& ek : welt) {
        if (ek.entity >= 0 && ek.entity == ignoriere) { continue; }
        ProbeKlotz k = ek.k;
        if (ek.entity >= 0) {
            NavVec o{0.0F, 0.0F, 0.0F};
            if (!stellung(ek.entity, o)) { continue; }
            for (std::size_t i = 0; i < 3; ++i) {
                k.min[i] += o[i];
                k.max[i] += o[i];
            }
        }
        const NavSpur s = probeSpur({k}, a, mi, ma, b, maske);
        if (s.allsolid) { r.allsolid = true; }
        if (s.startsolid) {
            if (!r.startsolid) { r.entity = ek.entity; }
            r.startsolid = true;
        }
        if (s.fraction < r.fraction) {
            r.fraction = s.fraction;
            r.endpos = s.endpos;
            r.normal = s.normal;
            r.contents = s.contents;
            r.entity = ek.entity;
        }
    }
    return r;
}

// Boden, Wand quer bei x 300..310 mit einer Luecke y -80..80, darin Tueren.
std::vector<EntKlotz> tuerWelt(const std::vector<std::pair<int, std::pair<float, float>>>& fluegel) {
    std::vector<EntKlotz> w;
    w.push_back({{{-3000, -3000, -16}, {3000, 3000, 0}, kNavSolid}, kNavWeltEntity});
    w.push_back({{{300, -3000, 0}, {310, -80, 400}, kNavSolid}, kNavWeltEntity});
    w.push_back({{{300, 80, 0}, {310, 3000, 400}, kNavSolid}, kNavWeltEntity});
    for (const auto& [ent, y] : fluegel) {
        w.push_back({{{300, y.first, 0}, {310, y.second, 150}, kNavSolid}, ent});
    }
    return w;
}

int index(const MapData& m, const char* name) {
    for (std::size_t i = 0; i < m.entities.size(); ++i) {
        if (m.entities[i].targetname == name) { return static_cast<int>(i); }
    }
    return -1;
}
int indexKlasse(const MapData& m, const char* klasse, int n = 0) {
    for (std::size_t i = 0; i < m.entities.size(); ++i) {
        if (m.entities[i].classname == klasse && n-- == 0) { return static_cast<int>(i); }
    }
    return -1;
}

// Netz bauen: die Tueren stehen in PHASE 0 an ihrem Platz, offen 200 hoeher.
std::shared_ptr<NavNetz> netzMitTueren(const MapData& m, const std::vector<EntKlotz>& w) {
    NavBauHilfe h;
    const auto zu = [](int, NavVec&) { return true; };
    h.spur = [w, zu](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int ign, std::uint32_t mk) {
        return spurMitEnts(w, a, mi, ma, b, ign, mk, zu);
    };
    h.spurVersetzt = [w](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int ign, std::uint32_t mk,
                         const NavVersetzt& v) {
        const auto st = [&v](int e, NavVec& o) {
            for (const NavVersetztEintrag& x : v) {
                if (x.entity == e) {
                    o = x.ort;
                    return x.fest;
                }
            }
            return true;
        };
        return spurMitEnts(w, a, mi, ma, b, ign, mk, st);
    };
    h.tuerStellungen = [&m](int e, NavVec& p1, NavVec& p2) {
        if (e < 0 || m.entities[static_cast<std::size_t>(e)].classname != "func_door") { return false; }
        p1 = {0.0F, 0.0F, 0.0F};
        p2 = {0.0F, 0.0F, 200.0F};
        return true;
    };
    return baueNavNetz(m.entities, h);
}

std::string tuer(const char* modell, const char* mehr) {
    return std::string("{\n\"classname\" \"func_door\"\n\"model\" \"") + modell + "\"\n\"angle\" \"-1\"\n" + mehr + "}\n";
}
const char* const kWegpunkte =
    "{\n\"classname\" \"waypoint\"\n\"targetname\" \"w1\"\n\"origin\" \"0 0 24\"\n\"target\" \"w2\"\n}\n"
    "{\n\"classname\" \"waypoint\"\n\"targetname\" \"w2\"\n\"origin\" \"150 30 24\"\n\"target\" \"w3\"\n}\n"
    "{\n\"classname\" \"waypoint\"\n\"targetname\" \"w3\"\n\"origin\" \"460 -30 24\"\n\"target\" \"w4\"\n}\n"
    "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"w4\"\n\"origin\" \"640 0 24\"\n}\n";

}  // namespace teil3

void teil3Mover() {
    using namespace teil3;
    std::printf("\n== teil 3: Tueren und Mover zur Zeit (M1-M5) ==\n");
    // M1 - eine Tuer in einer Wand, 100 vor der Figur; sie faehrt von 1000
    // bis 1500 ms 200 hoch. Im Spiel spurt PM_SlideMove gegen die Tuer dort,
    // wo sie in diesem Bild steht: die Figur wartet davor und geht durch,
    // sobald die Tuer weit genug oben ist. Bis teil 3 stand die Tuer fuer die
    // Spuren immer an ihrem Spawn-Platz - die Figur blieb fuer immer davor.
    {
        const std::vector<EntKlotz> w = tuerWelt({{1, {-80.0F, 80.0F}}});
        const auto hoehe = [](double t) {
            return static_cast<float>(t <= 1000.0 ? 0.0 : t >= 1500.0 ? 200.0 : 200.0 * (t - 1000.0) / 500.0);
        };
        auto welt = std::make_shared<NavWelt>();
        welt->spur = [w](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int ign, std::uint32_t mk) {
            return spurMitEnts(w, a, mi, ma, b, ign, mk, [](int, NavVec&) { return true; });
        };
        welt->spurZeit = [w, hoehe](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int ign,
                                    std::uint32_t mk, double t) {
            return spurMitEnts(w, a, mi, ma, b, ign, mk, [&](int, NavVec& o) {
                o = {0.0F, 0.0F, hoehe(t)};
                return true;
            });
        };
        welt->boden = [](float, float, float zOben, float zUnten, float& z) {
            if (zOben < 0.0F || zUnten > 0.0F) { return false; }
            z = 0.0F;
            return true;
        };
        auto plan = std::make_shared<NavMoverPlan>();
        NavMoverPlan::Mover mv;
        mv.entity = 1;
        mv.radius = 120.0F;
        mv.kastenDa = true;
        mv.kastenMin = {300.0F, -80.0F, 0.0F};
        mv.kastenMax = {310.0F, 80.0F, 150.0F};
        for (int f = 0; f <= 40; ++f) {
            NavMoverPlan::Stand s;
            s.ort = {0.0F, 0.0F, hoehe(f * 50.0)};
            mv.takte.push_back(s);
        }
        plan->mover.push_back(mv);
        plan->fertig(4);
        welt->mover = plan;
        LaufZustand start;
        start.ort = {0.0F, 0.0F, 24.125F};
        LaufWerte lw;
        lw.zielGesetzt = true;
        lw.ziel = {380.0F, 0.0F, 24.125F};
        lw.maxTempo = 300.0F;
        lw.gehTempo = 90.0F;
        const LaufPlan p = planeLauf(*welt, start, lw, 0.0, 8000.0);
        float xVor = -1.0e9F;
        for (const LaufTakt& k : p.takte) {
            if (k.t < 1000.0) { xVor = std::max(xVor, k.ort[0]); }
        }
        pruefe(xVor <= 300.0F - 16.0F + 0.2F, "M1 vor 1000 ms steht die Tuer: die Figur bleibt davor (x " + std::to_string(xVor) + ")");
        pruefe(p.ankunftMs > 1000.0 && p.ankunftMs < 4000.0,
               "M1 die Tuer faehrt hoch: die Figur geht durch und kommt an (" + std::to_string(p.ankunftMs) + " ms)");
    }
    // M2 - der Besitzer einer Tuerkante wie TestEdge (g_navigator.cpp:1406-1444
    // MD): G_Find(target) liefert das ERSTE Entity mit target == targetname
    // (hier ein target_relay); ist es kein trigger_multiple/_once, sucht die
    // Engine target2 AB DORT. Der inaktive trigger_multiple dahinter wird nie
    // Besitzer - die Tuer selbst ist es, und die oeffnet (kein Flag).
    {
        const std::string text = std::string("{\n\"classname\" \"worldspawn\"\n}\n") +
                                 "{\n\"classname\" \"target_relay\"\n\"target\" \"tuer1\"\n}\n"
                                 "{\n\"classname\" \"trigger_multiple\"\n\"target\" \"tuer1\"\n\"spawnflags\" \"128\"\n}\n" +
                                 tuer("*1", "\"targetname\" \"tuer1\"\n") + kWegpunkte;
        const MapData m = karte(text.c_str());
        const int t1 = indexKlasse(m, "func_door");
        const auto netz = netzMitTueren(m, tuerWelt({{t1, {-80.0F, 80.0F}}}));
        const int a = netz->knotenNamens("w1");
        const int b = netz->knotenNamens("w4");
        const int e = netz->kanteZwischen(netz->knotenNamens("w2"), netz->knotenNamens("w3"));
        const bool tuerKante = e > 0 && netz->kanten[static_cast<std::size_t>(e)].hat(NavKante::TuerSperrt) &&
                               netz->kanten[static_cast<std::size_t>(e)].besitzer == t1;
        pruefe(tuerKante && navAStar(*netz, a, b),
               std::string("M2 Besitzer nach G_Find-Reihenfolge: die Tuer selbst, der Weg durch die Tuer gilt") +
                   (tuerKante ? "" : " (keine Tuerkante mit der Tuer als Besitzer)"));
    }
    // M3 - eine Tuer aus zwei Fluegeln (team "t1"): TestEdge oeffnet die ganze
    // Kette (g_navigator.cpp:1313-1343 MD). Bis teil 3 wurde nur der getroffene
    // Fluegel uebergangen - der andere hielt die Spur auf, die Kante fiel weg.
    {
        const std::string text = std::string("{\n\"classname\" \"worldspawn\"\n}\n") + tuer("*1", "\"team\" \"t1\"\n") +
                                 tuer("*2", "\"team\" \"t1\"\n") + kWegpunkte;
        const MapData m = karte(text.c_str());
        const int f1 = indexKlasse(m, "func_door", 0);
        const int f2 = indexKlasse(m, "func_door", 1);
        const auto netz = netzMitTueren(m, tuerWelt({{f1, {-80.0F, 0.0F}}, {f2, {0.0F, 80.0F}}}));
        const int e = netz->kanteZwischen(netz->knotenNamens("w2"), netz->knotenNamens("w3"));
        const bool tuerKante = e > 0 && netz->kanten[static_cast<std::size_t>(e)].hat(NavKante::TuerSperrt) &&
                               netz->kanten[static_cast<std::size_t>(e)].entity == f1;
        pruefe(tuerKante && navAStar(*netz, netz->knotenNamens("w1"), netz->knotenNamens("w4")),
               "M3 zwei Fluegel im Team: die Kette wird geoeffnet, die Kante gilt (Entity = Meister)");
    }
    // M4 - is_valid zur Laufzeit: eine verriegelte Tuer (MOVER_LOCKED, die Tuer
    // selbst ist Besitzer) sperrt, solange sie ZU ist. Ist sie offen (POS2),
    // gilt die Kante ("if (Closed) ... return true", g_navigator.cpp:596-628
    // MD) - die Figur geht ueber das Netz hindurch. Mit demselben Schluessel
    // fuer den Zwischenspeicher: der Plan "steht" darf nicht wiederkommen.
    const std::string text4 = std::string("{\n\"classname\" \"worldspawn\"\n}\n") +
                              tuer("*1", "\"targetname\" \"tuer1\"\n\"spawnflags\" \"16\"\n") + kWegpunkte +
                              tuer("*2", "\"targetname\" \"weit\"\n");
    const MapData m4 = karte(text4.c_str());
    const int t4 = indexKlasse(m4, "func_door", 0);
    const int weit4 = indexKlasse(m4, "func_door", 1);
    std::vector<EntKlotz> w4 = tuerWelt({{t4, {-80.0F, 80.0F}}});
    w4.push_back({{{5000, 5000, 0}, {5010, 5100, 150}, kNavSolid}, weit4});
    const auto netz4 = netzMitTueren(m4, w4);
    const auto weltMit = [&](std::shared_ptr<const NavMoverPlan> plan, std::uint64_t kennung) {
        auto welt = std::make_shared<NavWelt>();
        welt->netz = netz4;
        welt->spur = [w4](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int ign, std::uint32_t mk) {
            return spurMitEnts(w4, a, mi, ma, b, ign, mk, [](int, NavVec&) { return true; });
        };
        if (plan) {
            welt->spurZeit = [w4, plan](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int ign,
                                        std::uint32_t mk, double t) {
                return spurMitEnts(w4, a, mi, ma, b, ign, mk, [&](int e, NavVec& o) {
                    if (const NavMoverPlan::Stand* s = plan->standVon(e, t)) { o = s->ort; }
                    return true;
                });
            };
        }
        welt->boden = [](float, float, float zOben, float zUnten, float& z) {
            if (zOben < 0.0F || zUnten > 0.0F) { return false; }
            z = 0.0F;
            return true;
        };
        welt->mover = plan;
        welt->kennung = kennung;
        return welt;
    };
    const auto offen = [&](bool weitBewegt) {
        auto plan = std::make_shared<NavMoverPlan>();
        NavMoverPlan::Mover mv;
        mv.entity = t4;
        mv.radius = 120.0F;
        mv.kastenDa = true;
        mv.kastenMin = {300.0F, -80.0F, 0.0F};
        mv.kastenMax = {310.0F, 80.0F, 150.0F};
        mv.anfang.verriegelt = true;
        NavMoverPlan::Stand s;
        s.ort = {0.0F, 0.0F, 200.0F};
        s.zustand = 1;   // MOVER_POS2
        mv.takte.push_back(s);
        plan->mover.push_back(mv);
        if (weitBewegt) {
            NavMoverPlan::Mover w;
            w.entity = weit4;
            w.radius = 120.0F;
            w.kastenDa = true;
            w.kastenMin = {5000.0F, 5000.0F, 0.0F};
            w.kastenMax = {5010.0F, 5100.0F, 150.0F};
            for (int f = 0; f < 40; ++f) {
                NavMoverPlan::Stand x;
                x.ort = {0.0F, 0.0F, static_cast<float>(f)};
                x.zustand = f == 0 ? 0 : 2;
                w.takte.push_back(x);
            }
            plan->mover.push_back(w);
        }
        plan->fertig(m4.entities.size());
        return std::shared_ptr<const NavMoverPlan>(plan);
    };
    LaufZustand start4;
    start4.ort = {0.0F, 0.0F, 24.125F};
    LaufWerte lw4;
    lw4.zielGesetzt = true;
    lw4.ziel = {640.0F, 0.0F, 24.125F};
    lw4.maxTempo = 300.0F;
    lw4.gehTempo = 90.0F;
    const std::uint64_t kennung = 0x7e113ULL;
    const LaufPlan zu = planeLauf(*weltMit(nullptr, kennung), start4, lw4, 0.0, 20000.0);
    const LaufPlan auf = planeLauf(*weltMit(offen(false), kennung), start4, lw4, 0.0, 20000.0);
    pruefe(zu.nie && zu.ankunftMs < 0.0, "M4 verriegelte Tuer zu: kein Weg, die Figur steht (wie STEER::Stop)");
    pruefe(auf.ankunftMs > 0.0, "M4 dieselbe Tuer offen (POS2): die Kante gilt, die Figur kommt an (" +
                                    std::to_string(auf.ankunftMs) + " ms) - auch mit demselben Schluessel des Zwischenspeichers");
    // M5 - der Zwischenspeicher behaelt einen Plan, wenn sich nur ein Mover
    // aendert, den keine seiner Spuren beruehrt (weit weg) - und das Ergebnis
    // ist Bit fuer Bit das einer frischen Rechnung.
    {
        const NavPlanZaehler vor = navPlanZaehler();
        const LaufPlan warm = planeLauf(*weltMit(offen(true), kennung), start4, lw4, 0.0, 20000.0);
        const NavPlanZaehler nach = navPlanZaehler();
        const LaufPlan kalt = planeLauf(*weltMit(offen(true), 0U), start4, lw4, 0.0, 20000.0);
        bool gleich = warm.takte.size() == kalt.takte.size() && warm.ankunftMs == kalt.ankunftMs;
        for (std::size_t i = 0; gleich && i < warm.takte.size(); ++i) {
            gleich = warm.takte[i].ort == kalt.takte[i].ort && warm.takte[i].tempo == kalt.takte[i].tempo;
        }
        pruefe(nach.warm == vor.warm + 1 && gleich,
               "M5 ein weit entfernter Mover bewegt sich: der Plan kommt aus dem Zwischenspeicher und ist gleich der frischen Rechnung");
    }
}

// --- rc601 (bewegung, teil 3): Fallen im Plan (F2a-F2d) ------------------------
//
// Auftrag: "walking off a ledge falls under gravity like PM_GroundTrace/
// PM_AirMove/PM_StepSlideMove; one source of truth for the height so the plan,
// the drawn height (gravity code) and the flow agree; PM_CorrectAllSolid
// ported instead of the one-step lift".
void teil3Fallen() {
    std::printf("\n== teil 3: Fallen im Plan (F2a-F2d) ==\n");
    // Ein Absatz: bis x 100 Boden auf 0, dahinter 200 tiefer.
    const std::vector<ProbeKlotz> absatz = {
        {{-2000, -2000, -16}, {100, 2000, 0}, kNavSolid},
        {{100, -2000, -216}, {2000, 2000, -200}, kNavSolid},
    };
    auto welt = std::make_shared<NavWelt>();
    welt->spur = [absatz](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int, std::uint32_t maske) {
        return probeSpur(absatz, a, mi, ma, b, maske);
    };
    welt->boden = [](float x, float, float zOben, float zUnten, float& z) {
        const float oben = x < 100.0F ? 0.0F : -200.0F;
        if (oben > zOben || oben < zUnten) { return false; }
        z = oben;
        return true;
    };
    LaufWerte lw;
    lw.zielGesetzt = true;
    lw.ziel = {300.0F, 0.0F, 24.125F};   // in der Luft ueber dem unteren Boden
    lw.maxTempo = 300.0F;
    lw.gehTempo = 90.0F;
    // F2a - ueber die Kante: PM_GroundTrace findet keinen Boden, PM_AirMove mit
    // der Schwerkraft (800), Landung unten, Ankunft. Bis teil 3 hielt der Plan
    // die Hoehe (hoechstens eine Stufe tiefer) und kam nie an.
    {
        LaufZustand start;
        start.ort = {0.0F, 0.0F, 24.125F};
        const LaufPlan p = planeLauf(*welt, start, lw, 0.0, 10000.0);
        bool faellt = false;
        float zEnde = 0.0F;
        float xEnde = 0.0F;
        for (const LaufTakt& k : p.takte) {
            if (k.ort[0] > 110.0F && k.ort[2] < 20.0F && k.ort[2] > -170.0F) { faellt = true; }
            zEnde = k.ort[2];
            xEnde = k.ort[0];
        }
        const bool gelandet = !p.zustaende.empty() && p.zustaende.back().amBoden;
        pruefe(faellt && gelandet && nah(zEnde, -175.875, 0.3) && xEnde > 150.0F,
               "F2a ueber die Kante: faellt und landet 200 tiefer (PM_GroundTrace am Boden; z am Ende " + std::to_string(zEnde) +
                   ", x " + std::to_string(xEnde) + ")");
    }
    // F2b - der Kasten steckt im Boden: PM_CorrectAllSolid nimmt nur den
    // Boden weg ("FIXME: jitter around"), PM_SlideMove meldet allsolid - die
    // Figur bewegt sich nicht. Bis teil 3 hob der Plan sie eine Stufe an.
    {
        LaufZustand start;
        start.ort = {0.0F, 0.0F, 10.0F};
        LaufWerte w2 = lw;
        w2.ziel = {60.0F, 0.0F, 24.125F};
        const LaufPlan p = planeLauf(*welt, start, w2, 0.0, 3000.0);
        float xMax = 0.0F;
        for (const LaufTakt& k : p.takte) { xMax = std::max(xMax, std::fabs(k.ort[0])); }
        pruefe(p.ankunftMs < 0.0 && xMax < 0.01F,
               "F2b steckt im Boden: PM_CorrectAllSolid, kein Anheben - sie bleibt (x bis " + std::to_string(xMax) + ")");
    }
    // F2c - Vorlauf ab dem Spawn: G_CheckInSolid (g_utils.cpp:1641-1674) hebt
    // den Ursprung auf den Boden (+24), danach geht sie los.
    {
        LaufZustand start;
        start.ort = {0.0F, 0.0F, 1.0F};
        LaufWerte w3 = lw;
        w3.ziel = {60.0F, 0.0F, 24.125F};
        w3.zielAbMs = 0.0;
        w3.spawnVorlauf = true;
        const LaufPlan p = planeLauf(*welt, start, w3, kNavKartenSpawnMs, 6000.0);
        const float z0 = p.takte.empty() ? -1.0F : p.takte.front().ort[2];
        pruefe(nah(z0, 24.125, 0.01) && p.ankunftMs > 0.0,
               "F2c Spawn 23 zu tief: G_CheckInSolid hebt auf 24.125 (" + std::to_string(z0) + "), dann Ankunft (" +
                   std::to_string(p.ankunftMs) + " ms)");
    }
    // F2d - eine Quelle fuer die Hoehe: in der Szene zeichnet die Schwerkraft
    // waehrend des Weges die Hoehe des Plans (vorher rechnete sie selbst mit
    // einem Strahl und hielt die Figur ueber der Kante oben).
    {
        const MapData m = karte((kartenNpc("held", "0 0 24") + kartenZiel("unten", "300 0 24")).c_str());
        SzenenHilfe h;
        h.nav = welt;
        Scene s = szene(held(set("SET_NAVGOAL", "unten") + warte(9000.0)), m, &h);
        SchwerkraftHilfe sh;
        sh.strahl = ::welt({{-5000.0F, 100.0F, -5000.0F, 5000.0F, 0.0F}, {100.0F, 5000.0F, -5000.0F, 5000.0F, -200.0F}}, {});
        sh.endeMs = 10000.0;
        schwerkraftEinrechnen(s, sh);
        const Actor& a = s.actors.front();
        double maxAbw = 0.0;
        int verglichen = 0;
        bool unten = false;
        for (const ActorStep& st : a.steps) {
            if (st.kind != ActorStep::Kind::WalkTo || !st.lauf) { continue; }
            for (double t = st.startMs + 50.0; t <= st.endMs && t < sh.endeMs - 100.0; t += 50.0) {
                const double d = std::fabs(static_cast<double>(a.at(t).pos[2]) - static_cast<double>(ortBei(*st.lauf, t)[2]));
                maxAbw = std::max(maxAbw, d);
                ++verglichen;
                if (a.at(t).pos[2] < -170.0F) { unten = true; }
            }
        }
        pruefe(verglichen > 10 && maxAbw < 0.01 && unten,
               "F2d gezeichnete Hoehe = Hoehe des Plans waehrend des Weges (" + std::to_string(verglichen) +
                   " Takte, Abweichung bis " + std::to_string(maxAbw) + ")");
    }
}

// --- rc601 (bewegung, teil 3): andere Figuren als Hindernisse (K1-K3) ----------
void teil3Koerper() {
    std::printf("\n== teil 3: andere Figuren im selben Takt (K1-K3) ==\n");
    const std::vector<ProbeKlotz> boden = {{{-3000, -3000, -16}, {3000, 3000, 0}, kNavSolid}};
    auto welt = std::make_shared<NavWelt>();
    welt->spur = [boden](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int, std::uint32_t maske) {
        return probeSpur(boden, a, mi, ma, b, maske);
    };
    welt->boden = [](float, float, float zOben, float zUnten, float& z) {
        if (zOben < 0.0F || zUnten > 0.0F) { return false; }
        z = 0.0F;
        return true;
    };
    const auto abschnitt = [&](int figur, NavVec von, NavVec nach) {
        NavAbschnitt a;
        a.figur = figur;
        a.abMs = 0.0;
        a.grenzeMs = 20000.0;
        a.start.ort = von;
        a.start.amBoden = true;
        a.werte.zielGesetzt = true;
        a.werte.ziel = nach;
        a.werte.maxTempo = 150.0F;
        a.werte.gehTempo = 90.0F;
        a.sprung = true;
        a.allein = std::make_shared<const LaufPlan>(planeLauf(*welt, a.start, a.werte, a.abMs, a.grenzeMs));
        return a;
    };
    std::vector<NavFigurKoerper> figuren(2);
    figuren[1].reihe = 1;
    // Ueberlappen sich die Kaesten (32 breit) zweier Plaene zu einer Zeit?
    const auto ueberlapp = [](const LaufPlan& p, const LaufPlan& q) {
        float tiefste = 0.0F;
        for (std::size_t i = 0; i < p.takte.size(); ++i) {
            const NavVec a = p.takte[i].ort;
            const NavVec b = ortBei(q, p.takte[i].t);
            const float ox = 32.0F - std::fabs(a[0] - b[0]);
            const float oy = 32.0F - std::fabs(a[1] - b[1]);
            if (ox > 0.0F && oy > 0.0F) { tiefste = std::max(tiefste, std::min(ox, oy)); }
        }
        return tiefste;
    };
    // K1 - zwei Figuren gehen aufeinander zu (leicht versetzt). Im Spiel sieht
    // jede die andere (CONTENTS_BODY): AvoidCollisions lenkt, PM_SlideMove
    // schiebt am Kasten entlang - sie gehen nie ineinander. Bis teil 3 liefen
    // sie durcheinander hindurch.
    {
        std::vector<NavAbschnitt> abs = {abschnitt(0, {0.0F, 0.0F, 24.125F}, {300.0F, 0.0F, 24.125F}),
                                         abschnitt(1, {300.0F, 8.0F, 24.125F}, {0.0F, 8.0F, 24.125F})};
        const float vorher = ueberlapp(*abs[0].allein, *abs[1].allein);
        const NavKoerperErgebnis e = navKoerperLauf(*welt, figuren, abs);
        const float nachher = ueberlapp(*e.plaene[0], *e.plaene[1]);
        std::printf("  info  K1 ohne die anderen ueberlappen die Kaesten bis %.1f, im gemeinsamen Takt %.3f (%d Plaene geaendert)\n",
                    static_cast<double>(vorher), static_cast<double>(nachher), e.geaendert);
        pruefe(nachher < 0.2F && e.geaendert > 0,
               "K1 aufeinander zu: im gemeinsamen Takt nie ineinander (Ueberlappung " + std::to_string(nachher) + ")");
    }
    // K2 - weit auseinander: kein Kasten beruehrt eine Spur des anderen - die
    // Plaene bleiben Bit fuer Bit die ohne die anderen (derselbe Zeiger).
    {
        std::vector<NavAbschnitt> abs = {abschnitt(0, {0.0F, 0.0F, 24.125F}, {300.0F, 0.0F, 24.125F}),
                                         abschnitt(1, {0.0F, 1500.0F, 24.125F}, {300.0F, 1500.0F, 24.125F})};
        const NavKoerperErgebnis e = navKoerperLauf(*welt, figuren, abs);
        pruefe(e.geaendert == 0 && e.plaene[0] == abs[0].allein && e.plaene[1] == abs[1].allein,
               "K2 weit auseinander: die Plaene ohne die anderen gelten unveraendert");
    }
    // K3 - eine steht im Weg (ohne Plan, nur ihr Ort): die andere kommt nicht
    // hindurch, sondern um sie herum oder bleibt davor.
    {
        std::vector<NavFigurKoerper> fg = figuren;
        fg[1].orte.push_back({-1000.0, {150.0F, 0.0F, 24.125F}});
        std::vector<NavAbschnitt> abs = {abschnitt(0, {0.0F, 0.0F, 24.125F}, {300.0F, 0.0F, 24.125F})};
        const NavKoerperErgebnis e = navKoerperLauf(*welt, fg, abs);
        float tiefste = 0.0F;
        for (const LaufTakt& k : e.plaene[0]->takte) {
            const float ox = 32.0F - std::fabs(k.ort[0] - 150.0F);
            const float oy = 32.0F - std::fabs(k.ort[1]);
            if (ox > 0.0F && oy > 0.0F) { tiefste = std::max(tiefste, std::min(ox, oy)); }
        }
        pruefe(tiefste < 0.2F, "K3 eine steht im Weg: nicht durch sie hindurch (Ueberlappung " + std::to_string(tiefste) + ")");
    }
    // K4 - Ablauf und Szene: zwei NPCs gehen per Skript aufeinander zu. Der
    // Ablauf rechnet mit dem gemeinsamen Takt (simuliereAblaufMitKoerpern),
    // die Szene nimmt dieselben Plaene - dowait endet, wenn die Figur der Szene
    // ankommt, und die beiden gehen nicht ineinander.
    {
        const MapData m = karte(
            "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"a\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"0 0 24.125\"\n}\n"
            "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"b\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"300 8 24.125\"\n}\n"
            "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"za\"\n\"origin\" \"300 0 24\"\n}\n"
            "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"zb\"\n\"origin\" \"0 8 24\"\n}\n");
        AblaufWelt aw;
        aw.karte = &m;
        aw.nav = welt;
        const std::string text = "affect ( \"a\", FLUSH )\n{\n\ttask ( \"geh\" )\n\t{\n\t\tset ( \"SET_NAVGOAL\", \"za\" );\n\t}\n"
                                 "\tdowait ( \"geh\" );\n\tprint ( \"da\" );\n}\n"
                                 "affect ( \"b\", FLUSH )\n{\n\tset ( \"SET_NAVGOAL\", \"zb\" );\n\twait ( 9000 );\n}\n";
        int durchgaenge = 0;
        const Ablauf a = simuliereAblaufMitKoerpern(lies(text), "", aw, &durchgaenge);
        SzenenHilfe h;
        h.nav = welt;
        h.koerperPlaene = aw.koerperPlaene;
        const Scene s = buildScene(a.flach, m, &h);
        const Actor* fa = figur(s, "a");
        const Actor* fb = figur(s, "b");
        float tiefste = 99.0F;
        if (fa != nullptr && fb != nullptr) {
            tiefste = 0.0F;
            for (double t = 0.0; t < 9000.0; t += 50.0) {
                const ActorState x = fa->at(t);
                const ActorState y = fb->at(t);
                const float ox = 32.0F - std::fabs(x.pos[0] - y.pos[0]);
                const float oy = 32.0F - std::fabs(x.pos[1] - y.pos[1]);
                if (ox > 0.0F && oy > 0.0F) { tiefste = std::max(tiefste, std::min(ox, oy)); }
            }
        }
        const double da = zeitVon(a, "a", "print", "da");
        const double an = fa != nullptr ? ankunftVon(*fa) : -2.0;
        pruefe(durchgaenge > 1 && tiefste < 0.2F && da > 0.0 && nah(da, an, 0.5),
               "K4 Ablauf + Szene im gemeinsamen Takt: nicht ineinander (" + std::to_string(tiefste) + "), dowait " +
                   std::to_string(da) + " = Ankunft in der Szene " + std::to_string(an) + " (" + std::to_string(durchgaenge) +
                   " Rechnungen)");
    }
}

// --- rc603 fix603: Tuer-Lauf - ein Ort aus der Zukunft als Hindernis --------
//
// Anwender: "In unserer Mission von Mustafar sieht das an manchen Stellen, wo
// Anakin durch die Tuer laeuft, nicht richtig aus. Statt durch die Tuer laeuft
// er nur nach links und rechts." (md_am_sith, ani_walk.ibi: ani2 geht nach
// ani2_nav1, am Ende "player" SET_COPY_ORIGIN "ani2".) Der echte Spieler hat
// keinen Spawner und keinen bekannten Ort; erst Q3_SetCopyOrigin
// (Q3_Interface.cpp:1413 -> Q3_SetOrigin :1309, G_SetOrigin + linkentity zur
// Zeit des Befehls) stellt ihn hin. behaved stellte den Kasten einer Figur ohne
// Plan an ihren Ort vom ENDE des Ablaufs - und zwar ab Beginn: der Spieler
// stand von Anfang an dort, wo ani2 am Ende ankommt, und ani2 pendelte davor.
void tuerLaufKoerper() {
    std::printf("\n== fix603: Tuer-Lauf - Orte von Figuren ohne Plan zur Zeit (TL1) ==\n");
    const std::vector<ProbeKlotz> boden = {{{-3000, -3000, -16}, {3000, 3000, 0}, kNavSolid}};
    auto welt = std::make_shared<NavWelt>();
    welt->spur = [boden](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int, std::uint32_t maske) {
        return probeSpur(boden, a, mi, ma, b, maske);
    };
    welt->boden = [](float, float, float zOben, float zUnten, float& z) {
        if (zOben < 0.0F || zUnten > 0.0F) { return false; }
        z = 0.0F;
        return true;
    };
    const MapData m = karte(
        "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"a\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"0 0 24.125\"\n}\n"
        "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"za\"\n\"origin\" \"300 0 24\"\n}\n");
    AblaufWelt aw;
    aw.karte = &m;
    aw.nav = welt;
    const std::string text = "affect ( \"a\", FLUSH )\n{\n\tset ( \"SET_WALKING\", \"true\" );\n"
                             "\tset ( \"SET_NAVGOAL\", \"za\" );\n\twait ( 15000 );\n}\n"
                             "wait ( 12000 );\n"
                             "affect ( \"player\", FLUSH )\n{\n\tset ( \"SET_COPY_ORIGIN\", \"a\" );\n}\n";
    int durchgaenge = 0;
    const Ablauf a = simuliereAblaufMitKoerpern(lies(text), "", aw, &durchgaenge);
    // Ab wann steht der Kasten des Spielers?
    double frueh = 1.0e300;
    for (std::size_t i = 0; i < a.laufFiguren.size() && i < a.laufFigurNamen.size(); ++i) {
        if (a.laufFigurNamen[i] != "player") { continue; }
        for (const auto& [ms, ort] : a.laufFiguren[i].orte) { frueh = std::min(frueh, ms); }
    }
    SzenenHilfe h;
    h.nav = welt;
    h.koerperPlaene = aw.koerperPlaene;
    const Scene s = buildScene(a.flach, m, &h);
    const Actor* fa = figur(s, "a");
    const double an = fa != nullptr ? ankunftVon(*fa) : -2.0;
    const float rest = fa != nullptr ? std::hypot(300.0F - fa->at(11000.0).pos[0], fa->at(11000.0).pos[1]) : 999.0F;
    // Bezug: derselbe Weg ohne den Spieler.
    AblaufWelt aw0;
    aw0.karte = &m;
    aw0.nav = welt;
    const Ablauf a0 = simuliereAblaufMitKoerpern(lies(text.substr(0, text.find("wait ( 12000 )"))), "", aw0, nullptr);
    SzenenHilfe h0;
    h0.nav = welt;
    h0.koerperPlaene = aw0.koerperPlaene;
    const Scene s0 = buildScene(a0.flach, m, &h0);
    const Actor* fa0 = figur(s0, "a");
    const double an0 = fa0 != nullptr ? ankunftVon(*fa0) : -3.0;
    std::printf("  info  TL1 Spieler-Kasten ab %.0f ms, a angekommen %.0f (ohne Spieler %.0f), Rest bei 11 s %.1f (%d Rechnungen)\n",
                frueh, an, an0, static_cast<double>(rest), durchgaenge);
    pruefe(frueh >= 11999.0, "TL1 der Spieler (ohne Ort) ist erst ab SET_COPY_ORIGIN bei 12000 ms ein Koerper (ab " +
                                 std::to_string(frueh) + ")");
    pruefe(an > 0.0 && an < 11000.0 && rest < 24.0F && nah(an, an0, 0.5),
           "TL1 a kommt an wie ohne den Spieler - kein Kasten aus der Zukunft im Weg (Ankunft " + std::to_string(an) + " / " +
               std::to_string(an0) + ", Rest " +
               std::to_string(rest) + ")");
}

// --- rc603 fix603: pml.msec im gemeinsamen Takt nach einer Pause (KP1-KP2) ---
//
// md_gd_jedi, cin4_jedi.ibi: dooku5 (beim Laden gespawnt) steht bis zu seinem
// SET_NAVGOAL bei 6700 ms still, yoda2 steht dicht daneben. Im ersten Denkbild
// des Wegs (6750) sprang er ~450 Einheiten, das erste Pmove spurte ~1020 weit
// (150 * 6,8 s). Im Spiel denkt ein NPC jedes Bild (NPC_Think: nextthink =
// level.time + FRAMETIME/2, NPC.cpp:2213 MD; ucmd.serverTime = level.time - 50,
// NPC.cpp:2147), pml.msec = serverTime - commandTime ist also 50 und nie mehr
// als 200 (bg_pmove.cpp:33781-33789 MD, g_active.cpp:10094-10102). Der Plan
// ohne die anderen ueberspringt das Stillstehen (eine Luecke in den Takten);
// wich die Figur danach ab, nahm der gemeinsame Takt die ganze Luecke als
// Bildzeit (t - Zeit des letzten Takts).
void koerperTaktNachPause() {
    std::printf("\n== fix603: gemeinsamer Takt - pml.msec nach einer Pause im Plan (KP1-KP2) ==\n");
    const std::vector<ProbeKlotz> boden = {{{-3000, -3000, -16}, {3000, 3000, 0}, kNavSolid}};
    auto welt = std::make_shared<NavWelt>();
    welt->spur = [boden](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int, std::uint32_t maske) {
        return probeSpur(boden, a, mi, ma, b, maske);
    };
    welt->boden = [](float, float, float zOben, float zUnten, float& z) {
        if (zOben < 0.0F || zUnten > 0.0F) { return false; }
        z = 0.0F;
        return true;
    };
    // Beim Laden der Karte gespawnt (Vorlauf ab NPC_Begin), Ziel erst ab 6700,
    // 100 entfernt: STEER::SafeToGoTo gibt unter 110 sofort frei
    // (g_navigator.cpp:4337 MD) - schon das erste Laufdenkbild bewegt sie.
    const auto abschnitt = [&](NavVec von) {
        NavAbschnitt a;
        a.figur = 0;
        a.abMs = kNavKartenSpawnMs;
        a.grenzeMs = 20000.0;
        a.start.ort = von;
        a.start.gesetztMs = kNavKartenSpawnMs;
        a.start.gesetztSpawn = true;
        a.werte.zielGesetzt = true;
        a.werte.ziel = {100.0F, 0.0F, 24.125F};
        a.werte.maxTempo = 150.0F;
        a.werte.gehTempo = 90.0F;
        a.werte.zielAbMs = 6700.0;
        a.werte.spawnVorlauf = true;
        a.sprung = true;
        a.allein = std::make_shared<const LaufPlan>(planeLauf(*welt, a.start, a.werte, a.abMs, a.grenzeMs));
        return a;
    };
    // Der weiteste Schritt eines Denkbilds (waagrecht) nach dem Befehl.
    const auto weitester = [](const LaufPlan& p, double ab, double& wann) {
        float best = 0.0F;
        NavVec vorher = p.anfang.ort;
        for (const LaufTakt& k : p.takte) {
            const float d = std::hypot(k.ort[0] - vorher[0], k.ort[1] - vorher[1]);
            if (k.t > ab && d > best) {
                best = d;
                wann = k.t;
            }
            vorher = k.ort;
        }
        return best;
    };
    // KP1 - wie dooku5: die zweite Figur steht so, dass erst die Spuren des
    // ersten Laufdenkbilds (MoveTrace nach vorn, 150 weit) ihren Kasten
    // beruehren - dort weicht der Plan ab. Mehr als 150 * 0,05 = 7,5 kann ein
    // Denkbild nicht gehen.
    {
        std::vector<NavFigurKoerper> fg(2);
        fg[1].reihe = 1;
        fg[1].orte.push_back({-1.0e299, {60.0F, 33.0F, 24.125F}});
        std::vector<NavAbschnitt> abs = {abschnitt({0.0F, 0.0F, 24.125F})};
        const NavKoerperErgebnis e = navKoerperLauf(*welt, fg, abs);
        const LaufPlan& p = *e.plaene[0];
        double wann = -1.0;
        const float weit = weitester(p, 6700.0, wann);
        double wann0 = -1.0;
        const float weit0 = weitester(*abs[0].allein, 6700.0, wann0);
        const LaufTakt* erster = nullptr;
        for (const LaufTakt& k : p.takte) {
            if (erster == nullptr && k.t > 6700.5) { erster = &k; }
        }
        std::printf("  info  KP1 %d Plaene geaendert; weitester Schritt %.2f bei %.0f ms (ohne die andere %.2f bei %.0f), "
                    "erstes Laufdenkbild %.0f bei %.1f %.1f, angekommen %.0f\n",
                    e.geaendert, static_cast<double>(weit), wann, static_cast<double>(weit0), wann0,
                    erster != nullptr ? erster->t : -1.0, erster != nullptr ? static_cast<double>(erster->ort[0]) : 0.0,
                    erster != nullptr ? static_cast<double>(erster->ort[1]) : 0.0, p.ankunftMs);
        pruefe(e.geaendert > 0 && erster != nullptr && erster->t < 6750.5,
               "KP1 die Figur weicht im ersten Laufdenkbild (6750) vom Plan ohne die andere ab");
        pruefe(weit <= 150.0F * 0.05F + 0.01F,
               "KP1 kein Denkbild geht weiter als runSpeed * 50 ms = 7,5 (weitester Schritt " + std::to_string(weit) + " bei " +
                   std::to_string(wann) + " ms)");
        pruefe(p.ankunftMs > 6750.0 && p.ankunftMs < 6700.0 + 3000.0,
               "KP1 sie kommt an ihrem Ziel an (" + std::to_string(p.ankunftMs) + " ms)");
    }
    // KP2 - die zweite Figur steht schon beim Spawn dicht daneben: die Spuren
    // des Vorlaufs (G_CheckInSolid, Pmove von 200 ms in NPC_Begin) beruehren
    // ihren Kasten. Die Figur erscheint 40 ueber dem Boden und faellt noch beim
    // ersten NPC_Think. Der gemeinsame Takt rechnet den Vorlauf wie der Plan
    // ohne die andere: der Kasten trifft keine dieser Spuren, also Bit fuer
    // Bit dieselben Takte - der Spawn bei -200 (200 ms Fallen) und das erste
    // NPC_Think bei -50 (wieder 200 ms).
    {
        std::vector<NavFigurKoerper> fg(2);
        fg[1].reihe = 1;
        fg[1].orte.push_back({-1.0e299, {-33.0F, 0.0F, 24.125F}});
        std::vector<NavAbschnitt> abs = {abschnitt({0.0F, 0.0F, 64.0F})};
        const NavKoerperErgebnis e = navKoerperLauf(*welt, fg, abs);
        const LaufPlan& p = *e.plaene[0];
        const LaufPlan& al = *abs[0].allein;
        bool gleich = p.takte.size() >= 2 && al.takte.size() >= 2;
        for (std::size_t i = 0; gleich && i < 2; ++i) {
            gleich = p.takte[i].t == al.takte[i].t && p.takte[i].ort == al.takte[i].ort;
        }
        std::printf("  info  KP2 %d Plaene geaendert; Takte mit der anderen %.0f (z %.3f), %.0f (z %.3f); ohne %.0f (z %.3f), %.0f (z %.3f)\n",
                    e.geaendert, p.takte.empty() ? -1.0 : p.takte[0].t,
                    p.takte.empty() ? 0.0 : static_cast<double>(p.takte[0].ort[2]), p.takte.size() < 2 ? -1.0 : p.takte[1].t,
                    p.takte.size() < 2 ? 0.0 : static_cast<double>(p.takte[1].ort[2]), al.takte.empty() ? -1.0 : al.takte[0].t,
                    al.takte.empty() ? 0.0 : static_cast<double>(al.takte[0].ort[2]), al.takte.size() < 2 ? -1.0 : al.takte[1].t,
                    al.takte.size() < 2 ? 0.0 : static_cast<double>(al.takte[1].ort[2]));
        pruefe(e.geaendert > 0 && gleich,
               "KP2 Abweichung schon beim Spawn: Vorlauf (-200, 200 ms) und erstes NPC_Think (-50, 200 ms) wie ohne die andere");
        double wann = -1.0;
        const float weit = weitester(p, 6700.0, wann);
        pruefe(weit <= 150.0F * 0.05F + 0.01F,
               "KP2 kein Denkbild geht weiter als 7,5 (weitester Schritt " + std::to_string(weit) + " bei " +
                   std::to_string(wann) + " ms)");
    }
}

// --- rc601 (bewegung, teil 3): Patches halten Spuren auf (W1) ------------------
namespace teil3w {
void i32an(std::string& b, std::int32_t v) {
    char c[4];
    std::memcpy(c, &v, 4);
    b.append(c, 4);
}
void f32an(std::string& b, float v) {
    char c[4];
    std::memcpy(c, &v, 4);
    b.append(c, 4);
}
// Eine kleinste RBSP: ein Knoten, ein Blatt ohne Brushes, darin ein Patch
// 3 x 3 (flach auf z 0, x/y von -100 bis 100), Shader solid.
std::string patchBsp() {
    std::string lumps[18];
    {   // 1 shaders
        std::string& s = lumps[1];
        std::string name = "textures/probe/patch";
        name.resize(64, '\0');
        s += name;
        i32an(s, 0);
        i32an(s, 1);   // CONTENTS_SOLID
    }
    {   // 2 planes
        f32an(lumps[2], 0.0F);
        f32an(lumps[2], 0.0F);
        f32an(lumps[2], 1.0F);
        f32an(lumps[2], -10000.0F);
    }
    {   // 3 nodes: beide Kinder Blatt 0
        std::string& s = lumps[3];
        i32an(s, 0);
        i32an(s, -1);
        i32an(s, -1);
        for (int i = 0; i < 6; ++i) { i32an(s, i < 3 ? -4096 : 4096); }
    }
    {   // 4 leafs: cluster, area, mins, maxs, firstLeafSurface, numLeafSurfaces, firstLeafBrush, numLeafBrushes
        std::string& s = lumps[4];
        i32an(s, 0);
        i32an(s, 0);
        for (int i = 0; i < 6; ++i) { i32an(s, i < 3 ? -4096 : 4096); }
        i32an(s, 0);
        i32an(s, 1);
        i32an(s, 0);
        i32an(s, 0);
    }
    i32an(lumps[5], 0);   // leafsurfaces
    {   // 7 models
        std::string& s = lumps[7];
        for (int i = 0; i < 6; ++i) { f32an(s, i < 3 ? -4096.0F : 4096.0F); }
        i32an(s, 0);
        i32an(s, 1);
        i32an(s, 0);
        i32an(s, 0);
    }
    {   // 10 drawverts (80 Bytes): xyz, st, lightmap[4][2], normal, color[4][4]
        std::string& s = lumps[10];
        for (int j = 0; j < 3; ++j) {
            for (int i = 0; i < 3; ++i) {
                f32an(s, -100.0F + 100.0F * static_cast<float>(i));
                f32an(s, -100.0F + 100.0F * static_cast<float>(j));
                f32an(s, 0.0F);
                s.append(80 - 12, '\0');
            }
        }
    }
    {   // 13 surfaces (148 Bytes)
        std::string& s = lumps[13];
        std::string f(148, '\0');
        const auto setze = [&f](std::size_t at, std::int32_t v) { std::memcpy(&f[at], &v, 4); };
        setze(0, 0);     // shaderNum
        setze(4, -1);    // fogNum
        setze(8, 2);     // MST_PATCH
        setze(12, 0);    // firstVert
        setze(16, 9);    // numVerts
        setze(140, 3);   // patchWidth
        setze(144, 3);   // patchHeight
        s += f;
    }
    std::string b = "RBSP";
    i32an(b, 1);
    std::size_t ofs = 8 + 18 * 8;
    for (const std::string& l : lumps) {
        i32an(b, static_cast<std::int32_t>(ofs));
        i32an(b, static_cast<std::int32_t>(l.size()));
        ofs += l.size();
    }
    for (const std::string& l : lumps) { b += l; }
    return b;
}
}  // namespace teil3w

void teil3Patches() {
    std::printf("\n== teil 3: Patches (Pa1) ==\n");
    KollisionsKarte k;
    const bool gelesen = leseKollision(teil3w::patchBsp(), k);
    const float mins[3] = {-16.0F, -16.0F, -24.0F};
    const float maxs[3] = {16.0F, 16.0F, 40.0F};
    const float von[3] = {0.0F, 0.0F, 50.0F};
    const float bis[3] = {0.0F, 0.0F, -50.0F};
    const KollisionsSpur kasten = kollisionsSpur(k, von, mins, maxs, bis, kNavSolid);
    const float null3[3] = {0.0F, 0.0F, 0.0F};
    const float pVon[3] = {30.0F, 20.0F, 10.0F};
    const float pBis[3] = {30.0F, 20.0F, -10.0F};
    const KollisionsSpur punktSpur = kollisionsSpur(k, pVon, null3, null3, pBis, kNavSolid);
    // Der Kasten setzt mit den Fuessen (-24) auf dem Patch auf, eine Spur aus
    // einem Punkt bleibt SURFACE_CLIP_EPSILON darueber stehen.
    pruefe(gelesen && kasten.fraction < 1.0F && nah(kasten.endpos[2], 24.125, 0.05) && punktSpur.fraction < 1.0F &&
               nah(punktSpur.endpos[2], 0.125, 0.05),
           "Pa1 ein Patch haelt die Spur auf (CM_TraceThroughPatchCollide): Kasten bei z " + std::to_string(kasten.endpos[2]) +
               ", Punkt bei z " + std::to_string(punktSpur.endpos[2]) + " (" + std::to_string(k.patches.size()) + " Patch)");
}

// --- rc601 (bewegung, teil 3): ANGLE2SHORT (Q1) ---------------------------------
void teil3Winkel() {
    std::printf("\n== teil 3: ANGLE2SHORT (Q1) ==\n");
    // Q1 - Drehen von 0 nach 90 mit 330 Grad/s: im Spiel nach dem ersten
    // Denkbild SHORT2ANGLE(3003) = 16,49597, nach dem zweiten 32,99194 (nicht
    // 16,5 und 33 - NPC_UpdateAngles schneidet ueber ANGLE2SHORT ab).
    GierLauf g;
    g.yaw0 = 0.0F;
    g.t0 = 0.0;
    g.ziel = 90.0F;
    g.rate = 330.0F;
    const float b1 = g.bei(50.0);
    const float b2 = g.bei(100.0);
    pruefe(std::fabs(b1 - 16.4959717F) < 1e-4F && std::fabs(b2 - 32.991943F) < 1e-4F,
           "Q1 Drehen mit ANGLE2SHORT: nach 50 ms " + std::to_string(b1) + ", nach 100 ms " + std::to_string(b2));
    // Im Laufplan: jede Gier ist ein Vielfaches von 360/65536.
    LaufZustand start;
    start.ort = {0.0F, 0.0F, 24.0F};
    LaufWerte w;
    w.zielGesetzt = true;
    w.ziel = {0.0F, 300.0F, 24.0F};
    w.maxTempo = 150.0F;
    w.gehTempo = 90.0F;
    const LaufPlan p = planeLauf(*navWeltAusEntities({}), start, w, 0.0, 6000.0);
    bool alle = !p.zustaende.empty();
    for (const LaufZustand& z : p.zustaende) {
        const double stufen = static_cast<double>(z.gier) * 65536.0 / 360.0;
        if (std::fabs(stufen - std::round(stufen)) > 1e-3) { alle = false; }
    }
    pruefe(alle, "Q1 im Laufplan ist die Gier je Denkbild auf 65536 Stufen (SHORT2ANGLE)");
    // R1 - Regelwerk: CLASS_GUARD wird auf Stufe 2 nur in Movie Duels schneller
    // gedreht (NPC_spawn.cpp:1838-1856 MD), in OpenJK nicht (1087-1110).
    {
        NpcDef def;
        def.klasse = "CLASS_GUARD";
        float yMd = 90.0F;
        float yOjk = 90.0F;
        float g1 = 90.0F;
        float l1 = 300.0F;
        npcWerteBeimSpawnen(def, "imperial", 2, yMd, g1, l1);
        navMovieDuelsRegeln(false);
        npcWerteBeimSpawnen(def, "imperial", 2, yOjk, g1, l1);
        navMovieDuelsRegeln(true);
        pruefe(nah(yMd, 135.0, 0.01) && nah(yOjk, 90.0, 0.01),
               "R1 Regelwerk: CLASS_GUARD auf Stufe 2 - Movie Duels " + std::to_string(yMd) + ", OpenJK " + std::to_string(yOjk));
    }
}

// --- rc601 integ: Takt des Verhaltens je Regelwerk ---------------------------
//
// OpenJK ruft NPC_ExecuteBState nur alle FRAMETIME = 100 ms (NPC.cpp:2481-
// 2488; Jedi mit Schwert ab Rang lt auf g_spskill >= 2 alle 50), Movie Duels
// jedes Denkbild (NPC.cpp:2359-2368 MD). Dazwischen dreht OpenJK nur und
// laeuft mit dem letzten ucmd weiter (NPC.cpp:2512-2520): desiredYaw bleibt,
// und UpdateGoal (die Ankunft) kommt nur in Denkbildern mit Verhalten.
void regelwerkVerhaltenTakt() {
    pruefe(npcVerhaltenTaktMs(true, "WP_BLASTER", 0, "") == 50 && npcVerhaltenTaktMs(true, "WP_SABER", 3, "captain") == 50,
           "RW1 Movie Duels: Verhalten jedes Denkbild (50 ms)");
    pruefe(npcVerhaltenTaktMs(false, "WP_BLASTER", 3, "captain") == 100 && npcVerhaltenTaktMs(false, "WP_SABER", 1, "lt") == 100 &&
               npcVerhaltenTaktMs(false, "WP_SABER", 2, "ltjg") == 100 && npcVerhaltenTaktMs(false, "WP_SABER", 2, "") == 100,
           "RW2 OpenJK: Verhalten alle 100 ms (Blaster, Schwert auf Stufe 1, Rang ltjg/ohne Rang)");
    pruefe(npcVerhaltenTaktMs(false, "WP_SABER", 2, "lt") == 50 && npcVerhaltenTaktMs(false, "wp_saber", 3, "Commander") == 50,
           "RW3 OpenJK: Jedi mit Schwert, g_spskill >= 2, Rang > ltjg: 50 ms");
    // Ein Lauf, der anfangs seitwaerts schiebt (STEER lenkt in jedem
    // Verhaltensbild nach): unter OpenJK aendert sich desiredYaw nur in den
    // Denkbildern mit Verhalten (ab denkNullMs = 0: 0, 100, 200 ...).
    LaufZustand start;
    start.ort = {0.0F, 0.0F, 24.0F};
    start.tempoVek = {150.0F, 0.0F, 0.0F};
    start.denkNullMs = 0.0;
    LaufWerte w;
    w.zielGesetzt = true;
    w.ziel = {0.0F, 300.0F, 24.0F};
    w.maxTempo = 150.0F;
    w.gehTempo = 90.0F;
    const auto zaehle = [&](int takt, int& zwischen, int& gesamt, double& ankunft) {
        LaufWerte ww = w;
        ww.verhaltenTaktMs = takt;
        const LaufPlan p = planeLauf(*navWeltAusEntities({}), start, ww, 0.0, 8000.0);
        zwischen = 0;
        gesamt = 0;
        float vorher = start.wunschGier;
        for (const LaufTakt& tk : p.takte) {
            const bool verhalten = std::fmod(tk.t, 100.0) < 0.5;
            if (std::fabs(tk.zustandWunschGier - vorher) > 1e-4F) {
                ++gesamt;
                if (!verhalten) { ++zwischen; }
            }
            vorher = tk.zustandWunschGier;
        }
        ankunft = p.ankunftMs;
    };
    int z100 = 0;
    int g100 = 0;
    double a100 = 0.0;
    int z50 = 0;
    int g50 = 0;
    double a50 = 0.0;
    zaehle(100, z100, g100, a100);
    zaehle(50, z50, g50, a50);
    pruefe(z50 > 0 && g50 > 0, "RW4 Probe trifft: mit 50 ms aendert STEER desiredYaw auch zwischen den 100er-Bildern (" +
                                   std::to_string(z50) + " von " + std::to_string(g50) + ")");
    pruefe(z100 == 0 && g100 > 0, "RW5 OpenJK 100 ms: desiredYaw aendert sich nur in Denkbildern mit Verhalten (" +
                                      std::to_string(z100) + " dazwischen, " + std::to_string(g100) + " gesamt)");
    pruefe(a100 > 0.0 && std::fmod(a100, 100.0) < 0.5,
           "RW6 OpenJK 100 ms: die Ankunft (UpdateGoal) faellt in ein Denkbild mit Verhalten (" + std::to_string(a100) +
               " ms; mit 50 ms " + std::to_string(a50) + " ms)");
}

// rc604 fix604b (A1): OpenJK dreht NPCs nur in Denkbildern mit Verhalten. Im
// Zweig ohne Verhalten rechnet NPC_UpdateAngles(qtrue, qtrue) zwar ucmd.angles,
// gleich danach ueberschreibt memcpy(&ucmd, &NPCInfo->last_ucmd) sie wieder
// (code/game/NPC.cpp:2515-2520); last_ucmd stammt aus dem letzten
// NPC_ExecuteBState (NPC.cpp:2279). Also alle 100 ms ein 50-ms-Schritt.
void regelwerkDrehTakt() {
    std::printf("\n== fix604b A1: OpenJK dreht nur mit Verhalten ==\n");
    LaufZustand start;
    start.ort = {0.0F, 0.0F, 24.0F};
    start.tempoVek = {150.0F, 0.0F, 0.0F};
    start.denkNullMs = 0.0;
    LaufWerte w;
    w.zielGesetzt = true;
    w.ziel = {0.0F, 300.0F, 24.0F};
    w.maxTempo = 150.0F;
    w.gehTempo = 90.0F;
    w.verhaltenTaktMs = 100;
    const LaufPlan p = planeLauf(*navWeltAusEntities({}), start, w, 0.0, 8000.0);
    int zwischen = 0;
    int gesamt = 0;
    float vorher = start.gier;
    for (std::size_t i = 0; i < p.takte.size() && i < p.zustaende.size(); ++i) {
        const bool verhalten = std::fmod(p.takte[i].t, 100.0) < 0.5;
        if (std::fabs(p.zustaende[i].gier - vorher) > 1e-4F) {
            ++gesamt;
            if (!verhalten) { ++zwischen; }
        }
        vorher = p.zustaende[i].gier;
    }
    pruefe(zwischen == 0 && gesamt > 0, "RW7 OpenJK 100 ms: die Figur dreht (viewangles) nur in Denkbildern mit Verhalten (" +
                                            std::to_string(zwischen) + " dazwischen, " + std::to_string(gesamt) + " gesamt)");
    // Der Regler im Stand (GierLauf, SET_DYAW): Takt 100 ab denkNullMs 0 -
    // Schritte bei 100, 200 ...; dazwischen gilt der alte Winkel.
    GierLauf g;
    g.yaw0 = 0.0F;
    g.t0 = 0.0;
    g.ziel = 90.0F;
    g.rate = 330.0F;
    g.taktMs = 100;
    g.denkNullMs = 0.0;
    const float b50 = g.bei(50.0);
    const float b100 = g.bei(100.0);
    const float b200 = g.bei(200.0);
    pruefe(b50 == 0.0F && std::fabs(b100 - 16.4959717F) < 1e-4F && std::fabs(b200 - 32.991943F) < 1e-4F,
           "RW8 GierLauf mit Takt 100: 50 ms " + std::to_string(b50) + ", 100 ms " + std::to_string(b100) + ", 200 ms " +
               std::to_string(b200));
    // TID_ANGLE_FACE: 20 Grad bei 330 Grad/s sind zwei Schritte (16,5 + 3,5);
    // mit 50 ms fertig nach 150 ms, mit Takt 100 ab Phase 0: Schritte bei 100
    // und 200, "exact" im Denkbild danach - 250 ms.
    const double h50 = drehHalteMs(0.0F, 20.0F, 330.0F);
    const double h100 = drehHalteMs(0.0F, 20.0F, 330.0F, DrehTakt{100, 0.0, 0.0});
    const double n100 = drehHalteMs(20.0F, 330.0F, DrehTakt{100, 0.0, 0.0});
    pruefe(h50 == 150.0 && h100 == 250.0 && n100 == 250.0,
           "RW9 TID_ANGLE_FACE mit Takt 100: " + std::to_string(h100) + " ms (Nick " + std::to_string(n100) + ", mit 50 ms " +
               std::to_string(h50) + ")");
    // Movie Duels: Takt 50 - unveraendert.
    const double hMd = drehHalteMs(0.0F, 20.0F, 330.0F, DrehTakt{50, 0.0, 0.0});
    pruefe(hMd == 150.0, "RW10 Takt 50 (Movie Duels) unveraendert: " + std::to_string(hMd) + " ms");
    // rc604: Jedi Outcast hat denselben memcpy (codeJK2/game/NPC.cpp:2111-2113)
    // und denselben Verhaltenstakt (NPC.cpp:2084-2091: FRAMETIME, Jedi mit
    // Schwert ab g_spskill 2 und Rang > ltjg FRAMETIME/2) - auch der Regler im
    // Stand dreht dort nur mit Verhalten.
    regelwerkAnwendenSpiel(kRegelwerkJediOutcast, 2);
    const int jk2Blaster = npcDrehTaktMs("WP_BLASTER", "");
    const int jk2Jedi = npcDrehTaktMs("WP_SABER", "commander");
    const int jk2Reborn = npcDrehTaktMs("WP_SABER", "ltjg");
    regelwerkAnwenden(true, -1);
    pruefe(jk2Blaster == 100 && jk2Jedi == 50 && jk2Reborn == 100,
           "RW11 Jedi Outcast: Drehtakt wie das Verhalten (Blaster " + std::to_string(jk2Blaster) + ", Jedi " +
               std::to_string(jk2Jedi) + ", Reborn " + std::to_string(jk2Reborn) + ")");
}

// rc602 kartenpruefung: "duel_jt_outside" (1100 Wegpunkte) brachte behaved
// nach einer anderen Karte zum Absturz - baueNavNetz nahm 1024 echte Knoten,
// der Platzhalter [0] dazu macht 1025, n.region hat aber nur NUM_NODES (1024)
// Plaetze: Schreiben hinter das Ende. Im Spiel fasst der Pool mNodes
// (ragl/graph_vs.h:211, pool_vs<TNODE, MAXNODES>) NUM_NODES EINSCHLIESSLICH
// des Platzhalters (insert_node -> mNodes.alloc(), graph_vs.h:540 "dummy node
// at location 0") - mehr als 1023 echte Punkte gehen nicht hinein.
void knotenGrenze() {
    MapData m;
    std::string text = "{\n\"classname\" \"worldspawn\"\n}\n";
    for (int i = 0; i < 1100; ++i) {
        char z[160];
        std::snprintf(z, sizeof(z), "{\n\"classname\" \"waypoint\"\n\"origin\" \"%d %d 24\"\n}\n", (i % 40) * 64,
                      (i / 40) * 64);
        text += z;
    }
    parseEntities(text, m.entities);
    const auto netz = baueNavNetz(m.entities, NavBauHilfe{});
    const std::size_t echte = netz->knoten.size() - 1U;
    pruefe(echte <= 1023U, "KG1 hoechstens 1023 echte Wegpunkte (Pool NUM_NODES mit Platzhalter), sind " +
                               std::to_string(echte));
    pruefe(netz->region.size() >= netz->knoten.size(), "KG2 n.region fasst jeden Knoten (" +
                                                          std::to_string(netz->region.size()) + " / " +
                                                          std::to_string(netz->knoten.size()) + ")");
}

// --- rc605 (fix605): SET_SOLID true im Koerper eines anderen (UK13, UK14) ------
//
// Im Spiel scheitert Q3_SetSolid an SpotWouldTelefrag2; Q3_Set haelt dann
// TID_RESIZE (Q3_Interface.cpp:9496-9504 MD / 8900-8908 OpenJK), bis
// SolidifyOwner (alle FRAMETIME = 100 ms ab dem Befehl) keinen anderen Koerper
// mehr findet (Q3_Interface.cpp:6031-6056 MD / 5589-5615 OpenJK). Ein dowait auf
// den set wartet so lange; der Ablauf machte ihn sofort fertig.
void festWarten() {
    std::printf("\n== fix605: SET_SOLID true wartet, bis die Figur fest werden kann (UK13, UK14) ==\n");
    const auto zeit = [](const char* bOrt, const std::string& bBefehle) {
        const std::string text = std::string(kKarteAblauf) +
                                 "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"b\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"" +
                                 bOrt + "\"\n}\n";
        const MapData m = karte(text.c_str());
        AblaufWelt w;
        w.karte = &m;
        const Ablauf a = simuliereAblauf(lies("affect ( \"b\", FLUSH )\n{\n" + bBefehle + "}\n" +
                                             inA("\tset ( \"SET_SOLID\", \"false\" );\n\ttask ( \"fest\" )\n\t{\n"
                                                 "\t\tset ( \"SET_SOLID\", \"true\" );\n\t}\n"
                                                 "\tdowait ( \"fest\" );\n\tprint ( \"fest\" );\n")),
                                         "", w);
        return zeitVon(a, "a", "print", "fest");
    };
    // b steht 10 neben a (die Kaesten ueberlappen) und geht bei 1000 weg.
    const double t1 = zeit("10 0 0", "\twait ( 1000.000 );\n\tset ( \"SET_ORIGIN\", \"500 0 0\" );\n");
    pruefe(t1 >= 1000.0 && t1 <= 1150.0,
           "UK13 a in b: dowait auf SET_SOLID true endet erst, wenn b weg ist (1000-1150, ist " + std::to_string(t1) + ")");
    // b 40 weit (Kaesten 32 breit, absmin/absmax 1 weiter): kein Treffer, sofort fest.
    const double t2 = zeit("40 0 0", "\twait ( 1000.000 );\n\tset ( \"SET_ORIGIN\", \"500 0 0\" );\n");
    pruefe(t2 >= 0.0 && t2 < 60.0, "UK14 b 40 weit: SET_SOLID true sofort fertig (ist " + std::to_string(t2) + ")");
}

// --- rc604 fix604: contents/clipmask je Zeit im gemeinsamen Takt (UK1-UK7) ----
//
// md_ga_sith, intro_sith.ibi: col1 ist SET_INVISIBLE true - im Spiel contents
// 0 (Q3_SetInvisible, Q3_Interface.cpp:3101-3128 MD). dok1 drueckte in der
// Vorschau sieben Sekunden gegen ihren Kasten. SET_SOLID false: CONTENTS_CORPSE
// und clipmask ohne CONTENTS_BODY, SET_SOLID true: CONTENTS_BODY erst, wenn
// SpotWouldTelefrag2 keinen anderen Koerper findet (SolidifyOwner alle 100 ms),
// SFB_NOTSOLID (spawnflags 64): contents 0 ab NPC_Begin.
void koerperFest() {
    std::printf("\n== fix604: unsichtbare/nicht feste Figuren im gemeinsamen Takt (UK1-UK7) ==\n");
    const std::vector<ProbeKlotz> boden = {{{-3000, -3000, -16}, {3000, 3000, 0}, kNavSolid}};
    auto welt = std::make_shared<NavWelt>();
    welt->spur = [boden](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int, std::uint32_t maske) {
        return probeSpur(boden, a, mi, ma, b, maske);
    };
    welt->boden = [](float, float, float zOben, float zUnten, float& z) {
        if (zOben < 0.0F || zUnten > 0.0F) { return false; }
        z = 0.0F;
        return true;
    };
    struct Erg {
        double an = -1.0;
        float quer = 0.0F;
        float rest = 999.0F;
    };
    // a geht von (0 0) nach (zx 0); b steht bei (bx by) - oder fehlt (bx > 1e5).
    const auto lauf = [&](float zx, float bx, float by, int sfA, int sfB, const std::string& skriptB, const std::string& skriptA) {
        char k[1200];
        std::snprintf(k, sizeof(k),
                      "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"a\"\n\"NPC_type\" \"jedi\"\n\"spawnflags\" \"%d\"\n"
                      "\"origin\" \"0 0 24.125\"\n}\n"
                      "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"za\"\n\"origin\" \"%.0f 0 24\"\n}\n",
                      sfA, static_cast<double>(zx));
        std::string kt = k;
        if (bx < 1.0e5F) {
            std::snprintf(k, sizeof(k),
                          "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"b\"\n\"NPC_type\" \"jedi\"\n\"spawnflags\" \"%d\"\n"
                          "\"origin\" \"%.0f %.0f 24.125\"\n}\n",
                          sfB, static_cast<double>(bx), static_cast<double>(by));
            kt += k;
        }
        const MapData m = karte(kt.c_str());
        AblaufWelt aw;
        aw.karte = &m;
        aw.nav = welt;
        std::string text;
        if (!skriptB.empty()) { text += "affect ( \"b\", FLUSH )\n{\n" + skriptB + "}\n"; }
        text += "affect ( \"a\", FLUSH )\n{\n" + skriptA + "\tset ( \"SET_WALKING\", \"true\" );\n"
                "\tset ( \"SET_NAVGOAL\", \"za\" );\n\twait ( 15000 );\n}\n";
        const Ablauf ab = simuliereAblaufMitKoerpern(lies(text), "", aw, nullptr);
        SzenenHilfe h;
        h.nav = welt;
        h.koerperPlaene = aw.koerperPlaene;
        const Scene s = buildScene(ab.flach, m, &h);
        Erg e;
        const Actor* fa = figur(s, "a");
        if (fa == nullptr) { return e; }
        e.an = ankunftVon(*fa);
        for (double t = 0.0; t <= 15000.0; t += 50.0) { e.quer = std::max(e.quer, std::fabs(fa->at(t).pos[1])); }
        e.rest = std::hypot(zx - fa->at(15000.0).pos[0], fa->at(15000.0).pos[1]);
        return e;
    };
    const auto zeige = [](const char* was, const Erg& e) {
        std::printf("  info  %s: angekommen %.0f, quer %.1f, Rest %.1f\n", was, e.an, static_cast<double>(e.quer),
                    static_cast<double>(e.rest));
    };
    const auto gleich = [](const Erg& x, const Erg& y) { return x.an > 0.0 && nah(x.an, y.an, 0.5) && nah(x.quer, y.quer, 0.01); };
    const std::string unsichtbar = "\tset ( \"SET_INVISIBLE\", \"true\" );\n";
    const Erg ohne = lauf(300.0F, 1.0e6F, 0.0F, 0, 0, "", "");
    // b braucht einen Befehl, sonst kennt der Ablauf ihn nicht (Wesen nur fuer
    // Namen aus den Skripten).
    const std::string nichts = "\tset ( \"SET_PARM1\", \"1\" );\n";
    const Erg fest = lauf(300.0F, 150.0F, 0.0F, 0, 0, nichts, "");
    zeige("ohne b", ohne);
    zeige("b fest im Weg", fest);
    pruefe(ohne.an > 0.0 && !gleich(fest, ohne), "UK0 Bezug: ein fester Koerper im Weg aendert den Weg");
    const Erg u1 = lauf(300.0F, 150.0F, 0.0F, 0, 0, unsichtbar, "");
    zeige("b SET_INVISIBLE true", u1);
    pruefe(gleich(u1, ohne), "UK1 SET_INVISIBLE true: contents 0 - a geht wie ohne b (Ankunft " + std::to_string(u1.an) + " / " +
                                 std::to_string(ohne.an) + ")");
    const Erg u2 = lauf(300.0F, 150.0F, 0.0F, 0, 0, "\tset ( \"SET_SOLID\", \"false\" );\n", "");
    zeige("b SET_SOLID false", u2);
    pruefe(gleich(u2, ohne), "UK2 SET_SOLID false: CONTENTS_CORPSE - a geht wie ohne b");
    const Erg u3 = lauf(300.0F, 150.0F, 0.0F, 0, 0, unsichtbar + "\tset ( \"SET_INVISIBLE\", \"false\" );\n", "");
    zeige("b SET_INVISIBLE true, dann false", u3);
    pruefe(gleich(u3, ohne), "UK3 SET_INVISIBLE false stellt contents nicht zurueck - a geht wie ohne b");
    const Erg u4 = lauf(300.0F, 150.0F, 0.0F, 0, 64, nichts, "");
    zeige("b mit SFB_NOTSOLID", u4);
    pruefe(gleich(u4, ohne), "UK4 SFB_NOTSOLID am Spawner: contents 0 ab NPC_Begin - a geht wie ohne b");
    const Erg u5 = lauf(300.0F, 150.0F, 0.0F, 0, 0, unsichtbar + "\tset ( \"SET_SOLID\", \"true\" );\n", "");
    zeige("b SET_INVISIBLE true, dann SET_SOLID true", u5);
    pruefe(gleich(u5, fest), "UK5 SET_SOLID true nach SET_INVISIBLE: wieder CONTENTS_BODY - wie b fest");
    // UK6: b (SFB_NOTSOLID) steht in a; SET_SOLID true bei 0 - SpotWouldTelefrag2
    // findet a, SolidifyOwner versucht es alle 100 ms, bis a weg ist. a geht
    // von b weg wie ohne b. Ohne die Pruefung wuerde b sofort fest und a
    // steckte in ihm.
    const Erg o6 = lauf(-300.0F, 1.0e6F, 0.0F, 0, 0, "", "");
    const Erg u6 = lauf(-300.0F, 24.0F, 0.0F, 0, 64, "\tset ( \"SET_SOLID\", \"true\" );\n", "");
    zeige("ohne b, nach -300", o6);
    zeige("b in a, SET_SOLID true", u6);
    pruefe(gleich(u6, o6), "UK6 SET_SOLID true in einem anderen Koerper: erst fest, wenn er weg ist (SolidifyOwner) - a geht wie ohne b");
    // UK7: a selbst SET_SOLID false (clipmask ohne CONTENTS_BODY), b fest in
    // a: Pmove spurt mit pm.tracemask = clipmask und haelt a nicht auf.
    const Erg u7 = lauf(-300.0F, 24.0F, 0.0F, 0, 0, nichts, "\tset ( \"SET_SOLID\", \"false\" );\n");
    const Erg f7 = lauf(-300.0F, 24.0F, 0.0F, 0, 0, nichts, "");
    zeige("a SET_SOLID false, b fest in a", u7);
    zeige("a fest, b fest in a", f7);
    pruefe(u7.an > 0.0 && u7.rest < 24.0F, "UK7 a ohne CONTENTS_BODY in der clipmask kommt aus b heraus an (Ankunft " +
                                              std::to_string(u7.an) + ", Rest " + std::to_string(u7.rest) + ")");
    // UK8/UK9: eine Figur vom Kartenstart, die kein Skript nennt (Spawner ohne
    // targetname, ohne NPC_targetname): im Spiel ein Koerper ab NPC_Begin -
    // die Vorschau zeichnet sie, a ging bis fix604 durch sie hindurch. Mit
    // SFB_NOTSOLID nicht.
    const auto ohneName = [&](int sf) {
        char k[600];
        std::snprintf(k, sizeof(k),
                      "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"a\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"0 0 24.125\"\n}\n"
                      "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"za\"\n\"origin\" \"300 0 24\"\n}\n"
                      "{\n\"classname\" \"NPC_spawner\"\n\"NPC_type\" \"jedi\"\n\"spawnflags\" \"%d\"\n\"origin\" \"150 0 24.125\"\n}\n",
                      sf);
        const MapData m = karte(k);
        AblaufWelt aw;
        aw.karte = &m;
        aw.nav = welt;
        const std::string text = "affect ( \"a\", FLUSH )\n{\n\tset ( \"SET_WALKING\", \"true\" );\n"
                                 "\tset ( \"SET_NAVGOAL\", \"za\" );\n\twait ( 15000 );\n}\n";
        const Ablauf ab = simuliereAblaufMitKoerpern(lies(text), "", aw, nullptr);
        SzenenHilfe h;
        h.nav = welt;
        h.koerperPlaene = aw.koerperPlaene;
        const Scene s = buildScene(ab.flach, m, &h);
        Erg e;
        const Actor* fa = figur(s, "a");
        if (fa == nullptr) { return e; }
        e.an = ankunftVon(*fa);
        for (double t = 0.0; t <= 15000.0; t += 50.0) { e.quer = std::max(e.quer, std::fabs(fa->at(t).pos[1])); }
        e.rest = std::hypot(300.0F - fa->at(15000.0).pos[0], fa->at(15000.0).pos[1]);
        return e;
    };
    const Erg u8 = ohneName(0);
    const Erg u9 = ohneName(64);
    zeige("Kartenfigur ohne Namen im Weg", u8);
    zeige("Kartenfigur ohne Namen mit SFB_NOTSOLID", u9);
    pruefe(gleich(u8, fest), "UK8 eine Kartenfigur, die kein Skript nennt, ist ein Koerper - wie b fest");
    pruefe(gleich(u9, ohne), "UK9 ... mit SFB_NOTSOLID nicht - a geht wie ohne sie");
    // UK10-UK12: eine getoetete Figur bleibt ein Koerper, bis CorpsePhysics sie
    // zur Leiche macht (level.time - s.time > 5000 MD / > 500 OpenJK,
    // NPC.cpp:209 MD / 122 OpenJK; s.time = Todeszeit, g_combat.cpp:5854 MD /
    // 4690 OpenJK). Das deathscript laeuft ab dem Tod (player_die,
    // G_ActivateBehavior BSET_DEATH, g_combat.cpp:5824 MD / 4657 OpenJK): wer es
    // als Reiter oeffnet, sieht den Traeger tot ab 0.
    bool mark1 = false;   // rc605 fix605: b ist ein Mark1 (AblaufWelt::bleibtFest)
    const auto mitText = [&](const std::string& kt, const std::string& text, const std::string& pfad) {
        const MapData m = karte(kt.c_str());
        AblaufWelt aw;
        aw.karte = &m;
        aw.nav = welt;
        if (mark1) { aw.bleibtFest = [](const std::string& f) { return f == "b"; }; }
        const Ablauf ab = simuliereAblaufMitKoerpern(lies(text), pfad, aw, nullptr);
        SzenenHilfe h;
        h.nav = welt;
        h.koerperPlaene = aw.koerperPlaene;
        const Scene s = buildScene(ab.flach, m, &h);
        Erg e;
        const Actor* fa = figur(s, "a");
        if (fa == nullptr) { return e; }
        e.an = ankunftVon(*fa);
        for (double t = 0.0; t <= 20000.0; t += 50.0) { e.quer = std::max(e.quer, std::fabs(fa->at(t).pos[1])); }
        e.rest = std::hypot(300.0F - fa->at(20000.0).pos[0], fa->at(20000.0).pos[1]);
        return e;
    };
    const std::string kartA = "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"a\"\n\"NPC_type\" \"jedi\"\n\"origin\" \"0 0 24.125\"\n}\n"
                              "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"za\"\n\"origin\" \"300 0 24\"\n}\n";
    const std::string kartB = "{\n\"classname\" \"NPC_spawner\"\n\"npc_targetname\" \"b\"\n\"NPC_type\" \"jedi\"\n"
                              "\"deathscript\" \"probe/tod\"\n\"origin\" \"150 0 24.125\"\n}\n";
    const std::string gehen = "affect ( \"a\", FLUSH )\n{\n\tset ( \"SET_WALKING\", \"true\" );\n"
                              "\tset ( \"SET_NAVGOAL\", \"za\" );\n\twait ( 15000 );\n}\n";
    const std::string toeten = "affect ( \"b\", FLUSH )\n{\n\tset ( \"SET_PARM1\", \"1\" );\n}\nkill ( \"b\" );\n";
    const Erg u10 = mitText(kartA + kartB, toeten + gehen, "");
    zeige("b bei 0 getoetet, a geht los (Movie Duels)", u10);
    pruefe(gleich(u10, fest), "UK10 Movie Duels: der Getoetete bleibt 5 s ein Koerper - a weicht aus wie bei b fest (Ankunft " +
                                  std::to_string(u10.an) + ", ohne b " + std::to_string(ohne.an) + ")");
    regelwerkAnwenden(false, -1);
    const Erg o11 = mitText(kartA, gehen, "");
    const Erg u11 = mitText(kartA + kartB, toeten + gehen, "");
    regelwerkAnwenden(true, -1);
    zeige("ohne b (OpenJK)", o11);
    zeige("b bei 0 getoetet, a geht los (OpenJK)", u11);
    pruefe(gleich(u11, o11), "UK11 OpenJK: nach 0,5 s eine Leiche - a geht wie ohne b");
    // UK12: der Reiter ist das deathscript von b; a geht erst nach 6 s los.
    const std::string spaeter = "wait ( 6000 );\n" + gehen;
    const Erg o12 = mitText(kartA, spaeter, "probe/tod");
    const Erg u12 = mitText(kartA + kartB, spaeter, "probe/tod");
    zeige("ohne b, a ab 6 s", o12);
    zeige("im deathscript von b, a ab 6 s", u12);
    pruefe(gleich(u12, o12), "UK12 im deathscript ist der Traeger tot: nach 5 s eine Leiche - a geht wie ohne b");
    // UK15/UK16 - rc605 (fix605): Mark1 und Interrogator bleiben nach dem Tod
    // CONTENTS_BODY (CorpsePhysics, NPC.cpp:209-216 MD / 122-127 OpenJK).
    regelwerkAnwenden(false, -1);
    const Erg f15 = mitText(kartA + kartB, gehen, "");
    mark1 = true;
    const Erg u15 = mitText(kartA + kartB, toeten + gehen, "");
    mark1 = false;
    regelwerkAnwenden(true, -1);
    zeige("b lebt (OpenJK)", f15);
    zeige("Mark1 b bei 0 getoetet (OpenJK)", u15);
    pruefe(gleich(u15, f15) && !gleich(u15, o11),
           "UK15 OpenJK: ein getoeteter Mark1 wird nie zur Leiche - a weicht aus wie bei b lebend");
    mark1 = true;
    const Erg u16 = mitText(kartA + kartB, spaeter, "probe/tod");
    mark1 = false;
    const Erg f16 = mitText(kartA + kartB, spaeter, "");
    zeige("im deathscript des Mark1 b, a ab 6 s", u16);
    pruefe(gleich(u16, f16) && !gleich(u16, o12), "UK16 im deathscript eines Mark1 bleibt der Traeger ein Koerper");
}

// --- rc604 fix604: netzTrefferRaster = netzTreffer, Bit fuer Bit (NR1-NR7) ----
//
// md_roc_jedi, "Schwerkraft (mit Movern)": 20-48 s je Reiter, 95 % davon in
// netzTreffer (jedes Dreieck jedes Brush-Modells je Strahl). Das Raster fragt
// nur die Dreiecke der Zelle (plus die fast senkrechten) - es muss fuer jeden
// senkrechten Strahl genau dasselbe liefern: Treffer ja/nein und dieselben Bits.
void netzRasterProben() {
    std::printf("\n== fix604: Raster fuer senkrechte Strahlen gegen Brush-Modelle (NR1-NR7) ==\n");
    std::uint64_t zufall = 0x9E3779B97F4A7C15ULL;
    const auto zahl = [&zufall]() {
        zufall ^= zufall << 13;
        zufall ^= zufall >> 7;
        zufall ^= zufall << 17;
        return zufall;
    };
    const auto gleich01 = [&zahl]() { return static_cast<float>(static_cast<double>(zahl() >> 11) / 9007199254740992.0); };
    // Ein Netz aus allerlei Dreiecken: flach, schraeg, senkrecht an den Achsen,
    // senkrecht schraeg, Splitter, winzig, gross, Ecken auf ganzen Zahlen (wie
    // Brushes) und krumme (wie unterteilte Patches); zwei Batches, einer nicht fest.
    BspMesh netz;
    const auto ecke = [&netz](float x, float y, float z) {
        BspVertex v;
        v.xyz[0] = x;
        v.xyz[1] = y;
        v.xyz[2] = z;
        netz.verts.push_back(v);
        return static_cast<std::uint32_t>(netz.verts.size() - 1U);
    };
    const auto dreieck = [&](float ax, float ay, float az, float bx, float by, float bz, float cx, float cy, float cz) {
        netz.indexes.push_back(ecke(ax, ay, az));
        netz.indexes.push_back(ecke(bx, by, bz));
        netz.indexes.push_back(ecke(cx, cy, cz));
    };
    for (int i = 0; i < 4000; ++i) {
        const int art = i % 8;
        const bool ganz = (i / 8) % 2 == 0;
        float x = (gleich01() - 0.5F) * 2000.0F;
        float y = (gleich01() - 0.5F) * 2000.0F;
        float z = (gleich01() - 0.5F) * 400.0F;
        if (ganz) {
            x = std::round(x / 8.0F) * 8.0F;
            y = std::round(y / 8.0F) * 8.0F;
            z = std::round(z);
        }
        const float g = art == 5 ? 0.01F + gleich01() : (art == 6 ? 200.0F + gleich01() * 800.0F : 8.0F + gleich01() * 120.0F);
        const float gx = ganz ? std::round(g) + 1.0F : g;
        switch (art) {
            case 0: dreieck(x, y, z, x + gx, y, z, x, y + gx, z); break;                        // flach
            case 1: dreieck(x, y, z, x + gx, y, z + gx * 0.5F, x, y + gx, z + 3.0F); break;     // schraeg
            case 2: dreieck(x, y, z, x, y + gx, z, x, y, z + gx); break;                        // senkrecht x = const
            case 3: dreieck(x, y, z, x + gx, y, z, x + gx, y, z + gx); break;                   // senkrecht y = const
            case 4: dreieck(x, y, z, x + gx, y + gx, z, x + gx, y + gx, z + gx); break;         // senkrecht schraeg
            case 7: dreieck(x, y, z, x + gx, y + gx * 1.0e-4F, z + 1.0F, x + gx * 2.0F, y + gx * 3.0e-4F, z); break;   // Splitter
            default: dreieck(x, y, z, x + gx, y + gx * 0.3F, z + gx * 0.2F, x - gx * 0.2F, y + gx, z - gx * 0.1F); break;
        }
    }
    BspMesh::Batch b0;
    b0.shader = 0;
    b0.firstIndex = 0;
    b0.numIndexes = static_cast<std::uint32_t>(netz.indexes.size() / 2U / 3U * 3U);
    BspMesh::Batch b1;
    b1.shader = 1;
    b1.firstIndex = b0.numIndexes;
    b1.numIndexes = static_cast<std::uint32_t>(netz.indexes.size()) - b0.numIndexes;
    netz.batches = {b0, b1};
    // Die Strahlen: zufaellig, genau auf Ecken, auf Kanten (Mitte), auf der
    // Geraden senkrechter Dreiecke weit draussen, und ganz ausserhalb.
    std::vector<std::array<float, 2>> punkte;
    for (int i = 0; i < 30000; ++i) {
        punkte.push_back({(gleich01() - 0.5F) * 2400.0F, (gleich01() - 0.5F) * 2400.0F});
    }
    for (std::size_t i = 0; i + 2 < netz.indexes.size(); i += 3) {
        const float* p = netz.verts[netz.indexes[i]].xyz;
        const float* q = netz.verts[netz.indexes[i + 1]].xyz;
        punkte.push_back({p[0], p[1]});
        punkte.push_back({(p[0] + q[0]) * 0.5F, (p[1] + q[1]) * 0.5F});
        punkte.push_back({p[0] + (q[0] - p[0]) * 7.0F, p[1] + (q[1] - p[1]) * 7.0F});
    }
    punkte.push_back({1.0e5F, -1.0e5F});
    const auto hashDazu = [](std::uint64_t h, const void* d, std::size_t n) {
        const auto* c = static_cast<const unsigned char*>(d);
        for (std::size_t i = 0; i < n; ++i) { h = (h ^ c[i]) * 1099511628211ULL; }
        return h;
    };
    // Ohne Reichweite (fast senkrechte immer gefragt), mit einer, die nicht
    // alle Strahlen deckt (ausserhalb alle), und mit einer, die alle deckt.
    int nr = 0;
    for (const float reichweite : {0.0F, 1500.0F, 12000.0F}) {
    for (const std::vector<bool>& fest : {std::vector<bool>{}, std::vector<bool>{true, false}}) {
        ++nr;
        const NetzRaster r = baueNetzRaster(netz, fest, 32.0F, reichweite);
        std::uint64_t ha = 1469598103934665603ULL;
        std::uint64_t hb = 1469598103934665603ULL;
        int treffer = 0;
        int verschieden = 0;
        double msAlt = 0.0;
        double msNeu = 0.0;
        for (const auto& pt : punkte) {
            for (const float zo : {300.0F, 37.5F}) {
                const float von[3] = {pt[0], pt[1], zo};
                const float bis[3] = {pt[0], pt[1], zo - 380.0F};
                float ta[3] = {0.0F, 0.0F, 0.0F};
                float tb[3] = {0.0F, 0.0F, 0.0F};
                const auto t0 = std::chrono::steady_clock::now();
                const bool a = netzTreffer(netz, fest, von, bis, ta);
                const auto t1 = std::chrono::steady_clock::now();
                const bool bb = netzTrefferRaster(netz, r, fest, von, bis, tb);
                const auto t2 = std::chrono::steady_clock::now();
                msAlt += std::chrono::duration<double, std::milli>(t1 - t0).count();
                msNeu += std::chrono::duration<double, std::milli>(t2 - t1).count();
                ha = hashDazu(ha, &a, 1);
                hb = hashDazu(hb, &bb, 1);
                if (a) { ha = hashDazu(ha, ta, sizeof(ta)); }
                if (bb) { hb = hashDazu(hb, tb, sizeof(tb)); }
                treffer += a ? 1 : 0;
                if (a != bb || (a && std::memcmp(ta, tb, sizeof(ta)) != 0)) { ++verschieden; }
            }
        }
        std::printf("  info  NR%d (Reichweite %.0f) %zu Dreiecke, %zu Strahlen, %d Treffer, %zu fast senkrecht%s, Zellen %dx%d, "
                    "Eintraege %zu: alt %.1f ms, Raster %.1f ms, Hash %016llx / %016llx\n",
                    nr, static_cast<double>(reichweite), netz.indexes.size() / 3U, punkte.size() * 2U, treffer, r.immer.size(),
                    r.streifen ? " (Streifen)" : "", r.nx, r.ny, r.liste.size(), msAlt, msNeu,
                    static_cast<unsigned long long>(ha), static_cast<unsigned long long>(hb));
        pruefe(verschieden == 0 && ha == hb && treffer > 1000,
               "NR" + std::to_string(nr) + (fest.empty() ? " alles fest" : " ein Batch nicht fest") + ", Reichweite " +
                   std::to_string(static_cast<int>(reichweite)) + ": jeder senkrechte Strahl trifft mit Raster Bit fuer Bit wie ohne (" +
                   std::to_string(verschieden) + " verschieden)");
    }
    }
    // NR7: ein schraeger Strahl (gekipptes Modell) geht an netzTreffer.
    {
        const NetzRaster r = baueNetzRaster(netz, {}, 32.0F, 1500.0F);
        int verschieden = 0;
        for (int i = 0; i < 2000; ++i) {
            const float von[3] = {(gleich01() - 0.5F) * 2000.0F, (gleich01() - 0.5F) * 2000.0F, 300.0F};
            const float bis[3] = {von[0] + 3.0F, von[1] - 2.0F, -100.0F};
            float ta[3] = {0.0F, 0.0F, 0.0F};
            float tb[3] = {0.0F, 0.0F, 0.0F};
            const bool a = netzTreffer(netz, {}, von, bis, ta);
            const bool bb = netzTrefferRaster(netz, r, {}, von, bis, tb);
            if (a != bb || (a && std::memcmp(ta, tb, sizeof(ta)) != 0)) { ++verschieden; }
        }
        pruefe(verschieden == 0, "NR7 schraege Strahlen: wie netzTreffer");
    }
}

// --- rc605: NPC-Spruenge (NPC_TryJump / NPC_Jump, NPC_move.cpp MD) -----------
// SP1: blockiert vor einem Absatz 32 hoeher (wie kylo3 in md_acc_sith): kein
// Netz, STEER::SafeToGoTo scheitert an der Kante, NAV::GoTo findet keinen
// Knoten -> STEER::Blocked(tempGoal); nach mehr als 2 s blockiert
// NPC_TryJump(blockedTargetEntity). Erste Bahn: shotSpeed = Abstand, also
// travelTime 1 s, shotVel = Richtung * Abstand + (0, 0, 0.5 * 800 * 1).
// SP2: eine Decke ueber der ersten Bahn - der zweite Versuch (shotSpeed - 50)
// steigt hoeher und trifft auch, der dritte (shotSpeed + 50) geht durch.
// SP3: eine Sprungkante im Wegnetz (targetJump): STEER::Path -> NPC_TryJump(
// NextPosition); ohne SCF_NAV_CAN_JUMP ist die Kante ungueltig.
void spruenge605() {
    std::printf("\n== rc605: NPC-Spruenge (SP1-SP3) ==\n");
    const auto baueWelt = [](std::vector<ProbeKlotz> kl) {
        auto welt = std::make_shared<NavWelt>();
        welt->spur = [kl](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int, std::uint32_t maske) {
            return probeSpur(kl, a, mi, ma, b, maske);
        };
        welt->boden = [](float x, float, float zOben, float zUnten, float& z) {
            const float oben = x < 100.0F ? 0.0F : 32.0F;
            if (oben > zOben || oben < zUnten) { return false; }
            z = oben;
            return true;
        };
        return welt;
    };
    const std::vector<ProbeKlotz> absatz = {
        {{-2000, -2000, -16}, {100, 2000, 0}, kNavSolid},
        {{100, -2000, -16}, {2000, 2000, 32}, kNavSolid},
    };
    LaufWerte lw;
    lw.zielGesetzt = true;
    lw.ziel = {200.0F, 0.0F, 56.0F};
    lw.maxTempo = 300.0F;
    lw.gehTempo = 90.0F;
    LaufZustand start;
    start.ort = {0.0F, 0.0F, 24.125F};
    start.amBoden = true;
    const double d = std::sqrt(200.0 * 200.0 + (56.0 - 24.125) * (56.0 - 24.125));
    const auto sprungTakt = [](const LaufPlan& p) -> const LaufTakt* {
        for (const LaufTakt& k : p.takte) {
            if (k.sprung) { return &k; }
        }
        return nullptr;
    };
    // SP1
    {
        const auto welt = baueWelt(absatz);
        LaufWerte ohne = lw;
        const LaufPlan rot = planeLauf(*welt, start, ohne, 0.0, 12000.0);
        pruefe(rot.nie && rot.ankunftMs < 0.0 && sprungTakt(rot) == nullptr,
               "SP1a ohne SCF_NAV_CAN_JUMP: steht vor dem Absatz, kommt nie an (wie bis rc604)");
        LaufWerte mit = lw;
        mit.kannSpringen = true;
        const LaufPlan p = planeLauf(*welt, start, mit, 0.0, 12000.0);
        const LaufTakt* k = sprungTakt(p);
        // Erstes Denkbild 50 (blockedDebounceTime), "level.time -
        // blockedDebounceTime > 2000" zuerst bei 2100.
        const double vx = 200.0;
        const double vz = (56.0 - 24.125) + 0.5 * 800.0 * 1.0;
        pruefe(k != nullptr && nah(k->t, 2100.0, 0.1) && nah(k->sprungTempo[0], vx, 0.01) && nah(k->sprungTempo[1], 0.0, 0.01) &&
                   nah(k->sprungTempo[2], vz, 0.01),
               "SP1b blockiert -> Sprung bei 2100 mit shotVel 200 0 " + std::to_string(vz) + " (" +
                   (k != nullptr ? std::to_string(k->t) + ": " + std::to_string(k->sprungTempo[0]) + " " +
                                       std::to_string(k->sprungTempo[1]) + " " + std::to_string(k->sprungTempo[2])
                                 : std::string("kein Sprung")) + ")");
        const float zEnde = p.takte.empty() ? 0.0F : p.takte.back().ort[2];
        pruefe(p.ankunftMs > 2100.0 && !p.nie && nah(zEnde, 56.125, 0.2),
               "SP1c landet oben und kommt an (" + std::to_string(p.ankunftMs) + " ms, z " + std::to_string(zEnde) + ")");
        // rc605: SET_NO_ACROBATICS - NPC_CanTryJump (NPC_move.cpp:330 MD)
        // verweigert den Sprung trotz SCF_NAV_CAN_JUMP.
        LaufWerte akro = mit;
        akro.keineAkrobatik = true;
        const LaufPlan pa = planeLauf(*welt, start, akro, 0.0, 12000.0);
        pruefe(sprungTakt(pa) == nullptr && pa.ankunftMs < 0.0,
               "SP1d SET_NO_ACROBATICS true: springt nicht, kommt nie an (" +
                   (sprungTakt(pa) != nullptr ? "Sprung bei " + std::to_string(sprungTakt(pa)->t) : std::string("kein Sprung")) + ")");

        // rc605 FU4: die Animationskette des Sprungs. NPC_JumpAnimation setzt
        // BOTH + HOLD (Laenge 400), der Pmove nimmt den "kickoff"-Zweig von
        // PM_GroundTrace -> PM_JumpForDir: Beine BOTH_JUMP1 ohne HOLD, der
        // Oberkoerper behaelt BOTH_FORCEJUMP1, bis sein Timer ablaeuft (PM_DropTimers
        // in den Pmoves 2100..2450), dann folgt er den Beinen (PM_TorsoAnimation).
        // Landung: PM_CrashLand (delta = |vz| / 10, jumpZStart 0) ->
        // PM_GetLandingAnim(BOTH_JUMP1) = BOTH_LAND1 und velocity x/y halb;
        // PM_ForceJumpingAnim(BOTH_JUMP1) und Oberkoerper == Beine -> BOTH, HOLD
        // 300; danach waehlt PM_Footsteps.
        const auto kette = [&](int art, int sprungMs, std::string& text) {
            LaufWerte kw = mit;
            kw.sprungAnimArt = art;
            kw.sprungAnimMs = sprungMs;
            kw.landMs = 300;
            kw.forceLandMs = 350;
            LaufPlan kp = planeLauf(*welt, start, kw, 0.0, 12000.0);
            std::size_t ab = kp.takte.size();
            std::size_t land = kp.takte.size();
            for (std::size_t i = 0; i < kp.takte.size(); ++i) {
                if (kp.takte[i].sprung && ab == kp.takte.size()) { ab = i; }
                if (ab < i && land == kp.takte.size() && i < kp.zustaende.size() && kp.zustaende[i].amBoden) { land = i; }
            }
            text.clear();
            for (std::size_t i = (ab >= 1 && ab < kp.takte.size()) ? ab - 1 : 0; i < kp.takte.size() && i < land + 9; ++i) {
                const LaufTakt& k = kp.takte[i];
                if (i > ab + 9 && i + 2 < land) { continue; }
                text += " " + std::to_string(static_cast<int>(k.t)) + ":" + std::to_string(k.beinAnim) + "@" +
                        std::to_string(static_cast<int>(k.beinAnimAb)) + "/" + std::to_string(k.torsoAnim) + "@" +
                        std::to_string(static_cast<int>(k.torsoAnimAb));
            }
            return std::make_tuple(kp, ab, land);
        };
        std::string txt;
        {
            const auto [kp, ab, land] = kette(0, 400, txt);
            bool ok = ab < kp.takte.size() && land < kp.takte.size() && land > 0;
            if (ok) {
                const LaufTakt& k0 = kp.takte[ab];
                ok = k0.beinAnim == kSaJump1 && nah(k0.beinAnimAb, 2100.0, 0.1) && k0.torsoAnim == kSaSprung &&
                     nah(k0.torsoAnimAb, 2100.0, 0.1);
                for (std::size_t i = ab; ok && i < land; ++i) {
                    const LaufTakt& k = kp.takte[i];
                    const bool torsoFrei = k.t >= 2450.0 - 0.1;
                    ok = k.beinAnim == kSaJump1 && nah(k.beinAnimAb, 2100.0, 0.1) &&
                         (torsoFrei ? k.torsoAnim == kSaKeine : k.torsoAnim == kSaSprung);
                }
                const LaufTakt& kl = kp.takte[land];
                const double tl = kl.t;
                // velocity x 200 vor der Landung; halb (100), dann PM_Friction
                // im selben Pmove - ohne "stick landings some" blieben ueber 100.
                const float vxLand = kp.zustaende[land].tempoVek[0];
                txt += " | vx " + std::to_string(kp.zustaende[land - 1].tempoVek[0]) + " -> " + std::to_string(vxLand);
                ok = ok && kl.beinAnim == kSaLand1 && nah(kl.beinAnimAb, tl, 0.1) && kl.torsoAnim == kSaKeine &&
                     nah(kp.zustaende[land - 1].tempoVek[0], 200.0, 0.5) && vxLand <= 100.0F;
                for (std::size_t i = land; ok && i < kp.takte.size(); ++i) {
                    const LaufTakt& k = kp.takte[i];
                    ok = k.t < tl + 300.0 - 0.1 ? (k.beinAnim == kSaLand1 && nah(k.beinAnimAb, tl, 0.1)) : k.beinAnim == kSaKeine;
                }
                ok = ok && kp.takte.back().t >= tl + 300.0 - 0.1;
            }
            pruefe(ok, "SP1e NPC_TryJump BOTH_FORCEJUMP1: Beine BOTH_JUMP1 ab 2100, Oberkoerper bis 2450, Landung BOTH_LAND1 "
                       "300 ms, velocity x halb (" + txt + ")");
        }
        {
            // SP1f: BOTH_FORCEJUMP1 laenger als der Flug - der Oberkoerper behaelt
            // ihn bei der Landung, BOTH_LAND1 nur auf den Beinen.
            const auto [kp, ab, land] = kette(0, 2000, txt);
            const bool ok = land < kp.takte.size() && land > 0 && kp.takte[land].beinAnim == kSaLand1 &&
                            kp.takte[land].torsoAnim == kSaSprung && nah(kp.takte[land].torsoAnimAb, 2100.0, 0.1) &&
                            kp.takte[land - 1].beinAnim == kSaJump1;
            pruefe(ok, "SP1f langer BOTH_FORCEJUMP1: Landung nur auf den Beinen, Oberkoerper behaelt ihn (" + txt + ")");
        }
        {
            // SP1g: BOTH_FLIP_F (PM_FlippingAnim) - kein PM_JumpForDir, ganzer
            // Koerper in der Luft; bei der Landung torsoAnimTimer = 0, BOTH_LAND1
            // auf den Beinen (PM_ForceJumpingAnim kennt BOTH_FLIP_F nicht), und
            // PM_TorsoAnimation laesst den Oberkoerper den Beinen folgen.
            const auto [kp, ab, land] = kette(1, 2000, txt);
            const bool ok = ab < kp.takte.size() && land < kp.takte.size() && land > 0 && kp.takte[ab].beinAnim == kSaSprung &&
                            kp.takte[land - 1].beinAnim == kSaSprung && kp.takte[land - 1].torsoAnim == kSaSprung &&
                            kp.takte[land].beinAnim == kSaLand1 && kp.takte[land].torsoAnim == kSaKeine;
            pruefe(ok, "SP1g BOTH_FLIP_F: ganzer Koerper in der Luft, Landung BOTH_LAND1, Oberkoerper folgt (" + txt + ")");
        }
    }
    // SP2
    {
        std::vector<ProbeKlotz> mitDecke = absatz;
        mitDecke.push_back({{40, -2000, 170}, {160, 2000, 300}, kNavSolid});
        const auto welt = baueWelt(mitDecke);
        LaufWerte mit = lw;
        mit.kannSpringen = true;
        const LaufPlan p = planeLauf(*welt, start, mit, 0.0, 12000.0);
        const LaufTakt* k = sprungTakt(p);
        const double s3 = d + 50.0;
        const double vx = 200.0 / d * s3;
        const double vz = (56.0 - 24.125) / d * s3 + (d / s3) * 0.5 * 800.0;
        pruefe(k != nullptr && nah(k->sprungTempo[0], vx, 0.05) && nah(k->sprungTempo[2], vz, 0.05) && p.ankunftMs > 0.0,
               "SP2 Decke: 1. Bahn trifft, 2. (shotSpeed - 50) auch, 3. (shotSpeed + 50) geht: " + std::to_string(vx) + " " +
                   std::to_string(vz) + " (" +
                   (k != nullptr ? std::to_string(k->sprungTempo[0]) + " " + std::to_string(k->sprungTempo[2]) : std::string("kein Sprung")) +
                   ", Ankunft " + std::to_string(p.ankunftMs) + ")");
    }
    // SP3
    {
        // c ist ein waypoint_navgoal mit "radius" 8: so gilt c erst nahe als
        // erreicht (mReachedRadius = Max(radius * 3, mRadius * 0.4), NAV::
        // FindPath) - ein Wegpunkt ohne Spuren beim Bau hat den groessten
        // Radius, und UpdatePath naehme c schon 400 vorher vom Pfad.
        std::string text = wegpunkt("a", "-60 0 24", "b") + wegpunkt("d", "600 0 56") + wegpunkt("e", "700 80 56", "d");   // y nicht ueberall 0: sonst hat das Zellraster keine Breite
        text += "{\n\"classname\" \"waypoint\"\n\"targetname\" \"b\"\n\"origin\" \"40 0 24\"\n\"targetJump\" \"c\"\n}\n";
        text += "{\n\"classname\" \"waypoint_navgoal\"\n\"targetname\" \"c\"\n\"origin\" \"200 0 56\"\n\"radius\" \"8\"\n\"target\" \"d\"\n}\n";
        const MapData m = karte(text.c_str());
        const auto mitSpur = baueWelt(absatz);
        auto welt = std::make_shared<NavWelt>(*navWeltAusEntities(m.entities));
        welt->spur = mitSpur->spur;
        welt->boden = mitSpur->boden;
        LaufWerte w3 = lw;
        w3.ziel = {600.0F, 0.0F, 56.0F};
        const LaufPlan rot = planeLauf(*welt, start, w3, 0.0, 15000.0);
        pruefe(rot.ankunftMs < 0.0 && sprungTakt(rot) == nullptr, "SP3a Sprungkante ohne SCF_NAV_CAN_JUMP: ungueltig, kommt nicht an");
        w3.kannSpringen = true;
        const LaufPlan p = planeLauf(*welt, start, w3, 0.0, 15000.0);
        const LaufTakt* k = sprungTakt(p);
        pruefe(k != nullptr && k->t < 500.0 && k->ort[0] < 100.0F && p.ankunftMs > 0.0,
               "SP3b Sprungkante b -> c: STEER::Path springt gleich vor dem Absatz ab und kommt an (" +
                   (k != nullptr ? std::to_string(k->t) + " ms bei x " + std::to_string(k->ort[0]) : std::string("kein Sprung")) +
                   ", Ankunft " + std::to_string(p.ankunftMs) + ")");
        // rc605: navAStar (NAV::FindPath fuer Proben) mit is_valid fuer
        // Springer (g_navigator.cpp:551-556 MD). Eigenes Netz ohne
        // Selbstverbindung (spawnflags 4 = WN_NOAUTOCONNECT): p -> q nur ueber
        // die Sprungkante (oben verbindet NAV a und c selbst); r und s nur, weil
        // NAV ab 4 Knoten ein Netz baut (g_navigator.cpp:1469 ff., size_nodes <= 3).
        const std::string t2 = R"({
"classname" "waypoint"
"targetname" "p"
"origin" "0 0 24"
"spawnflags" "4"
"targetJump" "q"
}
{
"classname" "waypoint"
"targetname" "q"
"origin" "300 40 24"
"spawnflags" "4"
}
{
"classname" "waypoint"
"targetname" "r"
"origin" "-900 600 24"
"spawnflags" "4"
}
{
"classname" "waypoint"
"targetname" "s"
"origin" "-900 900 24"
"spawnflags" "4"
"target" "r"
}
)";
        const MapData m2 = karte(t2.c_str());
        const auto w2 = navWeltAusEntities(m2.entities);
        const int kp = (w2 && w2->netz) ? w2->netz->knotenNamens("p") : -1;
        const int kq = (w2 && w2->netz) ? w2->netz->knotenNamens("q") : -1;
        const bool ohneSprung = w2 && w2->netz && navAStar(*w2->netz, kp, kq);
        std::vector<int> pfadSprung;
        const bool mitSprung = w2 && w2->netz && navAStar(*w2->netz, kp, kq, &pfadSprung, true);
        pruefe(kp > 0 && kq > 0 && !ohneSprung && mitSprung && pfadSprung.size() == 2,
               "SP3c navAStar p -> q: ohne SCF_NAV_CAN_JUMP kein Weg, mit ueber die Sprungkante (" +
                   std::to_string(ohneSprung) + "/" + std::to_string(mitSprung) + ", " + std::to_string(pfadSprung.size()) + " Knoten)");
    }
}

// --- rc605: BS_JUMP (NPC_BSJump, NPC_behavior.cpp:717-962 MD) ----------------
// BJ1: ueber eine Luecke (Boden bis x 100, Plattform ab x 300, Ziel 400 weit auf
// gleicher Hoehe). JS_FACING im ersten Denkbild (Gier 0, Fehler 0 <
// MIN_ANGLE_ERROR) -> BOTH_CROUCH1 (500 ms) -> nach 10 Pmoves bei 550 der
// Sprung: p1 = Figur, xy = (400 - (sqrt(100 + 0) - sqrt(100))) * 0.5 = 200,
// apex 100 ueber ihr, time = sqrt(100 / 400) = 0.5, velocity = (200 / 0.5, 0,
// 0.5 * 800) = (400, 0, 400). Landung nach 1 s bei x 400, BOTH_LAND1 (300 ms),
// dann UpdateGoal -> Ankunft. Ohne BS_JUMP geht sie in die Luecke.
void bsSprung605() {
    std::printf("\n== rc605: BS_JUMP (BJ1) ==\n");
    const std::vector<ProbeKlotz> luecke = {
        {{-2000, -2000, -16}, {100, 2000, 0}, kNavSolid},
        {{300, -2000, -16}, {2000, 2000, 0}, kNavSolid},
        {{-2000, -2000, -1016}, {2000, 2000, -1000}, kNavSolid},
    };
    auto welt = std::make_shared<NavWelt>();
    welt->spur = [luecke](const NavVec& a, const NavVec& mi, const NavVec& ma, const NavVec& b, int, std::uint32_t maske) {
        return probeSpur(luecke, a, mi, ma, b, maske);
    };
    welt->boden = [](float x, float, float zOben, float zUnten, float& z) {
        const float oben = (x < 100.0F || x >= 300.0F) ? 0.0F : -1000.0F;
        if (oben > zOben || oben < zUnten) { return false; }
        z = oben;
        return true;
    };
    LaufWerte lw;
    lw.zielGesetzt = true;
    lw.ziel = {400.0F, 0.0F, 24.125F};
    lw.maxTempo = 300.0F;
    lw.gehTempo = 90.0F;
    lw.hockeMs = 500;
    lw.landMs = 300;
    LaufZustand start;
    start.ort = {0.0F, 0.0F, 24.125F};
    start.amBoden = true;
    const LaufPlan rot = planeLauf(*welt, start, lw, 0.0, 8000.0);
    pruefe(rot.ankunftMs < 0.0, "BJ1a ohne BS_JUMP: geht in die Luecke, kommt nicht an");
    LaufWerte bj = lw;
    bj.bsJump = true;
    const LaufPlan p = planeLauf(*welt, start, bj, 0.0, 8000.0);
    const LaufTakt* sp = nullptr;
    double hocke = -1.0;
    double land = -1.0;
    for (const LaufTakt& k : p.takte) {
        if (k.sprung && sp == nullptr) { sp = &k; }
        if (k.bsAnim == 1 && hocke < 0.0) { hocke = k.bsAnimAb; }
        if (k.bsAnim == 3 && land < 0.0) { land = k.bsAnimAb; }
    }
    pruefe(sp != nullptr && nah(hocke, 50.0, 0.1) && nah(sp->t, 550.0, 0.1) && nah(sp->sprungTempo[0], 400.0, 0.01) &&
               nah(sp->sprungTempo[1], 0.0, 0.01) && nah(sp->sprungTempo[2], 400.0, 0.01),
           "BJ1b BOTH_CROUCH1 bei 50, Sprung bei 550 mit velocity 400 0 400 (" +
               (sp != nullptr ? std::to_string(hocke) + " / " + std::to_string(sp->t) + ": " + std::to_string(sp->sprungTempo[0]) + " " +
                                    std::to_string(sp->sprungTempo[2])
                              : std::string("kein Sprung")) + ")");
    const float xEnde = p.takte.empty() ? 0.0F : p.takte.back().ort[0];
    pruefe(land > 1400.0 && land < 1700.0 && p.ankunftMs >= land + 300.0 && p.ankunftMs <= land + 400.0 && std::fabs(xEnde - 400.0F) < 12.0F,
           "BJ1c landet nach 1 s (BOTH_LAND1 bei " + std::to_string(land) + "), Ankunft nach der Landeanimation (" +
               std::to_string(p.ankunftMs) + " ms, x " + std::to_string(xEnde) + ")");
    // rc605 FU4: die Kette auf den Beinen: BOTH_CROUCH1 (50), PM_Footsteps im
    // Stand, wenn sein Timer im Pmove 500 ablaeuft, PM_JumpForDir BOTH_JUMP1 im
    // Absprung (550), BOTH_INAIR1 ein Denkbild spaeter (600), PM_CrashLand
    // BOTH_LAND1 im Pmove der Landung - NPC_BSJump setzt es ein Denkbild spaeter
    // noch einmal, ohne Neubeginn.
    {
        std::string txt;
        std::size_t iLand = p.takte.size();
        for (std::size_t i = 0; i < p.takte.size(); ++i) {
            const LaufTakt& k = p.takte[i];
            if (k.t > 560.0 && iLand == p.takte.size() && i < p.zustaende.size() && p.zustaende[i].amBoden) { iLand = i; }
            if (k.t < 40.0 || (k.t > 110.0 && k.t < 440.0) || (k.t > 660.0 && iLand == p.takte.size() && k.t < 1300.0)) { continue; }
            if (iLand != p.takte.size() && i > iLand + 1) { break; }
            txt += " " + std::to_string(static_cast<int>(k.t)) + ":" + std::to_string(k.beinAnim) + "@" +
                   std::to_string(static_cast<int>(k.beinAnimAb));
        }
        const auto bei = [&](double t) -> const LaufTakt* {
            for (const LaufTakt& k : p.takte) {
                if (nah(k.t, t, 0.1)) { return &k; }
            }
            return nullptr;
        };
        const LaufTakt* k50 = bei(50.0);
        const LaufTakt* k450 = bei(450.0);
        const LaufTakt* k500 = bei(500.0);
        const LaufTakt* k550 = bei(550.0);
        const LaufTakt* k600 = bei(600.0);
        bool ok = k50 && k450 && k500 && k550 && k600 && iLand > 0 && iLand + 1 < p.takte.size();
        ok = ok && k50->beinAnim == kSaCrouch1 && nah(k50->beinAnimAb, 50.0, 0.1) && k450->beinAnim == kSaCrouch1 &&
             k500->beinAnim == kSaStand1 && k550->beinAnim == kSaJump1 && nah(k550->beinAnimAb, 550.0, 0.1) &&
             k600->beinAnim == kSaInAir1 && nah(k600->beinAnimAb, 600.0, 0.1);
        if (ok) {
            const LaufTakt& kl = p.takte[iLand];
            const LaufTakt& kn = p.takte[iLand + 1];
            ok = p.takte[iLand - 1].beinAnim == kSaInAir1 && kl.beinAnim == kSaLand1 && nah(kl.beinAnimAb, kl.t, 0.1) &&
                 kl.torsoAnim == kSaKeine && kn.beinAnim == kSaLand1 && nah(kn.beinAnimAb, kl.t, 0.1) && kn.bsAnim == 3;
        }
        pruefe(ok, "BJ1d Beine: BOTH_CROUCH1 50, BOTH_STAND1 500, BOTH_JUMP1 550, BOTH_INAIR1 600, BOTH_LAND1 ab der Landung (" +
                       txt + ")");
    }
}

int main(int argc, char** argv) {
    if (argc > 2 && std::strcmp(argv[1], "--bsp") == 0) {
        echteKarte(argv[2]);
        return 0;
    }
    laufenSzene();
    if (argc > 2) {
        laufenEchteDaten(argv[1], argv[2]);
    }
    laufenAblauf();
    drehenSzene();
    drehenAblauf();
    schwerkraftProben();
    navProben();
    reviewProben();
    wegeProben();
    offenePunkte();
    schwierigkeitProben();
    review2Proben();
    leistungEingriffe();
    waendeProben();
    teil3Mover();   // rc601 (bewegung, teil 3)
    teil3Fallen();
    teil3Koerper();
    teil3Patches();
    teil3Winkel();
    regelwerkVerhaltenTakt();   // rc601 integ
    regelwerkDrehTakt();        // rc604 fix604b (A1)
    knotenGrenze();   // rc602 kartenpruefung
    tuerLaufKoerper();   // rc603 fix603
    koerperTaktNachPause();   // rc603 fix603 (dooku5)
    koerperFest();   // rc604 fix604 (col1)
    festWarten();    // rc605 fix605 (TID_RESIZE)
    netzRasterProben();   // rc604 fix604 (md_roc_jedi)
    spruenge605();        // rc605: NPC-Spruenge
    bsSprung605();        // rc605: BS_JUMP
    std::printf("\n%s (%d Fehlschlaege)\n", fehler != 0 ? "FEHLGESCHLAGEN" : "alle Bewegungsproben bestanden", fehler);
    return fehler != 0 ? 1 : 0;
}
